// Framework ILAsm and the Windows PowerShell CLR 4 host are external, process-wide resources.
// Unbounded JUnit 5 fan-out produces nondeterministic empty host failures and occasionally no PE
// output. Keep only the Framework lane exclusive; modern .NET boxes remain parallel.
@ResourceLock("kotlin-dotnet-framework-toolchain")
abstract class AbstractDotNetIlTextTestBase(
    private val parser: FirParser,
    private val validatesCrossAssemblerCompatibility: Boolean = false,
) : AbstractKotlinCompilerDotNetTest() {
    override fun configure(builder: TestConfigurationBuilder): Unit = with(builder) {
        configureDotNetBase(parser, outputExtension = "il")

        dotNetArtifactsHandlersStep {
            if (validatesCrossAssemblerCompatibility) {
                useHandlers(::DotNetCrossAssemblerIlTextHandler)
            } else {
                useHandlers(::DotNetIlTextHandler)
            }
        }
    }
}

open class AbstractFirLightTreeDotNetIlTextTest : AbstractDotNetIlTextTestBase(FirParser.LightTree)

@FirPsiCodegenTest
open class AbstractFirPsiDotNetIlTextTest : AbstractDotNetIlTextTestBase(FirParser.Psi)

open class AbstractFirLightTreeDotNetCrossAssemblerTest :
    AbstractDotNetIlTextTestBase(FirParser.LightTree, validatesCrossAssemblerCompatibility = true)

abstract class AbstractDotNetBoxTestBase(
    private val parser: FirParser,
) : AbstractKotlinCompilerDotNetTest() {
    override fun configure(builder: TestConfigurationBuilder): Unit = with(builder) {
        // The box suite targets modern .NET: the artifact is a dll launched via the signed
        // `dotnet` host (`dotnet exec`), never a directly executed unsigned .exe (see
        // compiler/ir/backend.dotnet/AGENTS.md).
        configureDotNetBase(
            parser,
            outputExtension = "dll",
            target = DotNetTarget.NET10_0,
            additionalSourceProvider = ::DotNetBoxMainSourceProvider,
        )

        dotNetArtifactsHandlersStep {
            useHandlers(::DotNetBoxRunner)
        }
    }

    override fun runTest(filePath: String) {
        val toolchainAvailable =
            DotNetIlAssembler.findModernIlasm() != null && DotNetIlAssembler.findModernDotNetHost() != null
        val message = "Modern .NET toolchain (ilasm + dotnet host) not found; " +
                "provision with compiler/ir/backend.dotnet/tools/provision-dotnet-toolchain.ps1"
        if (dotNetToolchainIsRequired()) {
            check(toolchainAvailable) { "$message (KOTLIN_DOTNET_REQUIRE_TOOLCHAIN is enabled)" }
        } else {
            Assumptions.assumeTrue(toolchainAvailable, message)
        }
        super.runTest(filePath)
    }
}

open class AbstractFirLightTreeDotNetBoxTest : AbstractDotNetBoxTestBase(FirParser.LightTree)

@FirPsiCodegenTest
open class AbstractFirPsiDotNetBoxTest : AbstractDotNetBoxTestBase(FirParser.Psi)

@ResourceLock("kotlin-dotnet-framework-toolchain")
abstract class AbstractDotNetFrameworkBoxTestBase(
    private val parser: FirParser,
) : AbstractKotlinCompilerDotNetTest() {
    override fun configure(builder: TestConfigurationBuilder): Unit = with(builder) {
        configureDotNetBase(
            parser,
            outputExtension = "exe",
            target = DotNetTarget.NET48,
            additionalSourceProvider = ::DotNetBoxMainSourceProvider,
        )

        dotNetArtifactsHandlersStep {
            useHandlers(::DotNetFrameworkBoxRunner)
        }
    }

    override fun runTest(filePath: String) {
        val toolchainAvailable =
            DotNetIlAssembler.findFrameworkIlasm() != null &&
                    DotNetIlAssembler.findFrameworkPowerShellHost() != null
        val message = ".NET Framework toolchain (ILAsm + Windows PowerShell CLR 4 host) not found"
        if (dotNetToolchainIsRequired()) {
            check(toolchainAvailable) { "$message (KOTLIN_DOTNET_REQUIRE_TOOLCHAIN is enabled)" }
        } else {
            Assumptions.assumeTrue(toolchainAvailable, message)
        }
        super.runTest(filePath)
    }
}

open class AbstractFirLightTreeDotNetFrameworkBoxTest : AbstractDotNetFrameworkBoxTestBase(FirParser.LightTree)

@FirPsiCodegenTest
open class AbstractFirPsiDotNetFrameworkBoxTest : AbstractDotNetFrameworkBoxTestBase(FirParser.Psi)

private fun TestConfigurationBuilder.configureDotNetBase(
    parser: FirParser,
    outputExtension: String,
    // NET48 by default: the ilText goldens embed the `.module` directive naming the
    // artifact file, so the ilText suite must keep its historical target/extension untouched.
    target: DotNetTarget = DotNetTarget.NET48,
    additionalSourceProvider: Constructor<AdditionalSourceProvider>? = null,
) {
    with(this) {
        useDirectives(DotNetCodegenDirectives)
        globalDefaults {
            frontend = FrontendKinds.FIR
            targetPlatform = DotNetPlatforms.defaultDotNetPlatform
            targetBackend = TargetBackend.DOTNET
            artifactKind = ArtifactKinds.DotNet
            dependencyKind = DependencyKind.Binary
        }

        // Use the same directive-owned coroutine helpers as the JVM/JS/Wasm shared box corpus.
        // The provider is inert unless a test declares WITH_COROUTINES.
        useAdditionalSourceProviders(::CoroutineHelpersSourceFilesProvider)
        additionalSourceProvider?.let { useAdditionalSourceProviders(it) }

        useConfigurators(
            ::CommonEnvironmentConfigurator,
            ::DotNetEnvironmentConfigurator.bind(outputExtension, target),
        )

        facadeStep(::FirCliDotNetFacade)
        firHandlersStep {
            useHandlers(::NoFirCompilationErrorsHandler)
        }

        facadeStep(::Fir2IrCliDotNetFacade)
        irHandlersStep()

        facadeStep(::BackendCliDotNetFacade)

        configureFirParser(parser)
    }
}

private class FirCliDotNetFacade(
    private val dotNetTestServices: TestServices,
) : FirCliFacade<DotNetFrontendPipelinePhase, DotNetFrontendPipelineArtifact>(
    dotNetTestServices,
    DotNetFrontendPipelinePhase,
) {
    override fun getPartsForDependsOnModules(
        module: TestModule,
        firOutputs: List<SingleModuleFrontendOutput>,
    ): List<FirOutputPartForDependsOnModule> {
        val modulesBySessionName = module.transitiveDependsOnDependencies(includeSelf = true, reverseOrder = true)
            .associateBy { "<${it.name}>" }
        return firOutputs.map { output ->
            val sessionName = output.session.moduleData.name.asString()
            val logicalSessionName = sessionName.removeSuffix("-common")
            output.toTestOutputPart(modulesBySessionName.getValue(logicalSessionName), dotNetTestServices)
        }
    }
}

private class Fir2IrCliDotNetFacade(
    testServices: TestServices,
) : Fir2IrCliFacade<DotNetFir2IrPipelinePhase, DotNetFrontendPipelineArtifact, DotNetFir2IrPipelineArtifact>(
    testServices,
    DotNetFir2IrPipelinePhase,
)

private class BackendCliDotNetFacade(
    testServices: TestServices,
) : BackendFacade<IrBackendInput, BinaryArtifacts.DotNet>(
    testServices,
    BackendKinds.IrBackend,
    ArtifactKinds.DotNet,
) {
    @OptIn(MessageCollectorAccess::class, UnsafeDuringIrConstructionAPI::class)
    override fun transform(module: TestModule, inputArtifact: IrBackendInput): BinaryArtifacts.DotNet {
        require(inputArtifact is Fir2IrCliBasedOutputArtifact<*>) {
            "BackendCliDotNetFacade expects Fir2IrCliBasedOutputArtifact as input, but ${inputArtifact::class} was found"
        }
        val cliArtifact = inputArtifact.cliArtifact
        require(cliArtifact is DotNetFir2IrPipelineArtifact) {
            "BackendCliDotNetFacade expects DotNetFir2IrPipelineArtifact as input, but ${cliArtifact::class} was found"
        }
        val input = cliArtifact.withNewDiagnosticCollector(DiagnosticsCollectorImpl())
        val loweredInput = DotNetKlibInliningPipelinePhase.executePhase(input)
        val genericOwnerRehearsal = System.getProperty(GENERIC_OWNER_REHEARSAL_PROPERTY) == "true"
        if (genericOwnerRehearsal) {
            loweredInput.configuration.dotNetGenericOwnerRehearsal = true
        }
        val callRouteTraceExportPath = System.getProperty(GENERIC_OWNER_CALL_ROUTE_TRACE_EXPORT_PROPERTY)
        if (callRouteTraceExportPath != null && !loweredInput.configuration.dotNetProducesLibrary) {
            check(callRouteTraceExportPath.isNotBlank()) {
                "Generic-owner call-route trace export path must not be blank"
            }
            val traceFunctions = loweredInput.result.irModuleFragment.files
                .flatMap { file -> file.declarations }
                .filterIsInstance<IrSimpleFunction>()
            val recorder = traceFunctions.singleOrNull { function ->
                function.name.asString() == GENERIC_OWNER_CALL_ROUTE_TRACE_RECORDER_NAME
            }
                ?: error("The instrumented generic-owner application lacks its explicit IR trace recorder")
            val flusher = traceFunctions.singleOrNull { function ->
                function.name.asString() == GENERIC_OWNER_CALL_ROUTE_TRACE_FLUSHER_NAME
            }
                ?: error("The instrumented generic-owner application lacks its explicit IR trace flusher")
            loweredInput.configuration.dotNetGenericOwnerCallRouteTraceHooks =
                DotNetGenericOwnerCallRouteTraceHooks(recorder, flusher)
        }
        val metadataInput = if (loweredInput.configuration.dotNetProducesLibrary) {
            DotNetLibraryMetadataSerializationPipelinePhase.executePhase(loweredInput)
        } else {
            loweredInput
        }
        val backendOutput = DotNetBackendPipelinePhase.executePhase(metadataInput)
        check(backendOutput.genericOwnerRehearsal == genericOwnerRehearsal) {
            "The generic-owner rehearsal epoch was not propagated through the backend product"
        }
        val completedOutput = if (loweredInput.configuration.dotNetProducesLibrary) {
            DotNetLibraryMetadataFinalizationPipelinePhase.executePhase(backendOutput)
        } else {
            backendOutput
        }
        check(completedOutput.output.isFile) {
            val messages = (input.configuration.messageCollector as? MessageCollectorForCompilerTests)
                ?.nonSourceMessages
                ?.joinToString("\n")
                .orEmpty()
            "The .NET backend produced no file at ${completedOutput.output.path}:\n$messages"
        }
        System.getProperty(GENERIC_OWNER_REHEARSAL_EXPORT_PROPERTY)?.let { exportPath ->
            check(genericOwnerRehearsal) {
                "A generic-owner rehearsal product can only be exported from the rehearsal epoch"
            }
            val exportDirectory = File(exportPath).apply { mkdirs() }
            completedOutput.output.copyTo(
                exportDirectory.resolve(completedOutput.output.name),
                overwrite = true,
            )
            completedOutput.output.resolveSibling("${completedOutput.output.nameWithoutExtension}.il")
                .takeIf(File::isFile)
                ?.copyTo(
                    exportDirectory.resolve("${completedOutput.output.nameWithoutExtension}.il"),
                    overwrite = true,
                )
        }
        validateGenericOwnerHardestModelPrototype(
            completedOutput.genericOwnerPrototypes,
            completedOutput.genericOwnerCallRoutes,
        )
        validateGenericOwnerRepresentativeArrayCopyPrototype(
            completedOutput.genericOwnerPrototypes,
            completedOutput.genericOwnerCallRoutes,
        )
        validateGenericOwnerRepresentativeOctoTreePrototype(
            completedOutput.genericOwnerPrototypes,
            completedOutput.genericOwnerCallRoutes,
            loweredInput.configuration.dotNetTarget,
            completedOutput.output,
        )
        validateGenericOwnerForeignCSharpOverride(
            genericOwnerRehearsal = genericOwnerRehearsal,
            producesLibrary = loweredInput.configuration.dotNetProducesLibrary,
            target = loweredInput.configuration.dotNetTarget,
            producer = completedOutput.output,
            testDataFile = testServices.moduleStructure.originalTestDataFiles.single(),
            directory = testServices.getOrCreateTempDirectory("generic-owner-foreign-override"),
        )
        physicalizeGenericOwnerRepresentativeOctoTreeCandidate(
            completedOutput.genericOwnerPrototypes,
            completedOutput.genericOwnerCallRoutes,
            loweredInput.configuration.dotNetTarget,
            completedOutput.output,
            testServices.moduleStructure.originalTestDataFiles.single(),
            testServices.getOrCreateTempDirectory("generic-owner-octo-tree-candidate"),
            compilerOutputUsesReifiedOwners = genericOwnerRehearsal,
        )
        validateGenericOwnerOpenNullableArraySignaturePrototype(completedOutput.genericOwnerPrototypes)
        physicalizeGenericOwnerHardestModelPrototype(
            completedOutput.genericOwnerPrototypes,
            completedOutput.genericOwnerCallRoutes,
            loweredInput.configuration.dotNetTarget,
            completedOutput.output,
            testServices.moduleStructure.originalTestDataFiles.single(),
            testServices.getOrCreateTempDirectory("generic-owner-snapshot-physicalizer"),
        )
        if (callRouteTraceExportPath != null && !loweredInput.configuration.dotNetProducesLibrary) {
            val traceExportDirectory = File(callRouteTraceExportPath)
            val traceKey = genericOwnerCallRouteTraceKey(traceExportDirectory)
            if (!genericOwnerCallRouteTraceManifests.containsKey(traceKey)) {
                val resolvedRoutes = completedOutput.genericOwnerCallRoutes.filter { route ->
                    route.routeRequirement !=
                            DotNetGenericOwnerCallRouteRequirement.EXTERNAL_FAMILY_RECORD_REQUIRED
                }
                check(resolvedRoutes.isNotEmpty()) {
                    "The instrumented application has no locally resolved generic-owner call routes"
                }
                prepareGenericOwnerCallRouteTraceExport(
                    traceExportDirectory,
                    DotNetGenericOwnerCallRouteManifestCodec.encode(
                        DotNetGenericOwnerCallRouteManifest.fromResolvedCallRoutes(resolvedRoutes),
                    ),
                )
            }
        }
        return BinaryArtifacts.DotNet(completedOutput.output)
    }
}

private fun validateGenericOwnerOpenNullableArraySignaturePrototype(
    prototypes: List<DotNetGenericOwnerPrototypeSnapshot>,
) {
    val owner = prototypes.singleOrNull { prototype ->
        prototype.ownerName.endsWith("GenericNullableArrayCopier")
    } ?: return
    val systemArray = DotNetGenericOwnerPrototypeTypeSnapshot.systemArrayType()
    check(owner.constructors.single().let { constructor ->
        constructor.parameterSlotDomains == listOf(DotNetGenericOwnerPhysicalSlotDomain.STRICT_OWNER_INPUT) &&
                constructor.exactPathUnboundSignature?.parameterSlots?.singleOrNull()?.let { slot ->
                    slot.type == systemArray && slot.nullableReferenceFlags == listOf(
                        DotNetNullableReferenceFlag.NON_NULL,
                    )
                } == true
    }) {
        "GenericNullableArrayCopier(Array<T?>) must not publish an open CLR T[] constructor: $owner"
    }
    val shiftRight = owner.members.single { member -> member.sourceName == "shiftRight" }
    check(shiftRight.returnSlotDomain == DotNetGenericOwnerPhysicalSlotDomain.STRICT_OWNER_OUTPUT &&
            checkNotNull(shiftRight.exactPathUnboundSignatures).values.all { signature ->
                signature.returnSlot.type == systemArray &&
                        signature.returnSlot.nullableReferenceFlags == listOf(
                            DotNetNullableReferenceFlag.NON_NULL,
                        )
            }) {
        "GenericNullableArrayCopier.shiftRight(): Array<T?> must retain System.Array: $shiftRight"
    }
}

private fun validateGenericOwnerRepresentativeOctoTreePrototype(
    prototypes: List<DotNetGenericOwnerPrototypeSnapshot>,
    callRoutes: List<DotNetGenericOwnerCallRouteSnapshot>,
    target: DotNetTarget,
    producerOutput: File,
) {
    val tree = prototypes.singleOrNull { prototype -> prototype.ownerName == "OctoTree" } ?: return
    val node = prototypes.single { prototype -> prototype.ownerName == "OctoTree.Node" }
    val branch = prototypes.single { prototype -> prototype.ownerName == "OctoTree.Node.Branch" }
    val leaf = prototypes.single { prototype -> prototype.ownerName == "OctoTree.Node.Leaf" }
    val nodeCarrier = node.logicalBindingKey?.let { logicalKey ->
        DotNetGenericOwnerPrototypeTypeSnapshot.logicalGenericClassifier(
            logicalClassifierKey = logicalKey,
            arguments = listOf(DotNetGenericOwnerPrototypeTypeSnapshot.ownerParameter(0)),
        )
    }
    prototypes.singleOrNull { prototype ->
        prototype.ownerName == "GenericOwnerBareNullableSlot"
    }?.let { nullableControl ->
        check(nullableControl.states.single { state -> state.fieldName == "value" }.let { state ->
            state.requirement == DotNetGenericOwnerStateCarrierRequirement.SEMANTIC_OBJECT_REQUIRED &&
                    state.initializers.singleOrNull()?.kind ==
                    DotNetGenericOwnerPrototypeStateInitializerKind.DEFAULT_NULL_REFERENCE &&
                    state.writes.single { write ->
                        write.producerName == "<field-initializer:value>"
                    }.provenance == DotNetGenericOwnerWriteValueProvenance.SEMANTIC_OBJECT
        }) {
            "Bare T? null state must remain semantic across value/reference substitutions: " +
                    nullableControl.states
        }
    }
    check(branch.constructors.count { constructor -> !constructor.delegatesToThis } == 1 &&
            branch.constructors.count { constructor -> constructor.delegatesToThis } == 1) {
        "OctoTree.Branch must retain one exact base and one this-delegating constructor root: " +
                branch.constructors
    }
    check(tree.states.single { state -> state.fieldName == "root" }.let { root ->
        if (nodeCarrier == null) {
            root.requirement == DotNetGenericOwnerStateCarrierRequirement.SEMANTIC_OBJECT_REQUIRED &&
                    root.exactTypedCarrierType == null &&
                    root.physicalCarrierNullableReferenceFlags == listOf(
                        DotNetNullableReferenceFlag.NULLABLE,
                    ) &&
                    root.initializers.all { initializer ->
                        initializer.kind == DotNetGenericOwnerPrototypeStateInitializerKind.DEFAULT_NULL_REFERENCE
                    }
        } else {
            root.requirement ==
                    DotNetGenericOwnerStateCarrierRequirement.TYPED_STORAGE_PRODUCER_GRAPH_PROVEN &&
                    root.exactTypedCarrierType == nodeCarrier &&
                    root.physicalCarrierNullableReferenceFlags == listOf(
                        DotNetNullableReferenceFlag.NULLABLE,
                        DotNetNullableReferenceFlag.NON_NULL,
                    ) &&
                    root.initializers.all { initializer ->
                        initializer.kind == DotNetGenericOwnerPrototypeStateInitializerKind.DEFAULT_NULL_REFERENCE
                    } && root.writes.map { write -> write.producerName }.toSet() ==
                    setOf("<set-root>", "<field-initializer:root>") &&
                    root.writes.all { write ->
                        write.provenance == DotNetGenericOwnerWriteValueProvenance.PHYSICALLY_TYPED
                    }
        }
    }) {
        "OctoTree.root must remain semantic without a physical family and become a proven " +
                "nullable Node<T> reference with one: ${tree.states}"
    }
    check(tree.states.single { state -> state.fieldName == "depth" }.let { depth ->
        depth.isFinal &&
                depth.requirement ==
                DotNetGenericOwnerStateCarrierRequirement.DECLARATION_INDEPENDENT_STORAGE &&
                depth.exactTypedCarrierType == DotNetGenericOwnerPrototypeTypeSnapshot.int32Type() &&
                depth.initializers.singleOrNull()?.let { initializer ->
                    initializer.kind ==
                            DotNetGenericOwnerPrototypeStateInitializerKind.POSITIONAL_CONSTRUCTOR_PARAMETER &&
                            initializer.constructorParameterIndex == 0
                } == true
    } && tree.states.single { state -> state.fieldName == "actual" }.let { actual ->
        !actual.isFinal &&
                actual.requirement ==
                DotNetGenericOwnerStateCarrierRequirement.DECLARATION_INDEPENDENT_STORAGE &&
                actual.exactTypedCarrierType == DotNetGenericOwnerPrototypeTypeSnapshot.booleanType() &&
                actual.initializers.singleOrNull()?.kind ==
                DotNetGenericOwnerPrototypeStateInitializerKind.DEFAULT_ZERO_VALUE
    } && "actual" in tree.members.single { member -> member.sourceName == "set" }.transitiveStateWriteNames
    ) {
        "OctoTree declaration-independent state was omitted or widened: ${tree.states}"
    }
    if (tree.logicalBindingKey != null) {
        check(branch.members.filter { member ->
            member.logicalBindingKey == null &&
                    member.physicalVisibility == DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE &&
                    !member.isPropertyAccessor && !member.isFakeOverride
        }.singleOrNull()?.let { helper ->
            helper.sourceName == "canClusterize" &&
                    helper.roles == setOf(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY) &&
                    helper.exactPathUnboundSignatures?.get(
                        DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
                    )?.let { signature ->
                        signature.returnSlot.type == DotNetGenericOwnerPrototypeTypeSnapshot.booleanType() &&
                                signature.parameterSlots.singleOrNull()?.type ==
                                DotNetGenericOwnerPrototypeTypeSnapshot.ownerParameter(0)
                    } == true
        } == true) {
            "OctoTree.Branch.canClusterize must remain one private non-KLIB typed helper: ${branch.members}"
        }
    }
    check(branch.states.single { state -> state.fieldName == "nodes" }.let { nodes ->
        nodes.isFinal &&
                nodes.requirement == DotNetGenericOwnerStateCarrierRequirement.TYPED_STORAGE_PRODUCER_GRAPH_PROVEN &&
                nodes.exactTypedCarrierType == nodeCarrier?.let {
                    DotNetGenericOwnerPrototypeTypeSnapshot.szArray(it)
                } &&
                nodes.physicalCarrierNullableReferenceFlags == if (nodeCarrier == null) {
                    null
                } else {
                    listOf(
                        DotNetNullableReferenceFlag.NON_NULL,
                        DotNetNullableReferenceFlag.NULLABLE,
                        DotNetNullableReferenceFlag.NON_NULL,
                    )
                } &&
                nodes.initializers.singleOrNull()?.let { initializer ->
                    initializer.producerName == "<field-initializer:nodes>" && if (nodeCarrier == null) {
                        initializer.kind == DotNetGenericOwnerPrototypeStateInitializerKind.UNSUPPORTED &&
                                initializer.fixedElementCount == null
                    } else {
                        initializer.kind ==
                                DotNetGenericOwnerPrototypeStateInitializerKind.FIXED_ZEROED_SZ_ARRAY &&
                                initializer.fixedElementCount == 8
                    }
                } == true &&
                nodes.writes.singleOrNull()?.let { write ->
                    write.producerName == "<field-initializer:nodes>" &&
                            write.provenance == DotNetGenericOwnerWriteValueProvenance.PHYSICALLY_TYPED
                } == true
    }) {
        "OctoTree.Branch.nodes must retain its exact owner-classifier array producer: ${branch.states}"
    }
    check(leaf.states.single { state -> state.fieldName == "value" }.let { value ->
        !value.isFinal &&
                value.requirement == DotNetGenericOwnerStateCarrierRequirement.TYPED_STORAGE_PRODUCER_GRAPH_PROVEN &&
                value.exactTypedCarrierType == DotNetGenericOwnerPrototypeTypeSnapshot.ownerParameter(0) &&
                value.physicalCarrierNullableReferenceFlags == listOf(
                    DotNetNullableReferenceFlag.NON_NULL,
                )
    }) {
        "OctoTree.Leaf.value must retain typed owner state: ${leaf.states}"
    }
    val nodesGetter = branch.members.single { member ->
        member.sourceName.contains("nodes", ignoreCase = true) && member.parameterSlotDomains.isEmpty()
    }
    val depthGetter = tree.members.single { member -> member.sourceName == "<get-depth>" }
    val leafValueAccessors = leaf.members.filter { member -> member.physicalPropertyName == "value" }
    check(depthGetter.propertyAccessorKind == DotNetGenericOwnerPropertyAccessorKind.GETTER &&
            depthGetter.physicalPropertyName == "depth" &&
            nodesGetter.propertyAccessorKind == DotNetGenericOwnerPropertyAccessorKind.GETTER &&
            nodesGetter.physicalPropertyName == "nodes" &&
            leafValueAccessors.map { member -> member.propertyAccessorKind }.toSet() ==
            DotNetGenericOwnerPropertyAccessorKind.entries.toSet()) {
        "The OctoTree prototype lost its compiler-derived CLR property/accessor identities"
    }
    val get = tree.members.single { member -> member.sourceName == "get" }
    check(get.typedRetainsOwnerDependentOutput && get.semanticErasesOwnerDependentOutput &&
            get.returnSlotDomain == DotNetGenericOwnerPhysicalSlotDomain.STRICT_OWNER_OUTPUT &&
            checkNotNull(get.exactPathUnboundSignatures).values.all { signature ->
                signature.returnSlot.type == DotNetGenericOwnerPrototypeTypeSnapshot.objectType() &&
                        signature.returnSlot.nullableReferenceFlags == listOf(
                            DotNetNullableReferenceFlag.NULLABLE,
                        )
            }) {
        "OctoTree.get(): T? must use one truthful object carrier for nullable value/reference results: $get"
    }
    node.logicalBindingKey?.let { nodeKey ->
        val nodesGetterSignatures = checkNotNull(nodesGetter.exactPathUnboundSignatures) {
            "OctoTree.Branch.nodes must retain a complete path-unbound signature family: $nodesGetter"
        }
        check(nodesGetterSignatures.getValue(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY).returnSlot.type ==
                nodeCarrier?.let(DotNetGenericOwnerPrototypeTypeSnapshot::szArray) &&
                nodesGetterSignatures.filterKeys { role ->
                    role != DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY
                }.values.all { signature ->
                    signature.returnSlot.type == DotNetGenericOwnerPrototypeTypeSnapshot.systemArrayType()
                }) {
            "OctoTree.Branch.nodes getter lost its typed constructed vector or semantic array carrier: $nodesGetter"
        }
        val nodesType = checkNotNull(branch.states.single { state -> state.fieldName == "nodes" }.exactTypedCarrierType)
        check(runCatching { nodesType.bindProducerTypes(emptyMap()) }.isFailure) {
            "OctoTree.Branch.nodes bound without a selected Node TypeDef path"
        }
        val nodePath = listOf("KotlinRepresentativeCandidate", "OctoTreeNode")
        val physicalOwnerPaths = mapOf(nodeKey to nodePath)
        val boundNodesGetter = nodesGetterSignatures.getValue(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY)
        check(runCatching { boundNodesGetter.bindProducerTypes(emptyMap()) }.isFailure) {
            "OctoTree.Branch.nodes getter bound without a selected Node TypeDef path"
        }
        check(boundNodesGetter.bindProducerTypes(physicalOwnerPaths).returnSlot.type ==
                nodesType.bindProducerTypes(physicalOwnerPaths)) {
            "OctoTree.Branch.nodes getter did not bind the same recursive vector as its state"
        }
        check(nodesType.bindProducerTypes(mapOf(nodeKey to nodePath)) ==
                DotNetGenericOwnerPhysicalTypeExpressionRecord.szArray(
                    DotNetGenericOwnerPhysicalTypeExpressionRecord.producerType(
                        typePath = nodePath,
                        category = DotNetGenericOwnerPhysicalNamedTypeCategory.CLASS,
                        arguments = listOf(DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(0)),
                    ),
                )) {
            "OctoTree.Branch.nodes did not bind its logical recursive classifier exactly"
        }
    }
    tree.logicalBindingKey?.let { treeKey ->
        val nodeKey = checkNotNull(node.logicalBindingKey)
        val artifact = createGenericOwnerRepresentativeOctoTreePhysicalFamilyArtifact(
            prototypes = prototypes,
            producerFingerprint = DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(producerOutput.readBytes()),
            target = target,
        )
        val encoded = DotNetGenericOwnerPhysicalFamilyCodec.encode(artifact)
        val decoded = DotNetGenericOwnerPhysicalFamilyCodec.decode(
            encoded,
            expectedProducerFingerprint = artifact.producerFingerprint,
            expectedTargetProfile = artifact.targetProfile,
        )
        val expectedOwners = listOf(tree, node, branch, leaf).associateBy { prototype ->
            checkNotNull(prototype.logicalBindingKey)
        }
        check(DotNetGenericOwnerPhysicalFamilyCodec.encode(decoded) == encoded &&
                decoded.owners.map { owner -> owner.logicalOwnerKey }.toSet() == expectedOwners.keys &&
                decoded.owners.all { owner ->
                    val prototype = expectedOwners.getValue(owner.logicalOwnerKey)
                    owner.physicalVisibility == prototype.physicalVisibility &&
                            owner.physicalDispatch == prototype.physicalDispatch
                }) {
            "The complete OctoTree physical family lost an owner declaration envelope"
        }
        val treeOwner = decoded.requirePhysicalFamily(treeKey)
        val nodeOwner = decoded.requirePhysicalFamily(nodeKey)
        check(nodeOwner.physicalDispatch == DotNetGenericOwnerPhysicalTypeDispatch.SEALED &&
                nodeOwner.constructors.isNotEmpty() && nodeOwner.constructors.all { constructor ->
                    constructor.visibility ==
                            DotNetGenericOwnerPhysicalConstructorVisibility.FAMILY_AND_ASSEMBLY
                }) {
            "OctoTree.Node did not close sealed construction to its producer family: $nodeOwner"
        }
        check(runCatching {
            nodeOwner.copy(constructors = nodeOwner.constructors.map { constructor ->
                constructor.copy(visibility = DotNetGenericOwnerPhysicalConstructorVisibility.FAMILY)
            })
        }.isFailure) {
            "The recursive OctoTree family accepted externally subclassable sealed construction"
        }
        val rootState = treeOwner.states.single { state -> state.logicalFieldName == "root" }
        val privateRootMethods = rootState.accessPaths.map { access -> access.physicalMethod }.toSet()
        val rootPhysicalType = DotNetGenericOwnerPhysicalTypeExpressionRecord.producerType(
            typePath = nodeOwner.physicalOwnerPath,
            category = DotNetGenericOwnerPhysicalNamedTypeCategory.CLASS,
            arguments = listOf(DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(0)),
        )
        check(rootState.requirement ==
                DotNetGenericOwnerStateCarrierRequirement.TYPED_STORAGE_PRODUCER_GRAPH_PROVEN &&
                rootState.physicalType == rootPhysicalType &&
                rootState.nullableReferenceFlags == listOf(
                    DotNetNullableReferenceFlag.NULLABLE,
                    DotNetNullableReferenceFlag.NON_NULL,
                ) &&
                rootState.accessPaths.map { access -> access.operation }.toSet() ==
                DotNetGenericOwnerPhysicalStateAccessOperation.entries.toSet() &&
                rootState.accessPaths.all { access ->
                    access.bindingKind ==
                            DotNetGenericOwnerPhysicalStateAccessBindingKind.PRODUCER_PRIVATE_METHOD &&
                            access.physicalVisibility == DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE &&
                            access.physicalMethod.physicalOwnerPath == treeOwner.physicalOwnerPath
                } && treeOwner.reflection.callables.none { callable ->
                    callable.physicalMethods.any { method -> method in privateRootMethods }
        }) {
            "OctoTree.root did not bind to hidden producer-private Node<T> state access: $rootState"
        }
        val depthState = treeOwner.states.single { state -> state.logicalFieldName == "depth" }
        val actualState = treeOwner.states.single { state -> state.logicalFieldName == "actual" }
        val depthProperty = treeOwner.properties.single()
        check(depthProperty.physicalPropertyName == checkNotNull(depthGetter.physicalPropertyName) &&
                depthProperty.physicalType == DotNetGenericOwnerPhysicalTypeExpressionRecord.int32Type() &&
                depthProperty.getterRoute == DotNetGenericOwnerPhysicalPropertyGetterRoute.TYPED_ENTRY &&
                depthProperty.setterRoute == DotNetGenericOwnerPhysicalPropertySetterRoute.ABSENT &&
                depthProperty.getterLogicalMemberKey == depthGetter.logicalBindingKey &&
                depthProperty.setterPhysicalMethod == null) {
            "OctoTree.depth did not retain one exact getter-only CLR Property row: $depthProperty"
        }
        check(depthState.requirement ==
                DotNetGenericOwnerStateCarrierRequirement.DECLARATION_INDEPENDENT_STORAGE &&
                depthState.physicalType == DotNetGenericOwnerPhysicalTypeExpressionRecord.int32Type() &&
                depthState.isInitOnly && depthState.initializers.singleOrNull()?.let { initializer ->
                    initializer.kind ==
                            DotNetGenericOwnerPhysicalStateInitializerKind.POSITIONAL_CONSTRUCTOR_PARAMETER &&
                            initializer.constructorParameterIndex == 0
                } == true && actualState.requirement ==
                DotNetGenericOwnerStateCarrierRequirement.DECLARATION_INDEPENDENT_STORAGE &&
                actualState.physicalType == DotNetGenericOwnerPhysicalTypeExpressionRecord.booleanType() &&
                !actualState.isInitOnly && actualState.initializers.isEmpty()) {
            "OctoTree declaration-independent physical state is incomplete: $depthState / $actualState"
        }
        val branchOwner = decoded.requirePhysicalFamily(checkNotNull(branch.logicalBindingKey))
        val branchImplementationMethod = branchOwner.implementationMethods.singleOrNull()
        check(branchImplementationMethod?.let { helper ->
            helper.visibility == DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE &&
                    helper.dispatch == DotNetGenericOwnerPhysicalMemberDispatch.FINAL &&
                    helper.physicalMethod.signature.returnSlot.type ==
                    DotNetGenericOwnerPhysicalTypeExpressionRecord.booleanType() &&
                    helper.physicalMethod.signature.parameterSlots.singleOrNull()?.type ==
                    DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(0) &&
                    decoded.reflectionCallableForExactPhysicalMethodOrNull(
                        branchOwner.logicalOwnerKey,
                        helper.physicalMethod,
                    ) == null
        } == true) {
            "OctoTree.Branch private helper escaped or disappeared: ${branchOwner.implementationMethods}"
        }
        val nodesState = branchOwner.states.single { state -> state.logicalFieldName == "nodes" }
        val nodesInitializer = nodesState.initializers.single()
        val nodesProperty = branchOwner.properties.single()
        check(nodesState.isInitOnly && nodesState.physicalType == checkNotNull(branch.states.single { state ->
            state.fieldName == "nodes"
        }.exactTypedCarrierType).bindProducerTypes(physicalOwnerPathsByLogicalKey = mapOf(
            checkNotNull(node.logicalBindingKey) to decoded.requirePhysicalFamily(nodeKey).physicalOwnerPath,
        )) && nodesState.nullableReferenceFlags == listOf(
            DotNetNullableReferenceFlag.NON_NULL,
            DotNetNullableReferenceFlag.NULLABLE,
            DotNetNullableReferenceFlag.NON_NULL,
        ) && nodesInitializer.kind == DotNetGenericOwnerPhysicalStateInitializerKind.FIXED_ZEROED_SZ_ARRAY &&
                nodesInitializer.fixedElementCount == 8 &&
                nodesInitializer.logicalConstructorKeys == branchOwner.constructors.filter { constructor ->
                    constructor.delegation.kind == DotNetGenericOwnerConstructorDelegationKind.BASE
                }.map { constructor -> constructor.logicalConstructorKey }.sorted() &&
                nodesState.accessPaths.single().operation ==
                DotNetGenericOwnerPhysicalStateAccessOperation.READ) {
            "OctoTree.Branch.nodes lost its recursive typed vector/init/access join: $nodesState"
        }
        check(nodesProperty.physicalPropertyName == "nodes" &&
                nodesProperty.physicalType == nodesState.physicalType &&
                nodesProperty.nullableReferenceFlags == nodesState.nullableReferenceFlags &&
                nodesProperty.getterRoute == DotNetGenericOwnerPhysicalPropertyGetterRoute.TYPED_ENTRY &&
                nodesProperty.setterRoute == DotNetGenericOwnerPhysicalPropertySetterRoute.ABSENT &&
                nodesProperty.getterLogicalMemberKey == nodesGetter.logicalBindingKey &&
                nodesProperty.setterPhysicalMethod == null) {
            "OctoTree.Branch.nodes did not retain one exact recursive getter Property row: $nodesProperty"
        }
        val leafOwner = decoded.requirePhysicalFamily(checkNotNull(leaf.logicalBindingKey))
        val leafValueState = leafOwner.states.single { state -> state.logicalFieldName == "value" }
        val leafValueProperty = leafOwner.properties.single()
        check(!leafValueState.isInitOnly &&
                leafValueState.physicalType == DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(0) &&
                leafValueState.nullableReferenceFlags == listOf(
                    DotNetNullableReferenceFlag.NON_NULL,
                ) &&
                leafValueState.initializers.singleOrNull()?.let { initializer ->
                    initializer.kind ==
                            DotNetGenericOwnerPhysicalStateInitializerKind.POSITIONAL_CONSTRUCTOR_PARAMETER &&
                            initializer.constructorParameterIndex == 0 &&
                            initializer.fixedElementCount == null &&
                            initializer.logicalConstructorKeys == listOf(
                                leafOwner.constructors.single().logicalConstructorKey,
                            )
                } == true) {
            "OctoTree.Leaf.value lost its true CLR GenericParam state/constructor initialization: $leafValueState"
        }
        check(leafValueProperty.physicalPropertyName == "value" &&
                leafValueProperty.physicalType ==
                DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(0) &&
                leafValueProperty.nullableReferenceFlags == leafValueState.nullableReferenceFlags &&
                leafValueProperty.getterRoute == DotNetGenericOwnerPhysicalPropertyGetterRoute.TYPED_ENTRY &&
                leafValueProperty.setterRoute == DotNetGenericOwnerPhysicalPropertySetterRoute.TYPED_ENTRY &&
                leafValueProperty.getterPhysicalMethod != null &&
                leafValueProperty.setterPhysicalMethod != null) {
            "OctoTree.Leaf.value did not retain one get/set !T CLR Property row: $leafValueProperty"
        }
        check(runCatching {
            leafOwner.copy(properties = leafOwner.properties + leafValueProperty)
        }.isFailure) {
            "The recursive OctoTree family accepted a duplicate Property row"
        }
        val leafReadCapability = leafOwner.members.single { member ->
            member.logicalMemberKey == leafValueProperty.getterLogicalMemberKey
        }.slots.single { slot -> slot.role == DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER }
        check(runCatching {
            leafOwner.copy(properties = listOf(DotNetGenericOwnerPhysicalPropertyRecord(
                physicalPropertyName = leafValueProperty.physicalPropertyName,
                physicalType = leafReadCapability.signature.returnSlot.type,
                getterLogicalMemberKey = leafValueProperty.getterLogicalMemberKey,
                getterPhysicalMethod = DotNetGenericOwnerPhysicalMethodIdentityRecord(
                    leafReadCapability.physicalOwnerPath,
                    leafReadCapability.physicalMethodName,
                    leafReadCapability.signature,
                ),
                setterLogicalMemberKey = null,
                setterPhysicalMethod = null,
            )))
        }.isFailure) {
            "The recursive OctoTree family exposed a capability dispatcher as a CLR property accessor"
        }
        check(runCatching {
            leafOwner.copy(properties = listOf(leafValueProperty.copy(
                nullableReferenceFlags = listOf(DotNetNullableReferenceFlag.NULLABLE),
            )))
        }.isFailure) {
            "The recursive OctoTree family accepted a property/accessor nullability mismatch"
        }
        check(runCatching {
            leafOwner.copy(states = leafOwner.states.map { state ->
                if (state.logicalFieldName != "value") state else state.copy(
                    nullableReferenceFlags = listOf(DotNetNullableReferenceFlag.NULLABLE),
                )
            })
        }.isFailure) {
            "The recursive OctoTree family accepted a state/access-path nullability mismatch"
        }
        val partialPropertyArtifact = encoded.lineSequence().joinToString("\n", postfix = "\n") { line ->
            val fields = line.split('\t').toMutableList()
            if (fields.firstOrNull() == "W" && fields[4] != "-") fields[5] = "-"
            fields.joinToString("\t")
        }
        check(runCatching {
            DotNetGenericOwnerPhysicalFamilyCodec.decode(
                partialPropertyArtifact,
                expectedProducerFingerprint = artifact.producerFingerprint,
                expectedTargetProfile = artifact.targetProfile,
            )
        }.isFailure) {
            "The recursive OctoTree codec accepted a partial physical property accessor"
        }
        check(runCatching {
            artifact.copy(owners = artifact.owners.map { owner ->
                if (owner.logicalOwnerKey != leafOwner.logicalOwnerKey) {
                    owner
                } else {
                    owner.copy(states = owner.states.map { state ->
                        if (state.logicalFieldName != "value") {
                            state
                        } else {
                            state.copy(
                                initializers = state.initializers.map { initializer ->
                                    initializer.copy(constructorParameterIndex = 1)
                                },
                            )
                        }
                    })
                }
            })
        }.isFailure) {
            "The recursive OctoTree family accepted a state/constructor-parameter mismatch"
        }
        check(runCatching {
            artifact.copy(owners = artifact.owners.map { owner ->
                if (owner.logicalOwnerKey != branchOwner.logicalOwnerKey) {
                    owner
                } else {
                    val occupied = owner.members.first().slots.first()
                    owner.copy(implementationMethods = listOf(
                        checkNotNull(branchImplementationMethod).copy(
                            physicalMethod = DotNetGenericOwnerPhysicalMethodIdentityRecord(
                                occupied.physicalOwnerPath,
                                occupied.physicalMethodName,
                                occupied.signature,
                            ),
                        ),
                    ))
                }
            })
        }.isFailure) {
            "The recursive OctoTree family accepted an implementation/logical MethodDef collision"
        }
        val relabeled = prototypes.map { prototype ->
            if (prototype.ownerName !in expectedOwners.values.map { owner -> owner.ownerName }.toSet()) {
                prototype
            } else {
                prototype.copy(members = prototype.members.mapIndexed { index, member ->
                    member.copy(sourceName = "octoDiagnosticLabelMustNotOwnAbi$index")
                })
            }
        }
        check(createGenericOwnerRepresentativeOctoTreePhysicalFamilyArtifact(
            relabeled,
            artifact.producerFingerprint,
            target,
        ) == artifact) {
            "Changing OctoTree diagnostic member labels changed its physical ABI"
        }
        check(runCatching {
            artifact.copy(owners = artifact.owners.filterNot { owner -> owner.logicalOwnerKey == nodeKey })
        }.isFailure) {
            "The recursive OctoTree artifact accepted a missing Node physical family"
        }
        check(runCatching {
            artifact.copy(owners = artifact.owners.map { owner ->
                if (owner.logicalOwnerKey != branchOwner.logicalOwnerKey) {
                    owner
                } else {
                    owner.copy(states = owner.states.map { state ->
                        if (state.logicalFieldName != "nodes") {
                            state
                        } else {
                            state.copy(
                                physicalType = DotNetGenericOwnerPhysicalTypeExpressionRecord.szArray(
                                    DotNetGenericOwnerPhysicalTypeExpressionRecord.producerType(
                                        typePath = listOf("KotlinRepresentativeCandidate", "PhantomNode"),
                                        category = DotNetGenericOwnerPhysicalNamedTypeCategory.CLASS,
                                        arguments = listOf(
                                            DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(0),
                                        ),
                                    ),
                                ),
                            )
                        }
                    })
                }
            })
        }.isFailure) {
            "The recursive OctoTree family accepted an unrecorded producer TypeDef path"
        }
    }
    val routeCounts = callRoutes.groupingBy { route -> route.routeRequirement }.eachCount()
    check(callRoutes.any { route ->
        route.callerName == "OctoTree.Node.Branch.<init>" &&
                route.calleeOwnerName == "OctoTree.Node.Branch" &&
                route.calleeName == "<get-nodes>" &&
                route.receiverProvenance == DotNetGenericOwnerCallReceiverProvenance.EXACT_CONSTRUCTION &&
                route.routeRequirement == DotNetGenericOwnerCallRouteRequirement.EXACT_TYPED_ENTRY
    }) {
        "The recursive OctoTree constructor lost its exact newly-constructed receiver route"
    }
    check(routeCounts == mapOf(
        // The same-compilation driver contributes four exact calls. The Branch constructor's
        // read of producer-proven `nodes` is also exact: its receiver is the newly constructed
        // physical owner, never a projected value supplied through a Kotlin call boundary. A
        // published producer owns only the unchanged OctoTree source; its separately compiled
        // consumer owns the four driver calls.
        DotNetGenericOwnerCallRouteRequirement.EXACT_TYPED_ENTRY to
                if (tree.logicalBindingKey == null) 26 else 22,
        DotNetGenericOwnerCallRouteRequirement.SEMANTIC_CAPABILITY to 8,
        DotNetGenericOwnerCallRouteRequirement.EXTERNAL_FAMILY_RECORD_REQUIRED to 9,
    )) {
        "The representative OctoTree static call-route census changed: $routeCounts"
    }
}

/**
 * Test-owned physicalization of the decoded recursive OctoTree candidate. Physical declaration,
 * signature, inheritance, constructor, state, and private-helper identities come from the record;
 * the C# producer implements the complete source algorithms. Production emission cannot observe
 * this product.
 */
private fun physicalizeGenericOwnerRepresentativeOctoTreeCandidate(
    prototypes: List<DotNetGenericOwnerPrototypeSnapshot>,
    callRoutes: List<DotNetGenericOwnerCallRouteSnapshot>,
    target: DotNetTarget,
    erasedProducerOutput: File,
    applicationSource: File,
    directory: File,
    compilerOutputUsesReifiedOwners: Boolean,
) {
    val treePrototype = prototypes.singleOrNull { prototype -> prototype.ownerName == "OctoTree" }
        ?: return
    val treeLogicalKey = treePrototype.logicalBindingKey ?: return
    val nodePrototype = prototypes.singleOrNull { prototype -> prototype.ownerName == "OctoTree.Node" }
        ?: return
    val nodeLogicalKey = nodePrototype.logicalBindingKey ?: return
    val leafPrototype = prototypes.single { prototype -> prototype.ownerName == "OctoTree.Node.Leaf" }
    val leafLogicalKey = checkNotNull(leafPrototype.logicalBindingKey)
    val branchPrototype = prototypes.single { prototype -> prototype.ownerName == "OctoTree.Node.Branch" }
    val branchLogicalKey = checkNotNull(branchPrototype.logicalBindingKey)
    val artifact = createGenericOwnerRepresentativeOctoTreePhysicalFamilyArtifact(
        prototypes = prototypes,
        producerFingerprint = DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(
            erasedProducerOutput.readBytes(),
        ),
        target = target,
    )
    val encodedArtifact = DotNetGenericOwnerPhysicalFamilyCodec.encode(artifact)
    val decoded = DotNetGenericOwnerPhysicalFamilyCodec.decode(
        encodedArtifact,
        expectedProducerFingerprint = artifact.producerFingerprint,
        expectedTargetProfile = artifact.targetProfile,
    )
    val tree = decoded.requirePhysicalFamily(treeLogicalKey)
    val node = decoded.requirePhysicalFamily(nodeLogicalKey)
    val leaf = decoded.requirePhysicalFamily(leafLogicalKey)
    val branch = decoded.requirePhysicalFamily(branchLogicalKey)
    val reflectedPhysicalMethods = decoded.owners.flatMap { owner ->
        owner.reflection.callables.flatMap { callable ->
            callable.physicalMethods.map { physicalMethod -> Triple(owner, callable, physicalMethod) }
        }
    }
    check(reflectedPhysicalMethods.isNotEmpty() && reflectedPhysicalMethods.all { reflectedMethod ->
        val owner = reflectedMethod.first
        val callable = reflectedMethod.second
        val physicalMethod = reflectedMethod.third
        decoded.reflectionCallableForExactPhysicalMethodOrNull(
            owner.logicalOwnerKey,
            physicalMethod,
        )?.let { normalization ->
            normalization.classifier == owner.reflection &&
                    normalization.callable == callable &&
                    normalization.physicalMethod == physicalMethod
        } == true && decoded.reflectionCallableForLogicalMemberOrNull(callable.logicalMemberKey) == callable
    } && decoded.owners.all { owner ->
        owner.states.flatMap { state -> state.accessPaths }.filter { access ->
            access.bindingKind == DotNetGenericOwnerPhysicalStateAccessBindingKind.PRODUCER_PRIVATE_METHOD
        }.all { access ->
            decoded.reflectionCallableForExactPhysicalMethodOrNull(
                owner.logicalOwnerKey,
                access.physicalMethod,
            ) == null
        }
    }) {
        "The decoded OctoTree family did not collapse every physical MethodDef to one logical callable"
    }
    check(decoded.owners.all { owner ->
        decoded.reflectionClassifierForExactOpenTypeDefinitionOrNull(
            owner.reflection.physicalOpenTypeDefinition,
        ) == owner.reflection && decoded.reflectionClassifierForExactOpenTypeDefinitionOrNull(
            owner.reflection.physicalOpenTypeDefinition.copy(
                physicalTypePath = checkNotNull(owner.physicalCapabilityOwnerPath),
                genericArity = owner.genericArity,
            ),
        ) == null
    }) {
        "The decoded OctoTree family exposed a capability TypeDef as a logical Kotlin classifier"
    }
    val treeConstructor = tree.constructors.single()
    val nodeConstructor = node.constructors.single()
    val leafConstructor = leaf.constructors.single()
    val branchBaseConstructor = branch.constructors.single { constructor ->
        constructor.delegation.kind == DotNetGenericOwnerConstructorDelegationKind.BASE
    }
    val branchThisConstructor = branch.constructors.single { constructor ->
        constructor.delegation.kind == DotNetGenericOwnerConstructorDelegationKind.THIS
    }
    val leafState = leaf.states.single { state -> state.logicalFieldName == "value" }
    val leafInitializer = leafState.initializers.single()
    val leafParameterIndex = checkNotNull(leafInitializer.constructorParameterIndex)
    val branchState = branch.states.single { state -> state.logicalFieldName == "nodes" }
    val branchInitializer = branchState.initializers.single()
    val branchElementType = branchState.physicalType.arguments.singleOrNull()
    val rootState = tree.states.single { state -> state.logicalFieldName == "root" }
    val depthState = tree.states.single { state -> state.logicalFieldName == "depth" }
    val actualState = tree.states.single { state -> state.logicalFieldName == "actual" }
    val branchCanClusterize = branch.implementationMethods.single()
    val rootReadAccess = rootState.accessPaths.single { access ->
        access.operation == DotNetGenericOwnerPhysicalStateAccessOperation.READ
    }
    val rootWriteAccess = rootState.accessPaths.single { access ->
        access.operation == DotNetGenericOwnerPhysicalStateAccessOperation.WRITE
    }
    fun physicalMember(
        owner: DotNetGenericOwnerPhysicalFamilyRecord,
        prototype: DotNetGenericOwnerPrototypeSnapshot,
        sourceName: String,
    ): DotNetGenericOwnerPhysicalMemberFamilyRecord {
        val logicalKey = checkNotNull(prototype.members.single { member ->
            member.sourceName == sourceName
        }.logicalBindingKey)
        return owner.members.single { member -> member.logicalMemberKey == logicalKey }
    }
    fun typedSlot(member: DotNetGenericOwnerPhysicalMemberFamilyRecord): DotNetGenericOwnerPhysicalMemberSlotRecord =
        member.slots.single { slot -> slot.role == DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY }
    fun capabilitySlot(
        member: DotNetGenericOwnerPhysicalMemberFamilyRecord,
    ): DotNetGenericOwnerPhysicalMemberSlotRecord = member.slots.single { slot ->
        slot.role == DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER
    }
    fun stateAccessMemberAndSlot(
        owner: DotNetGenericOwnerPhysicalFamilyRecord,
        state: DotNetGenericOwnerPhysicalStateRecord,
        operation: DotNetGenericOwnerPhysicalStateAccessOperation,
    ): Pair<DotNetGenericOwnerPhysicalMemberFamilyRecord, DotNetGenericOwnerPhysicalMemberSlotRecord> {
        val access = state.accessPaths.single { candidate -> candidate.operation == operation }
        check(access.bindingKind == DotNetGenericOwnerPhysicalStateAccessBindingKind.LOGICAL_MEMBER_FAMILY &&
                access.domain == DotNetGenericOwnerPhysicalStateAccessDomain.TYPED &&
                access.conversion == DotNetGenericOwnerPhysicalStateAccessConversion.IDENTITY) {
            "The OctoTree candidate state access is not a typed logical identity path: $access"
        }
        val member = owner.members.single { candidate ->
            candidate.logicalMemberKey == access.logicalMemberKey
        }
        val slot = member.slots.single { candidate ->
            candidate.role == DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY &&
                    candidate.physicalOwnerPath == access.physicalMethod.physicalOwnerPath &&
                    candidate.physicalMethodName == access.physicalMethod.physicalMethodName &&
                    candidate.signature == access.physicalMethod.signature
        }
        return member to slot
    }
    val nodeSetMember = physicalMember(node, nodePrototype, "set")
    val leafSetMember = physicalMember(leaf, leafPrototype, "set")
    val branchSetMember = physicalMember(branch, branchPrototype, "set")
    val treeDepthMember = physicalMember(tree, treePrototype, "<get-depth>")
    val treeGetMember = physicalMember(tree, treePrototype, "get")
    val treeSetMember = physicalMember(tree, treePrototype, "set")
    val treeToStringMember = physicalMember(tree, treePrototype, "toString")
    val leafToStringMember = physicalMember(leaf, leafPrototype, "toString")
    val branchToStringMember = physicalMember(branch, branchPrototype, "toString")
    val treeDepthSlot = typedSlot(treeDepthMember)
    val treeGetSlot = typedSlot(treeGetMember)
    val treeSetSlot = typedSlot(treeSetMember)
    val treeToStringSlot = typedSlot(treeToStringMember)
    val leafToStringSlot = typedSlot(leafToStringMember)
    val branchToStringSlot = typedSlot(branchToStringMember)
    val treeGetCapability = capabilitySlot(treeGetMember)
    val treeSetCapability = capabilitySlot(treeSetMember)
    val treeDepthCapability = capabilitySlot(treeDepthMember)
    val treeToStringCapability = capabilitySlot(treeToStringMember)
    val leafToStringCapability = capabilitySlot(leafToStringMember)
    val branchToStringCapability = capabilitySlot(branchToStringMember)
    val nodeSetSlot = typedSlot(nodeSetMember)
    val leafSetSlot = typedSlot(leafSetMember)
    val branchSetSlot = typedSlot(branchSetMember)
    val nodeSetCapability = capabilitySlot(nodeSetMember)
    val leafSetCapability = capabilitySlot(leafSetMember)
    val branchSetCapability = capabilitySlot(branchSetMember)
    val leafReadAccess = stateAccessMemberAndSlot(
        leaf, leafState, DotNetGenericOwnerPhysicalStateAccessOperation.READ,
    )
    val leafWriteAccess = stateAccessMemberAndSlot(
        leaf, leafState, DotNetGenericOwnerPhysicalStateAccessOperation.WRITE,
    )
    val branchReadAccess = stateAccessMemberAndSlot(
        branch, branchState, DotNetGenericOwnerPhysicalStateAccessOperation.READ,
    )
    val leafReadMember = leafReadAccess.first
    val leafReadSlot = leafReadAccess.second
    val leafWriteMember = leafWriteAccess.first
    val leafWriteSlot = leafWriteAccess.second
    val branchReadMember = branchReadAccess.first
    val branchReadSlot = branchReadAccess.second
    fun propertyForGetter(
        owner: DotNetGenericOwnerPhysicalFamilyRecord,
        getter: DotNetGenericOwnerPhysicalMemberFamilyRecord,
    ): DotNetGenericOwnerPhysicalPropertyRecord = owner.properties.single { property ->
        property.getterLogicalMemberKey == getter.logicalMemberKey
    }
    val treeDepthProperty = propertyForGetter(tree, treeDepthMember)
    val leafValueProperty = propertyForGetter(leaf, leafReadMember)
    val branchNodesProperty = propertyForGetter(branch, branchReadMember)
    check(node.properties.isEmpty() && tree.properties == listOf(treeDepthProperty) &&
            leaf.properties == listOf(leafValueProperty) && branch.properties == listOf(branchNodesProperty) &&
            leafValueProperty.setterLogicalMemberKey == leafWriteMember.logicalMemberKey &&
            listOf(treeDepthProperty, leafValueProperty, branchNodesProperty).all { property ->
                property.physicalPropertyName.matches(Regex("[A-Za-z_][A-Za-z0-9_]*"))
            }) {
        "The bounded OctoTree PropertyDef surface is incomplete or not directly C#-authorable"
    }
    val leafReadCapability = capabilitySlot(leafReadMember)
    val leafWriteCapability = capabilitySlot(leafWriteMember)
    val branchReadCapability = capabilitySlot(branchReadMember)
    fun callRoute(
        caller: DotNetGenericOwnerPhysicalMemberFamilyRecord,
        callee: DotNetGenericOwnerPhysicalMemberFamilyRecord,
    ): DotNetGenericOwnerCallRouteSnapshot = callRoutes.single { route ->
        route.callerLogicalBindingKey == caller.logicalMemberKey &&
                route.calleeLogicalBindingKey == callee.logicalMemberKey
    }
    val treeGetLeafReadRoute = callRoute(treeGetMember, leafReadMember)
    val treeGetBranchReadRoute = callRoute(treeGetMember, branchReadMember)
    val treeSetNodeRoute = callRoute(treeSetMember, nodeSetMember)
    val treeTypeParameters = List(tree.genericArity) { index -> "T$index" }
    val nodeTypeParameters = List(node.genericArity) { index -> "T$index" }
    val leafTypeParameters = List(leaf.genericArity) { index -> "T$index" }
    val branchTypeParameters = List(branch.genericArity) { index -> "T$index" }

    check(tree.physicalDispatch == DotNetGenericOwnerPhysicalTypeDispatch.OVERRIDABLE &&
            tree.physicalVisibility == DotNetGenericOwnerPhysicalTypeVisibility.PUBLIC &&
            treeConstructor.visibility == DotNetGenericOwnerPhysicalConstructorVisibility.PUBLIC &&
            treeConstructor.delegation.kind == DotNetGenericOwnerConstructorDelegationKind.BASE &&
            treeConstructor.delegation.physicalOwnerType.scope ==
            DotNetGenericOwnerPhysicalTypeScope.CORE_LIBRARY &&
            treeConstructor.delegation.physicalOwnerType.typePath == listOf("System", "Object") &&
            treeConstructor.delegation.signature.parameterSlots.isEmpty() &&
            treeConstructor.physicalConstructor.signature.parameterSlots.singleOrNull()?.type ==
            DotNetGenericOwnerPhysicalTypeExpressionRecord.int32Type() &&
            tree.physicalGenericParameters.all { parameter ->
                parameter.specialConstraints.isEmpty() && parameter.typeConstraints.isEmpty()
            }) {
        "The bounded OctoTree root proof received an unsupported owner/constructor record: $tree"
    }
    val expectedRootType = DotNetGenericOwnerPhysicalTypeExpressionRecord.producerType(
        typePath = node.physicalOwnerPath,
        category = DotNetGenericOwnerPhysicalNamedTypeCategory.CLASS,
        arguments = listOf(DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(0)),
    )
    check(rootState.physicalVisibility == DotNetGenericOwnerPhysicalStateVisibility.PRIVATE &&
            rootState.requirement ==
            DotNetGenericOwnerStateCarrierRequirement.TYPED_STORAGE_PRODUCER_GRAPH_PROVEN &&
            rootState.physicalType == expectedRootType &&
            rootState.initializers.isEmpty() &&
            listOf(rootReadAccess, rootWriteAccess).all { access ->
                access.domain == DotNetGenericOwnerPhysicalStateAccessDomain.TYPED &&
                        access.conversion == DotNetGenericOwnerPhysicalStateAccessConversion.IDENTITY &&
                        access.bindingKind ==
                        DotNetGenericOwnerPhysicalStateAccessBindingKind.PRODUCER_PRIVATE_METHOD &&
                        access.logicalMemberKey == null && access.role == null &&
                        access.physicalVisibility == DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE &&
                        access.physicalMethod.physicalOwnerPath == tree.physicalOwnerPath
            } && rootReadAccess.physicalMethod.signature.parameterSlots.isEmpty() &&
            rootReadAccess.physicalMethod.signature.returnSlot.type == rootState.physicalType &&
            rootWriteAccess.physicalMethod.signature.parameterSlots.singleOrNull()?.type == rootState.physicalType &&
            rootWriteAccess.physicalMethod.signature.returnSlot.type ==
            DotNetGenericOwnerPhysicalTypeExpressionRecord.voidType()) {
        "The OctoTree root did not retain one private typed Node<T> state/access pair: $rootState"
    }
    val treeIndependentIntParameters = listOf(
        DotNetGenericOwnerPhysicalTypeExpressionRecord.int32Type(),
        DotNetGenericOwnerPhysicalTypeExpressionRecord.int32Type(),
        DotNetGenericOwnerPhysicalTypeExpressionRecord.int32Type(),
    )
    check(treeDepthMember.roles == setOf(
                DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
                DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
            ) &&
            treeDepthSlot.visibility == DotNetGenericOwnerPhysicalMemberVisibility.PUBLIC &&
            treeDepthSlot.dispatch == DotNetGenericOwnerPhysicalMemberDispatch.FINAL &&
            treeDepthSlot.signature.parameterSlots.isEmpty() &&
            treeDepthSlot.signature.returnSlot.type ==
            DotNetGenericOwnerPhysicalTypeExpressionRecord.int32Type() &&
            treeDepthCapability.signature == treeDepthSlot.signature &&
            treeGetMember.roles == setOf(
                DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
                DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
            ) && treeGetSlot.visibility == DotNetGenericOwnerPhysicalMemberVisibility.PUBLIC &&
            treeGetSlot.dispatch == DotNetGenericOwnerPhysicalMemberDispatch.FINAL &&
            treeGetSlot.signature.parameterSlots.map { parameter -> parameter.type } ==
            treeIndependentIntParameters &&
            treeGetSlot.signature.returnSlot.type ==
            DotNetGenericOwnerPhysicalTypeExpressionRecord.objectType() &&
            treeGetCapability.signature == treeGetSlot.signature &&
            treeSetMember.roles == setOf(
                DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
                DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
            ) && treeSetSlot.visibility == DotNetGenericOwnerPhysicalMemberVisibility.PUBLIC &&
            treeSetSlot.dispatch == DotNetGenericOwnerPhysicalMemberDispatch.FINAL &&
            treeSetSlot.signature.parameterSlots.map { parameter -> parameter.type } ==
            treeIndependentIntParameters + DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(0) &&
            treeSetSlot.signature.returnSlot.type ==
            DotNetGenericOwnerPhysicalTypeExpressionRecord.voidType() &&
            treeSetCapability.signature.parameterSlots.map { parameter -> parameter.type } ==
            treeIndependentIntParameters + DotNetGenericOwnerPhysicalTypeExpressionRecord.objectType() &&
            treeSetCapability.signature.returnSlot.type ==
            DotNetGenericOwnerPhysicalTypeExpressionRecord.voidType() &&
            treeToStringMember.roles == setOf(
                DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
                DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
            ) &&
            treeToStringSlot.visibility == DotNetGenericOwnerPhysicalMemberVisibility.PUBLIC &&
            treeToStringSlot.dispatch == DotNetGenericOwnerPhysicalMemberDispatch.OVERRIDABLE &&
            treeToStringSlot.signature.parameterSlots.isEmpty() &&
            treeToStringSlot.signature.returnSlot.type ==
            DotNetGenericOwnerPhysicalTypeExpressionRecord.stringType() &&
            treeToStringCapability.signature == treeToStringSlot.signature) {
        "The OctoTree root member families lost their exact recorded MethodDef slots"
    }
    check(listOf(
        leafToStringMember to leafToStringCapability,
        branchToStringMember to branchToStringCapability,
    ).all { pair ->
        val member = pair.first
        val capability = pair.second
        val slot = typedSlot(member)
        member.roles == setOf(
            DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
            DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
        ) && capability.signature == slot.signature &&
                slot.visibility == DotNetGenericOwnerPhysicalMemberVisibility.PUBLIC &&
                slot.dispatch == DotNetGenericOwnerPhysicalMemberDispatch.OVERRIDABLE &&
                slot.signature.parameterSlots.isEmpty() &&
                slot.signature.returnSlot.type == DotNetGenericOwnerPhysicalTypeExpressionRecord.stringType()
    }) {
        "The OctoTree Leaf/Branch rendering overrides lost their exact recorded MethodDef slots"
    }
    check(listOf(
        treeDepthCapability,
        treeGetCapability,
        treeSetCapability,
        treeToStringCapability,
    ).all { slot ->
        val interfaceSlot = slot.capabilitySlot
        slot.physicalOwnerPath == tree.physicalOwnerPath &&
                slot.visibility == DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE &&
                slot.dispatch == DotNetGenericOwnerPhysicalMemberDispatch.FINAL &&
                interfaceSlot != null &&
                interfaceSlot.physicalOwnerPath == tree.physicalCapabilityOwnerPath &&
                interfaceSlot.signature == slot.signature &&
                slot.physicalMethodName ==
                "${interfaceSlot.physicalOwnerPath.joinToString(".")}.${interfaceSlot.physicalMethodName}"
    }) {
        "The OctoTree root capability interface lost its exact private-final dispatchers"
    }
    check(listOf(
        treeGetLeafReadRoute,
        treeGetBranchReadRoute,
        treeSetNodeRoute,
    ).all { route ->
        route.routeRequirement == DotNetGenericOwnerCallRouteRequirement.SEMANTIC_CAPABILITY
    }) {
        "The OctoTree root lost its recorded semantic state-to-node call routes: " +
                listOf(treeGetLeafReadRoute, treeGetBranchReadRoute, treeSetNodeRoute)
    }
    check(node.physicalDispatch == DotNetGenericOwnerPhysicalTypeDispatch.SEALED &&
            node.physicalVisibility == DotNetGenericOwnerPhysicalTypeVisibility.PUBLIC &&
            nodeConstructor.visibility ==
            DotNetGenericOwnerPhysicalConstructorVisibility.FAMILY_AND_ASSEMBLY &&
            nodeConstructor.physicalConstructor.signature.parameterSlots.isEmpty() &&
            node.physicalGenericParameters.all { parameter ->
                parameter.specialConstraints.isEmpty() && parameter.typeConstraints.isEmpty()
            }) {
        "The bounded OctoTree sealed-construction proof received an unsupported Node record: $node"
    }
    check(leaf.physicalDispatch == DotNetGenericOwnerPhysicalTypeDispatch.FINAL &&
            leaf.physicalVisibility == DotNetGenericOwnerPhysicalTypeVisibility.PUBLIC &&
            leafConstructor.delegation.kind == DotNetGenericOwnerConstructorDelegationKind.BASE &&
            leafConstructor.delegation.physicalOwnerType.typePath == node.physicalOwnerPath &&
            leafConstructor.delegation.signature.parameterSlots.isEmpty() &&
            leafState.physicalVisibility == DotNetGenericOwnerPhysicalStateVisibility.PRIVATE &&
            leafInitializer.kind ==
            DotNetGenericOwnerPhysicalStateInitializerKind.POSITIONAL_CONSTRUCTOR_PARAMETER &&
            leafInitializer.logicalConstructorKeys == listOf(leafConstructor.logicalConstructorKey) &&
            leaf.physicalGenericParameters.all { parameter ->
                parameter.specialConstraints.isEmpty() && parameter.typeConstraints.isEmpty()
            }) {
        "The bounded OctoTree sealed-construction proof received an unsupported Leaf record: $leaf"
    }
    check(branch.physicalDispatch == DotNetGenericOwnerPhysicalTypeDispatch.FINAL &&
            branch.physicalVisibility == DotNetGenericOwnerPhysicalTypeVisibility.PUBLIC &&
            branchBaseConstructor.visibility == DotNetGenericOwnerPhysicalConstructorVisibility.PUBLIC &&
            branchThisConstructor.visibility == DotNetGenericOwnerPhysicalConstructorVisibility.PUBLIC &&
            branchBaseConstructor.delegation.physicalOwnerType.typePath == node.physicalOwnerPath &&
            branchBaseConstructor.physicalConstructor.signature.parameterSlots.isEmpty() &&
            branchBaseConstructor.delegation.signature.parameterSlots.isEmpty() &&
            branchThisConstructor.delegation.physicalOwnerType.typePath == branch.physicalOwnerPath &&
            branchThisConstructor.delegation.logicalConstructorKey ==
            branchBaseConstructor.logicalConstructorKey &&
            branchThisConstructor.delegation.signature ==
            branchBaseConstructor.physicalConstructor.signature &&
            branchThisConstructor.physicalConstructor.signature.parameterSlots.map { slot -> slot.type } == listOf(
                DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(0),
                DotNetGenericOwnerPhysicalTypeExpressionRecord.int32Type(),
            ) && branchState.physicalVisibility == DotNetGenericOwnerPhysicalStateVisibility.PRIVATE &&
            branchState.requirement ==
            DotNetGenericOwnerStateCarrierRequirement.TYPED_STORAGE_PRODUCER_GRAPH_PROVEN &&
            branchState.physicalType.kind == DotNetGenericOwnerPhysicalTypeKind.SZ_ARRAY &&
            branchInitializer.kind == DotNetGenericOwnerPhysicalStateInitializerKind.FIXED_ZEROED_SZ_ARRAY &&
            branchInitializer.fixedElementCount == 8 &&
            branchInitializer.logicalConstructorKeys == listOf(branchBaseConstructor.logicalConstructorKey) &&
            branch.physicalGenericParameters.all { parameter ->
                parameter.specialConstraints.isEmpty() && parameter.typeConstraints.isEmpty()
            }) {
        "The bounded OctoTree Branch-state proof received an unsupported record: $branch"
    }
    check(branchElementType?.kind == DotNetGenericOwnerPhysicalTypeKind.NAMED &&
            branchElementType.scope == DotNetGenericOwnerPhysicalTypeScope.PRODUCER &&
            branchElementType.typePath == node.physicalOwnerPath &&
            branchElementType.arguments == listOf(DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(0))) {
        "The OctoTree Branch vector is not the recorded recursive Node<T>[] carrier: $branchState"
    }
    val expectedSetParameterTypes = listOf(
        DotNetGenericOwnerPhysicalTypeExpressionRecord.int32Type(),
        DotNetGenericOwnerPhysicalTypeExpressionRecord.int32Type(),
        DotNetGenericOwnerPhysicalTypeExpressionRecord.int32Type(),
        DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(0),
        DotNetGenericOwnerPhysicalTypeExpressionRecord.int32Type(),
    )
    check(nodeSetSlot.physicalOwnerPath == node.physicalOwnerPath &&
            leafSetSlot.physicalOwnerPath == leaf.physicalOwnerPath &&
            branchSetSlot.physicalOwnerPath == branch.physicalOwnerPath &&
            nodeSetSlot.physicalMethodName == leafSetSlot.physicalMethodName &&
            nodeSetSlot.physicalMethodName == branchSetSlot.physicalMethodName &&
            nodeSetSlot.visibility == DotNetGenericOwnerPhysicalMemberVisibility.PUBLIC &&
            leafSetSlot.visibility == DotNetGenericOwnerPhysicalMemberVisibility.PUBLIC &&
            branchSetSlot.visibility == DotNetGenericOwnerPhysicalMemberVisibility.PUBLIC &&
            nodeSetSlot.dispatch == DotNetGenericOwnerPhysicalMemberDispatch.ABSTRACT &&
            leafSetSlot.dispatch == DotNetGenericOwnerPhysicalMemberDispatch.OVERRIDABLE &&
            branchSetSlot.dispatch == DotNetGenericOwnerPhysicalMemberDispatch.OVERRIDABLE &&
            nodeSetSlot.signature == leafSetSlot.signature &&
            nodeSetSlot.signature == branchSetSlot.signature &&
            nodeSetSlot.signature.parameterSlots.map { slot -> slot.type } == expectedSetParameterTypes &&
            nodeSetSlot.signature.returnSlot.type ==
            DotNetGenericOwnerPhysicalTypeExpressionRecord.booleanType() &&
            nodeSetMember.overrideRootLogicalMemberKeys == listOf(nodeSetMember.logicalMemberKey) &&
            leafSetMember.overrideRootLogicalMemberKeys == listOf(nodeSetMember.logicalMemberKey) &&
            branchSetMember.overrideRootLogicalMemberKeys == listOf(nodeSetMember.logicalMemberKey)) {
        "The OctoTree Node.set typed override family is not one exact recorded CLR slot"
    }
    val expectedCapabilityParameterTypes = expectedSetParameterTypes.map { type ->
        if (type.kind == DotNetGenericOwnerPhysicalTypeKind.OWNER_TYPE_PARAMETER) {
            DotNetGenericOwnerPhysicalTypeExpressionRecord.objectType()
        } else {
            type
        }
    }
    check(listOf(
        node to nodeSetCapability,
        leaf to leafSetCapability,
        branch to branchSetCapability,
    ).all { ownerAndSlot ->
        val owner = ownerAndSlot.first
        val slot = ownerAndSlot.second
        val interfaceSlot = slot.capabilitySlot
        slot.physicalOwnerPath == owner.physicalOwnerPath &&
                slot.visibility == DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE &&
                slot.dispatch == DotNetGenericOwnerPhysicalMemberDispatch.FINAL &&
                slot.signature.parameterSlots.map { parameter -> parameter.type } ==
                expectedCapabilityParameterTypes &&
                slot.signature.returnSlot.type == DotNetGenericOwnerPhysicalTypeExpressionRecord.booleanType() &&
                interfaceSlot != null &&
                interfaceSlot.physicalOwnerPath == owner.physicalCapabilityOwnerPath &&
                interfaceSlot.signature == slot.signature &&
                slot.physicalMethodName ==
                "${interfaceSlot.physicalOwnerPath.joinToString(".")}.${interfaceSlot.physicalMethodName}"
    }) {
        "The OctoTree Node.set strict capability family is not one exact non-generic object-carrier slot"
    }
    check(leafReadSlot.signature.parameterSlots.isEmpty() &&
            leafReadSlot.signature.returnSlot.type == leafState.physicalType &&
            leafWriteSlot.signature.parameterSlots.singleOrNull()?.type == leafState.physicalType &&
            leafWriteSlot.signature.returnSlot.type == DotNetGenericOwnerPhysicalTypeExpressionRecord.voidType() &&
            branchReadSlot.signature.parameterSlots.isEmpty() &&
            branchReadSlot.signature.returnSlot.type == branchState.physicalType) {
        "The OctoTree candidate state accessors lost their exact recorded carriers"
    }
    val systemArrayType = DotNetGenericOwnerPhysicalTypeExpressionRecord.coreType(
        typePath = listOf("System", "Array"),
        category = DotNetGenericOwnerPhysicalNamedTypeCategory.CLASS,
    )
    check(leafReadMember.roles == setOf(
        DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
        DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
    ) && leafWriteMember.roles == setOf(
        DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
        DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
    ) && branchReadMember.roles == setOf(
        DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
        DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
    ) && leafReadCapability.signature.parameterSlots.isEmpty() &&
            leafReadCapability.signature.returnSlot.type ==
            DotNetGenericOwnerPhysicalTypeExpressionRecord.objectType() &&
            leafWriteCapability.signature.parameterSlots.singleOrNull()?.type ==
            DotNetGenericOwnerPhysicalTypeExpressionRecord.objectType() &&
            leafWriteCapability.signature.returnSlot.type ==
            DotNetGenericOwnerPhysicalTypeExpressionRecord.voidType() &&
            branchReadCapability.signature.parameterSlots.isEmpty() &&
            branchReadCapability.signature.returnSlot.type == systemArrayType &&
            listOf(
                leaf to leafReadCapability,
                leaf to leafWriteCapability,
                branch to branchReadCapability,
            ).all { ownerAndSlot ->
                val owner = ownerAndSlot.first
                val slot = ownerAndSlot.second
                val interfaceSlot = slot.capabilitySlot
                slot.physicalOwnerPath == owner.physicalOwnerPath &&
                        slot.visibility == DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE &&
                        slot.dispatch == DotNetGenericOwnerPhysicalMemberDispatch.FINAL &&
                        interfaceSlot != null &&
                        interfaceSlot.physicalOwnerPath == owner.physicalCapabilityOwnerPath &&
                        interfaceSlot.signature == slot.signature &&
                        slot.physicalMethodName ==
                        "${interfaceSlot.physicalOwnerPath.joinToString(".")}.${interfaceSlot.physicalMethodName}"
            }) {
        "The OctoTree state-access capabilities lost their recorded erased ABI boundary"
    }
    check(tree.physicalOwnerPath.dropLast(1) == node.physicalOwnerPath.dropLast(1) &&
            node.physicalOwnerPath.dropLast(1) == leaf.physicalOwnerPath.dropLast(1) &&
            node.physicalOwnerPath.dropLast(1) == branch.physicalOwnerPath.dropLast(1) &&
            tree.physicalOwnerPath.last().matches(Regex("[A-Za-z_][A-Za-z0-9_]*")) &&
            node.physicalOwnerPath.last().matches(Regex("[A-Za-z_][A-Za-z0-9_]*")) &&
            leaf.physicalOwnerPath.last().matches(Regex("[A-Za-z_][A-Za-z0-9_]*")) &&
            branch.physicalOwnerPath.last().matches(Regex("[A-Za-z_][A-Za-z0-9_]*")) &&
            leafState.physicalFieldName.matches(Regex("[A-Za-z_][A-Za-z0-9_]*")) &&
            branchState.physicalFieldName.matches(Regex("[A-Za-z_][A-Za-z0-9_]*")) &&
            rootState.physicalFieldName.matches(Regex("[A-Za-z_][A-Za-z0-9_]*")) &&
            listOf(
                treeDepthSlot,
                treeGetSlot,
                treeSetSlot,
                treeToStringSlot,
                leafToStringSlot,
                branchToStringSlot,
                nodeSetSlot,
                leafReadSlot,
                leafWriteSlot,
                branchReadSlot,
            ).all { slot ->
                slot.physicalMethodName.matches(Regex("[A-Za-z_][A-Za-z0-9_]*"))
            } && listOf(rootReadAccess, rootWriteAccess).all { access ->
                access.physicalMethod.physicalMethodName.matches(Regex("[A-Za-z_][A-Za-z0-9_]*"))
            } && listOf(
                treeDepthCapability,
                treeGetCapability,
                treeSetCapability,
                treeToStringCapability,
                nodeSetCapability,
                leafSetCapability,
                branchSetCapability,
                leafReadCapability,
                leafWriteCapability,
                branchReadCapability,
                leafToStringCapability,
                branchToStringCapability,
            ).all { slot ->
                checkNotNull(slot.capabilitySlot).let { interfaceSlot ->
                    interfaceSlot.physicalOwnerPath.last().matches(Regex("[A-Za-z_][A-Za-z0-9_]*")) &&
                            interfaceSlot.physicalMethodName.matches(Regex("[A-Za-z_][A-Za-z0-9_]*"))
                }
            }) {
        "The bounded OctoTree candidate requires C#-representable physical identities"
    }
    check(leafParameterIndex in leafConstructor.physicalConstructor.signature.parameterSlots.indices &&
            leafConstructor.physicalConstructor.signature.parameterSlots[leafParameterIndex].type ==
            leafState.physicalType) {
        "The OctoTree Leaf state is not initialized by its exact recorded constructor parameter"
    }

    fun DotNetGenericOwnerPhysicalConstructorVisibility.renderVisibility(): String = when (this) {
        DotNetGenericOwnerPhysicalConstructorVisibility.PUBLIC -> "public"
        DotNetGenericOwnerPhysicalConstructorVisibility.FAMILY -> "protected"
        DotNetGenericOwnerPhysicalConstructorVisibility.ASSEMBLY -> "internal"
        DotNetGenericOwnerPhysicalConstructorVisibility.FAMILY_AND_ASSEMBLY -> "private protected"
        DotNetGenericOwnerPhysicalConstructorVisibility.FAMILY_OR_ASSEMBLY -> "protected internal"
        DotNetGenericOwnerPhysicalConstructorVisibility.PRIVATE -> "private"
    }
    fun DotNetGenericOwnerPhysicalMemberVisibility.renderVisibility(): String = when (this) {
        DotNetGenericOwnerPhysicalMemberVisibility.PUBLIC -> "public"
        DotNetGenericOwnerPhysicalMemberVisibility.FAMILY -> "protected"
        DotNetGenericOwnerPhysicalMemberVisibility.ASSEMBLY -> "internal"
        DotNetGenericOwnerPhysicalMemberVisibility.FAMILY_OR_ASSEMBLY -> "protected internal"
        DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE -> "private"
