                );
                MethodInfo treeSetTarget = CapabilityTarget(
                    tree.GetType(), typeof($treeCapabilityType),
                    ${treeSetCapabilityIdentity.physicalMethodName.asCSharpStringLiteral()}
                );
                if (treeGetTarget == null || treeSetTarget == null ||
                        !treeGetTarget.IsPrivate || !treeGetTarget.IsVirtual || !treeGetTarget.IsFinal ||
                        treeGetTarget.DeclaringType != tree.GetType() ||
                        !treeSetTarget.IsPrivate || !treeSetTarget.IsVirtual || !treeSetTarget.IsFinal ||
                        treeSetTarget.DeclaringType != tree.GetType()) return 60;
                var derivedTree = new DerivedOctoTree(2);
                derivedTree.${treeSetSlot.physicalMethodName}(0, 0, 0, 31);
                if (!object.Equals(derivedTree.${treeGetSlot.physicalMethodName}(0, 0, 0), 31) ||
                        string.IsNullOrEmpty(derivedTree.${treeToStringSlot.physicalMethodName}())) return 61;
                $treeCapabilityType derivedCapability = derivedTree;
                derivedCapability.${treeSetCapabilityIdentity.physicalMethodName}(0, 0, 0, 37);
                if (!object.Equals(
                        derivedCapability.${treeGetCapabilityIdentity.physicalMethodName}(0, 0, 0), 37)) return 62;
                MethodInfo derivedSetTarget = CapabilityTarget(
                    derivedTree.GetType(), typeof($treeCapabilityType),
                    ${treeSetCapabilityIdentity.physicalMethodName.asCSharpStringLiteral()}
                );
                if (derivedSetTarget == null ||
                        derivedSetTarget.DeclaringType != typeof(${tree.physicalOwnerPath.joinToString(".")}<int>) ||
                        !derivedSetTarget.IsPrivate || !derivedSetTarget.IsVirtual ||
                        !derivedSetTarget.IsFinal) return 63;

                var workloadTree = new ${tree.physicalOwnerPath.joinToString(".")}<int>(2);
                const int workloadExtent = 8;
                for (int x = 0; x < workloadExtent; x++)
                for (int y = 0; y < workloadExtent; y++)
                for (int z = 0; z < workloadExtent; z++)
                {
                    int value = (z + workloadExtent * y + workloadExtent * workloadExtent * x) & 1;
                    workloadTree.${treeSetSlot.physicalMethodName}(x, y, z, value);
                }
                int workloadMatched = 0;
                for (int x = 0; x < workloadExtent; x++)
                for (int y = 0; y < workloadExtent; y++)
                for (int z = 0; z < workloadExtent; z++)
                {
                    int expected = (z + workloadExtent * y + workloadExtent * workloadExtent * x) & 1;
                    if (object.Equals(workloadTree.${treeGetSlot.physicalMethodName}(x, y, z), expected))
                    {
                        workloadMatched++;
                    }
                }
                if (workloadMatched != workloadExtent * workloadExtent * workloadExtent ||
                        string.IsNullOrEmpty(workloadTree.${treeToStringSlot.physicalMethodName}())) return 64;

                var clusteredTree = new ${tree.physicalOwnerPath.joinToString(".")}<int>(1);
                const int clusteredExtent = 2;
                for (int x = 0; x < clusteredExtent; x++)
                for (int y = 0; y < clusteredExtent; y++)
                for (int z = 0; z < clusteredExtent; z++)
                {
                    clusteredTree.${treeSetSlot.physicalMethodName}(x, y, z, 91);
                }
                object clusteredRoot = closedRootField.GetValue(clusteredTree);
                if (clusteredRoot == null ||
                        clusteredRoot.GetType() != typeof(${leaf.physicalOwnerPath.joinToString(".")}<int>) ||
                        !object.Equals(clusteredTree.${treeGetSlot.physicalMethodName}(0, 0, 0), 91) ||
                        !object.Equals(clusteredTree.${treeGetSlot.physicalMethodName}(1, 1, 1), 91)) return 65;

                var doubleSignedZeroBranch =
                    new ${branch.physicalOwnerPath.joinToString(".")}<double>(-0.0d, 0);
                if (doubleSignedZeroBranch.${branchSetSlot.physicalMethodName}(
                        0, 0, 0, +0.0d, 0)) return 66;
                double firstNaN = BitConverter.Int64BitsToDouble(0x7ff8000000000001L);
                double secondNaN = BitConverter.Int64BitsToDouble(0x7ff8000000000042L);
                var doubleNaNBranch =
                    new ${branch.physicalOwnerPath.joinToString(".")}<double>(firstNaN, 0);
                if (!doubleNaNBranch.${branchSetSlot.physicalMethodName}(
                        0, 0, 0, secondNaN, 0)) return 67;
                var floatSignedZeroBranch =
                    new ${branch.physicalOwnerPath.joinToString(".")}<float>(-0.0f, 0);
                if (floatSignedZeroBranch.${branchSetSlot.physicalMethodName}(
                        0, 0, 0, +0.0f, 0)) return 68;

                var leaf = new ${leaf.physicalOwnerPath.joinToString(".")}<int>(42);
                Type nodeDefinition = typeof($nodeOpenType);
                ConstructorInfo[] nodeConstructors = nodeDefinition.GetConstructors(
                    BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic
                );
                if (!nodeDefinition.IsAbstract || nodeDefinition.IsSealed ||
                        nodeConstructors.Length != 1 ||
                        !nodeConstructors[0].IsFamilyAndAssembly) return 1;

                Type leafDefinition = typeof($leafOpenType);
                PropertyInfo openValueProperty = leafDefinition.GetProperty(
                    ${leafValueProperty.physicalPropertyName.asCSharpStringLiteral()},
                    BindingFlags.Instance | BindingFlags.Public | BindingFlags.DeclaredOnly
                );
                FieldInfo openValueField = leafDefinition.GetField(
                    ${leafState.physicalFieldName.asCSharpStringLiteral()},
                    BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.DeclaredOnly
                );
                if (!leafDefinition.IsSealed || openValueField == null || openValueProperty == null ||
                        openValueProperty.PropertyType != leafDefinition.GetGenericArguments()[0] ||
                        !openValueProperty.CanRead || !openValueProperty.CanWrite ||
                        openValueProperty.GetIndexParameters().Length != 0 ||
                        openValueProperty.GetGetMethod().Name !=
                            ${checkNotNull(leafValueProperty.getterPhysicalMethod).physicalMethodName.asCSharpStringLiteral()} ||
                        openValueProperty.GetSetMethod().Name !=
                            ${checkNotNull(leafValueProperty.setterPhysicalMethod).physicalMethodName.asCSharpStringLiteral()})
                    return 2;
                if (openValueField.FieldType != leafDefinition.GetGenericArguments()[0]) return 3;
                FieldInfo closedValueField = leaf.GetType().GetField(
                    ${leafState.physicalFieldName.asCSharpStringLiteral()},
                    BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.DeclaredOnly
                );
                if (closedValueField == null || closedValueField.FieldType != typeof(int) ||
                        !object.Equals(closedValueField.GetValue(leaf), 42)) return 4;

                var emptyBranch = new ${branch.physicalOwnerPath.joinToString(".")}<int>();
                var filledBranch = new ${branch.physicalOwnerPath.joinToString(".")}<int>(7, 3);
                Type branchDefinition = typeof($branchOpenType);
                PropertyInfo openNodesProperty = branchDefinition.GetProperty(
                    ${branchNodesProperty.physicalPropertyName.asCSharpStringLiteral()},
                    BindingFlags.Instance | BindingFlags.Public | BindingFlags.DeclaredOnly
                );
                FieldInfo openNodesField = branchDefinition.GetField(
                    ${branchState.physicalFieldName.asCSharpStringLiteral()},
                    BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.DeclaredOnly
                );
                if (!branchDefinition.IsSealed || openNodesField == null || openNodesProperty == null ||
                        openNodesProperty.PropertyType != openNodesField.FieldType ||
                        !openNodesProperty.CanRead || openNodesProperty.CanWrite ||
                        openNodesProperty.GetIndexParameters().Length != 0 ||
                        openNodesProperty.GetGetMethod().Name !=
                            ${checkNotNull(branchNodesProperty.getterPhysicalMethod).physicalMethodName.asCSharpStringLiteral()} ||
                        !openNodesField.FieldType.IsArray || !openNodesField.IsInitOnly) return 5;
                MethodInfo canClusterizeMethod = branchDefinition.GetMethod(
                    ${branchCanClusterize.physicalMethod.physicalMethodName.asCSharpStringLiteral()},
                    BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.DeclaredOnly
                );
                if (canClusterizeMethod == null || !canClusterizeMethod.IsPrivate ||
                        canClusterizeMethod.IsVirtual || canClusterizeMethod.ReturnType != typeof(bool) ||
                        canClusterizeMethod.GetParameters().Length != 1 ||
                        canClusterizeMethod.GetParameters()[0].ParameterType !=
                        branchDefinition.GetGenericArguments()[0]) return 5;
                Type openNodeElement = openNodesField.FieldType.GetElementType();
                if (openNodeElement == null || !openNodeElement.IsGenericType ||
                        openNodeElement.GetGenericTypeDefinition() != typeof($nodeOpenType) ||
                        openNodeElement.GetGenericArguments()[0] !=
                        branchDefinition.GetGenericArguments()[0]) return 6;
                ConstructorInfo[] branchConstructors = branchDefinition.GetConstructors(
                    BindingFlags.Instance | BindingFlags.Public | BindingFlags.DeclaredOnly
                );
                if (branchConstructors.Length != 2) return 7;

                FieldInfo closedNodesField = emptyBranch.GetType().GetField(
                    ${branchState.physicalFieldName.asCSharpStringLiteral()},
                    BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.DeclaredOnly
                );
                if (closedNodesField == null ||
                        closedNodesField.FieldType != typeof(${node.physicalOwnerPath.joinToString(".")}<int>[])) return 8;
                Array emptyNodes = (Array)closedNodesField.GetValue(emptyBranch);
                Array filledNodes = (Array)closedNodesField.GetValue(filledBranch);
                if (emptyNodes == null || filledNodes == null ||
                        emptyNodes.Length != $branchElementCount ||
                        filledNodes.Length != $branchElementCount ||
                        object.ReferenceEquals(emptyNodes, filledNodes)) return 9;
                for (int index = 0; index < $branchElementCount; index++)
                {
                    if (emptyNodes.GetValue(index) != null) return 10;
                    object node = filledNodes.GetValue(index);
                    if (index == 3)
                    {
                        if (node != null) return 11;
                    }
                    else if (node == null || node.GetType() != leaf.GetType() ||
                            !object.Equals(closedValueField.GetValue(node), 7)) return 12;
                }

                leaf.${leafValueProperty.physicalPropertyName} = 43;
                if (leaf.${leafValueProperty.physicalPropertyName} != 43) return 13;
                Array getterNodes = filledBranch.${branchNodesProperty.physicalPropertyName};
                if (!object.ReferenceEquals(getterNodes, filledNodes)) return 14;

                ${node.physicalOwnerPath.joinToString(".")}<int> typedNode = filledBranch;
                if (typedNode.${nodeSetSlot.physicalMethodName}(0, 0, 0, 19, 0)) return 15;
                object replacedNode = filledNodes.GetValue(0);
                if (replacedNode == null || replacedNode.GetType() != leaf.GetType() ||
                        !object.Equals(closedValueField.GetValue(replacedNode), 19)) return 16;

                bool leafThrew = false;
                try
                {
                    typedNode = leaf;
                    typedNode.${nodeSetSlot.physicalMethodName}(0, 0, 0, 23, 0);
                }
                catch (NotSupportedException)
                {
                    leafThrew = true;
                }
                if (!leafThrew) return 17;

                $nodeCapabilityType nodeCapability = filledBranch;
                if (nodeCapability.${nodeSetCapabilityIdentity.physicalMethodName}(0, 0, 0, 29, 0)) return 18;
                object nodeCapabilityValue = filledNodes.GetValue(0);
                if (nodeCapabilityValue == null || nodeCapabilityValue.GetType() != leaf.GetType() ||
                        !object.Equals(closedValueField.GetValue(nodeCapabilityValue), 29)) return 19;

                $branchCapabilityType branchCapability = filledBranch;
                if (branchCapability.${branchSetCapabilityIdentity.physicalMethodName}(0, 0, 0, 31, 0)) return 20;
                object branchCapabilityValue = filledNodes.GetValue(0);
                if (branchCapabilityValue == null || branchCapabilityValue.GetType() != leaf.GetType() ||
                        !object.Equals(closedValueField.GetValue(branchCapabilityValue), 31)) return 21;

                object beforeIncompatible = branchCapabilityValue;
                bool incompatibleThrew = false;
                try
                {
                    nodeCapability.${nodeSetCapabilityIdentity.physicalMethodName}(0, 0, 0, "wrong", 0);
                }
                catch (InvalidCastException)
                {
                    incompatibleThrew = true;
                }
                if (!incompatibleThrew ||
                        !object.ReferenceEquals(beforeIncompatible, filledNodes.GetValue(0))) return 22;

                $leafCapabilityType leafCapability = leaf;
                bool leafCapabilityThrew = false;
                try
                {
                    leafCapability.${leafSetCapabilityIdentity.physicalMethodName}(0, 0, 0, 37, 0);
                }
                catch (NotSupportedException)
                {
                    leafCapabilityThrew = true;
                }
                if (!leafCapabilityThrew) return 23;

                leafCapability.${leafWriteCapabilityIdentity.physicalMethodName}(41);
                object leafCapabilityValue = leafCapability.${leafReadCapabilityIdentity.physicalMethodName}();
                if (!object.Equals(leafCapabilityValue, 41) ||
                        leaf.${leafValueProperty.physicalPropertyName} != 41) return 24;
                bool leafWriteThrew = false;
                try
                {
                    leafCapability.${leafWriteCapabilityIdentity.physicalMethodName}("wrong");
                }
                catch (InvalidCastException)
                {
                    leafWriteThrew = true;
                }
                if (!leafWriteThrew || leaf.${leafValueProperty.physicalPropertyName} != 41) return 25;

                Array branchCapabilityNodes = branchCapability.${branchReadCapabilityIdentity.physicalMethodName}();
                if (!object.ReferenceEquals(branchCapabilityNodes, filledNodes)) return 26;

                MethodInfo nodeTarget = CapabilityTarget(
                    filledBranch.GetType(), typeof($nodeCapabilityType),
                    ${nodeSetCapabilityIdentity.physicalMethodName.asCSharpStringLiteral()}
                );
                MethodInfo branchTarget = CapabilityTarget(
                    filledBranch.GetType(), typeof($branchCapabilityType),
                    ${branchSetCapabilityIdentity.physicalMethodName.asCSharpStringLiteral()}
                );
                if (nodeTarget == null || branchTarget == null ||
                        !nodeTarget.IsPrivate || !nodeTarget.IsVirtual || !nodeTarget.IsFinal ||
                        nodeTarget.DeclaringType != typeof(${node.physicalOwnerPath.joinToString(".")}<int>) ||
                        !branchTarget.IsPrivate || !branchTarget.IsVirtual || !branchTarget.IsFinal ||
                        branchTarget.DeclaringType != filledBranch.GetType()) return 27;
                MethodInfo leafReadTarget = CapabilityTarget(
                    leaf.GetType(), typeof($leafCapabilityType),
                    ${leafReadCapabilityIdentity.physicalMethodName.asCSharpStringLiteral()}
                );
                MethodInfo leafWriteTarget = CapabilityTarget(
                    leaf.GetType(), typeof($leafCapabilityType),
                    ${leafWriteCapabilityIdentity.physicalMethodName.asCSharpStringLiteral()}
                );
                MethodInfo branchReadTarget = CapabilityTarget(
                    filledBranch.GetType(), typeof($branchCapabilityType),
                    ${branchReadCapabilityIdentity.physicalMethodName.asCSharpStringLiteral()}
                );
                if (leafReadTarget == null || leafWriteTarget == null || branchReadTarget == null ||
                        !leafReadTarget.IsPrivate || !leafReadTarget.IsVirtual || !leafReadTarget.IsFinal ||
                        leafReadTarget.DeclaringType != leaf.GetType() ||
                        !leafWriteTarget.IsPrivate || !leafWriteTarget.IsVirtual || !leafWriteTarget.IsFinal ||
                        leafWriteTarget.DeclaringType != leaf.GetType() ||
                        !branchReadTarget.IsPrivate || !branchReadTarget.IsVirtual || !branchReadTarget.IsFinal ||
                        branchReadTarget.DeclaringType != filledBranch.GetType()) return 28;
                return 0;
            }
        }
        """.trimIndent()
    )
    negativeConsumerSource.writeText(
        """
        public sealed class IllegalOctoTreeNode<T> : ${node.physicalOwnerPath.joinToString(".")}<T>
        {
            public IllegalOctoTreeNode() : base()
            {
            }

            public override $nodeSetReturnType ${nodeSetSlot.physicalMethodName}(
                ${nodeSetSlot.renderParameters(listOf("T"))}
            )
            {
                return false;
            }
        }
        """.trimIndent()
    )
    metadataInspectorSource.writeText(
        genericOwnerMetadataInspectorSource(decoded, producer, treeLogicalKey)
    )

    val platformProperty = "kotlin.dotnet.test.platform.${target.description}.path"
    val platformDirectory = System.getProperty(platformProperty)?.let(::File)
        ?: error("Missing reusable Kotlin/.NET test platform property '$platformProperty'")
    val runtime = platformDirectory.resolve(DotNetRuntimeArtifact.ASSEMBLY_FILE_NAME)
    val stdlib = platformDirectory.resolve(DotNetStdlibArtifact.ASSEMBLY_FILE_NAME)
    check(runtime.isFile && stdlib.isFile) {
        "The OctoTree paired application lacks reusable Runtime/Stdlib artifacts"
    }
    val producerCompilation: SnapshotCSharpCompilation
    val positiveCompilation: SnapshotCSharpCompilation
    val negativeCompilation: SnapshotCSharpCompilation
    val candidateMeasurementCompilation: SnapshotCSharpCompilation
    val erasedMeasurementCompilation: SnapshotCSharpCompilation
    when (target) {
        DotNetTarget.NET48 -> {
            val compiler = checkNotNull(DotNetIlAssembler.findFrameworkCSharpCompiler()) {
                ".NET Framework C# compiler is required for the OctoTree candidate"
            }
            producerCompilation = compileFrameworkSnapshotCSharp(
                compiler,
                producerSource,
                producer,
                references = listOf(runtime),
                executable = false,
                warningsAsErrors = true,
            )
            check(producerCompilation.exitCode == 0) { producerCompilation.output }
            candidateMeasurementCompilation = compileFrameworkSnapshotCSharp(
                compiler,
                candidateMeasurementSource,
                candidateMeasurement,
                references = listOf(producer, runtime),
                executable = true,
            )
            erasedMeasurementCompilation = compileFrameworkSnapshotCSharp(
                compiler,
                erasedMeasurementSource,
                erasedMeasurement,
                references = listOf(erasedProducerOutput, runtime, stdlib),
                executable = true,
            )
            positiveCompilation = compileFrameworkSnapshotCSharp(
                compiler,
                positiveConsumerSource,
                positiveConsumer,
                references = listOf(producer, runtime),
                executable = true,
            )
            negativeCompilation = compileFrameworkSnapshotCSharp(
                compiler,
                negativeConsumerSource,
                negativeConsumer,
                references = listOf(producer, runtime),
                executable = false,
            )
        }
        DotNetTarget.NET10_0 -> {
            val toolchain = checkNotNull(DotNetIlAssembler.findModernCSharpCompiler()) {
                "Modern C# compiler is required for the OctoTree candidate"
            }
            producerCompilation = compileModernSnapshotCSharp(
                toolchain,
                producerSource,
                producer,
                references = listOf(runtime),
                executable = false,
                warningsAsErrors = true,
            )
            check(producerCompilation.exitCode == 0) { producerCompilation.output }
            candidateMeasurementCompilation = compileModernSnapshotCSharp(
                toolchain,
                candidateMeasurementSource,
                candidateMeasurement,
                references = listOf(producer, runtime),
                executable = true,
            )
            erasedMeasurementCompilation = compileModernSnapshotCSharp(
                toolchain,
                erasedMeasurementSource,
                erasedMeasurement,
                references = listOf(erasedProducerOutput, runtime, stdlib),
                executable = true,
            )
            positiveCompilation = compileModernSnapshotCSharp(
                toolchain,
                positiveConsumerSource,
                positiveConsumer,
                references = listOf(producer, runtime),
                executable = true,
            )
            negativeCompilation = compileModernSnapshotCSharp(
                toolchain,
                negativeConsumerSource,
                negativeConsumer,
                references = listOf(producer, runtime),
                executable = false,
            )
        }
        DotNetTarget.NETSTANDARD_2_0 -> error("The OctoTree candidate cannot target netstandard2.0")
    }
    check(candidateMeasurementCompilation.exitCode == 0) { candidateMeasurementCompilation.output }
    check(erasedMeasurementCompilation.exitCode == 0) { erasedMeasurementCompilation.output }
    check(positiveCompilation.exitCode == 0) { positiveCompilation.output }
    check(negativeCompilation.exitCode != 0 && listOf("CS0122", "CS1729").any { diagnostic ->
        diagnostic in negativeCompilation.output
    }) {
        "External C# unexpectedly subclassed Kotlin sealed Node<T>: ${negativeCompilation.output}"
    }
    val metadataToolchain = checkNotNull(DotNetIlAssembler.findModernCSharpCompiler()) {
        "Modern C# compiler is required for the OctoTree raw metadata inspector"
    }
    val metadataCompilation = compileModernSnapshotCSharp(
        metadataToolchain,
        metadataInspectorSource,
        metadataInspector,
        references = emptyList(),
        executable = true,
    )
    check(metadataCompilation.exitCode == 0) { metadataCompilation.output }
    listOf(erasedProducerOutput, runtime, stdlib).forEach { dependency ->
        val localDependency = directory.resolve(dependency.name)
        if (dependency.canonicalFile != localDependency.canonicalFile) {
            check(!localDependency.exists()) {
                "The OctoTree paired application dependency collides with ${localDependency.path}"
            }
            dependency.copyTo(localDependency)
        }
    }
    executeSnapshotConsumer(DotNetTarget.NET10_0, metadataInspector, directory)
    executeSnapshotConsumer(target, positiveConsumer, directory)
    executeSnapshotConsumer(target, candidateMeasurement, directory)
    executeSnapshotConsumer(target, erasedMeasurement, directory)
    System.getProperty(GENERIC_OWNER_APPLICATION_EXPORT_PROPERTY)?.let { exportPath ->
        check(!compilerOutputUsesReifiedOwners) {
            "The paired erased/candidate OctoTree corpus cannot be exported from a rehearsal product"
        }
        check(exportPath.isNotBlank()) { "Generic-owner application export path must not be blank" }
        prepareGenericOwnerOctoTreeApplicationBundle(
            directory = directory,
            target = target,
            applicationSource = applicationSource,
            candidateProducerSource = producerSource,
            candidateProducer = producer,
            candidateConsumerSource = candidateMeasurementSource,
            candidateConsumer = candidateMeasurement,
            physicalFamilyArtifact = recordFile,
            callRouteManifest = callRouteManifestFile,
            erasedProducer = erasedProducerOutput,
            erasedConsumerSource = erasedMeasurementSource,
            erasedConsumer = erasedMeasurement,
            runtime = runtime,
            stdlib = stdlib,
            exportDirectory = File(exportPath),
        )
    }
}

private fun prepareGenericOwnerOctoTreeApplicationBundle(
    directory: File,
    target: DotNetTarget,
    applicationSource: File,
    candidateProducerSource: File,
    candidateProducer: File,
    candidateConsumerSource: File,
    candidateConsumer: File,
    physicalFamilyArtifact: File,
    callRouteManifest: File,
    erasedProducer: File,
    erasedConsumerSource: File,
    erasedConsumer: File,
    runtime: File,
    stdlib: File,
    exportDirectory: File,
) {
    val repositoryRoot = generateSequence(applicationSource.canonicalFile.parentFile, File::getParentFile)
        .firstOrNull { candidate ->
            candidate.resolve("kotlin-native").isDirectory && candidate.resolve("compiler").isDirectory
        }
        ?: error("Cannot locate the repository root from ${applicationSource.path}")
    val representativeSource = repositoryRoot.resolve(
        GENERIC_OWNER_OCTO_TREE_REPRESENTATIVE_SOURCE_PATH,
    ).canonicalFile
    check(representativeSource.isFile &&
            representativeSource.path.startsWith(repositoryRoot.canonicalPath + File.separator)) {
        "The closed OctoTree representative source is missing or escaped the repository"
    }
    check(listOf(
        applicationSource,
        candidateProducerSource,
        candidateProducer,
        candidateConsumerSource,
        candidateConsumer,
        physicalFamilyArtifact,
        callRouteManifest,
        erasedProducer,
        erasedConsumerSource,
        erasedConsumer,
        runtime,
        stdlib,
    ).all(File::isFile)) {
        "The OctoTree application bundle requires complete candidate, erased, and platform products"
    }

    fun stage(source: File, name: String): File = directory.resolve(name).also { destination ->
        if (source.canonicalFile != destination.canonicalFile) {
            if (destination.exists()) {
                check(destination.isFile && destination.readBytes().contentEquals(source.readBytes())) {
                    "The OctoTree bundle found a stale staged dependency at ${destination.path}"
                }
            } else {
                source.copyTo(destination)
            }
        }
    }

    val stagedApplicationSource = stage(
        applicationSource,
        GENERIC_OWNER_OCTO_TREE_APPLICATION_SOURCE_FILE,
    )
    val stagedRepresentativeSource = stage(
        representativeSource,
        GENERIC_OWNER_OCTO_TREE_REPRESENTATIVE_SOURCE_FILE,
    )
    val stagedCandidateProducer = stage(candidateProducer, "SnapshotProducer.dll")
    val stagedErasedProducer = stage(erasedProducer, GENERIC_OWNER_ERASED_PRODUCER_FILE)
    val stagedRuntime = stage(runtime, runtime.name)
    val stagedStdlib = stage(stdlib, stdlib.name)
    val candidateRuntimeConfig = if (target == DotNetTarget.NET10_0) {
        candidateConsumer.resolveSibling("${candidateConsumer.nameWithoutExtension}.runtimeconfig.json").also { file ->
            check(file.isFile) { "The OctoTree candidate measurement lacks its runtime config" }
        }
    } else {
        null
    }
    val erasedCSharpRuntimeConfig = if (target == DotNetTarget.NET10_0) {
        erasedConsumer.resolveSibling("${erasedConsumer.nameWithoutExtension}.runtimeconfig.json").also { file ->
            check(file.isFile) { "The OctoTree erased measurement lacks its runtime config" }
        }
    } else {
        null
    }
    val globalJson = if (target == DotNetTarget.NET10_0) {
        directory.resolve("global.json").apply {
            writeText(
                """
                {
                  "sdk": {
                    "version": "10.0.100",
                    "rollForward": "disable",
                    "allowPrerelease": false
                  }
                }
                """.trimIndent()
            )
        }
    } else {
        null
    }

    val manifest = directory.resolve(GENERIC_OWNER_APPLICATION_MANIFEST_FILE).apply {
        writeText(buildString {
            appendLine("schema=3")
            appendLine("corpusKind=octo-tree")
            appendLine("workloadVersion=2")
            appendLine("sdkVersion=${if (target == DotNetTarget.NET10_0) "10.0.100" else "framework-clr"}")
            appendLine("targetProfile=${target.name}")
            fun hash(name: String, file: File) {
                appendLine("$name=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(file.readBytes())}")
            }
            hash("applicationSourceSha256", stagedApplicationSource)
            hash("representativeSourceSha256", stagedRepresentativeSource)
            hash("candidateProducerSourceSha256", candidateProducerSource)
            hash("candidateProducerSha256", stagedCandidateProducer)
            hash("candidateConsumerSha256", candidateConsumer)
            hash("candidateSourceSha256", candidateConsumerSource)
            hash("physicalFamilyArtifactSha256", physicalFamilyArtifact)
            hash("callRouteManifestSha256", callRouteManifest)
            hash("erasedProducerSha256", stagedErasedProducer)
            hash("erasedCSharpSourceSha256", erasedConsumerSource)
            hash("erasedCSharpAssemblySha256", erasedConsumer)
            hash("runtimeSha256", stagedRuntime)
            hash("stdlibSha256", stagedStdlib)
            candidateRuntimeConfig?.let { hash("candidateRuntimeConfigSha256", it) }
            erasedCSharpRuntimeConfig?.let { hash("erasedCSharpRuntimeConfigSha256", it) }
            globalJson?.let { hash("globalJsonSha256", it) }
        }.trimEnd())
    }
    val bundleFiles = listOf(
        stagedApplicationSource,
        stagedRepresentativeSource,
        candidateProducerSource,
        stagedCandidateProducer,
        candidateConsumerSource,
        candidateConsumer,
        physicalFamilyArtifact,
        callRouteManifest,
        stagedErasedProducer,
        erasedConsumerSource,
        erasedConsumer,
        stagedRuntime,
        stagedStdlib,
        manifest,
    ) + listOfNotNull(
        candidateRuntimeConfig,
        erasedCSharpRuntimeConfig,
        globalJson,
    )
    check(bundleFiles.map(File::getName).toSet().size == bundleFiles.size && bundleFiles.all(File::isFile)) {
        "The OctoTree application bundle is incomplete or has colliding file names"
    }
    check(!exportDirectory.exists() || exportDirectory.isDirectory) {
        "Generic-owner application export path is not a directory: $exportDirectory"
    }
    check(exportDirectory.mkdirs() || exportDirectory.isDirectory) {
        "Cannot create generic-owner application export directory: $exportDirectory"
    }
    check(exportDirectory.list()?.isEmpty() == true) {
        "Generic-owner application export directory must be empty: $exportDirectory"
    }
    bundleFiles.forEach { file -> file.copyTo(exportDirectory.resolve(file.name), overwrite = false) }
}

private fun validateGenericOwnerRepresentativeArrayCopyPrototype(
    prototypes: List<DotNetGenericOwnerPrototypeSnapshot>,
    callRoutes: List<DotNetGenericOwnerCallRouteSnapshot>,
) {
    val owner = prototypes.singleOrNull { prototype ->
        prototype.ownerName.endsWith(".ArrayCopyBenchmark.CustomArray")
    } ?: return
    val values = owner.states.singleOrNull { state -> state.fieldName == "values" }
    check(values?.requirement == DotNetGenericOwnerStateCarrierRequirement.SEMANTIC_OBJECT_REQUIRED) {
        "ArrayCopy's unchecked object-vector initialization must keep one semantic values state: $owner"
    }
    check(values.exactTypedCarrierType == null) {
        "ArrayCopy's Array<T?> state must not be mistaken for a structural CLR T[] carrier: $values"
    }
    check(values.initializers.singleOrNull()?.let { initializer ->
        initializer.kind == DotNetGenericOwnerPrototypeStateInitializerKind.UNSUPPORTED &&
                initializer.fixedElementCount == null
    } == true) {
        "ArrayCopy's unchecked object-vector initializer must remain outside the typed recipe grammar: $values"
    }
    val add = owner.members.single { member -> member.sourceName == "add" }
    check(add.roles == setOf(
        DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
        DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
    ) &&
            add.parameterSlotDomains == listOf(
                DotNetGenericOwnerPhysicalSlotDomain.DECLARATION_INDEPENDENT,
                DotNetGenericOwnerPhysicalSlotDomain.STRICT_OWNER_INPUT,
            )) {
        "ArrayCopy.add must remain a strict exact entry over its semantic array state: $add"
    }
    val routeCounts = callRoutes.groupingBy { route -> route.routeRequirement }.eachCount()
    check(routeCounts == mapOf(
        DotNetGenericOwnerCallRouteRequirement.EXACT_TYPED_ENTRY to 16,
        DotNetGenericOwnerCallRouteRequirement.EXTERNAL_FAMILY_RECORD_REQUIRED to 11,
    )) {
        "The representative ArrayCopy static call-route census changed: $routeCounts"
    }
}

private fun validateGenericOwnerHardestModelPrototype(
    prototypes: List<DotNetGenericOwnerPrototypeSnapshot>,
    callRoutes: List<DotNetGenericOwnerCallRouteSnapshot>,
) {
    fun DotNetGenericOwnerPrototypeSnapshot.hasSimpleName(name: String): Boolean =
        ownerName == name || ownerName.endsWith(".$name")

    check(callRoutes.map { route -> route.callSiteIndex }.sorted() == callRoutes.indices.toList()) {
        "Generic-owner call-site indices must be unique and dense within one compilation: $callRoutes"
    }

    fun requireCallRoute(
        callerName: String,
        calleeOwnerName: String,
        calleeName: String,
        receiverProvenances: Set<DotNetGenericOwnerCallReceiverProvenance>,
        routeRequirement: DotNetGenericOwnerCallRouteRequirement,
    ) {
        val matching = callRoutes.filter { route ->
            (route.callerName == callerName || route.callerName.endsWith(".$callerName")) &&
                    (route.calleeOwnerName == calleeOwnerName || route.calleeOwnerName.endsWith(".$calleeOwnerName")) &&
                    route.calleeName == calleeName
        }
        check(matching.singleOrNull()?.let { route ->
            route.receiverProvenance in receiverProvenances && route.routeRequirement == routeRequirement
        } == true) {
            "Expected $callerName -> $calleeOwnerName.$calleeName to be " +
                    "$receiverProvenances/$routeRequirement, found $matching"
        }
    }

    if (prototypes.any { prototype -> prototype.hasSimpleName("HostileTypedStore") }) {
        requireCallRoute(
            "readInvariantTypedStore",
            "HostileTypedStore",
            "read",
            setOf(DotNetGenericOwnerCallReceiverProvenance.EXACT_CONSTRUCTION),
            DotNetGenericOwnerCallRouteRequirement.EXACT_TYPED_ENTRY,
        )
        requireCallRoute(
            "readStarTypedStore",
            "HostileTypedStore",
            "read",
            setOf(
                DotNetGenericOwnerCallReceiverProvenance.SEMANTIC_VIEW,
                DotNetGenericOwnerCallReceiverProvenance.UNRESOLVED,
            ),
            DotNetGenericOwnerCallRouteRequirement.SEMANTIC_CAPABILITY,
        )
        requireCallRoute(
            "readMergedTypedStore",
            "HostileTypedStore",
            "read",
            setOf(
                DotNetGenericOwnerCallReceiverProvenance.SEMANTIC_VIEW,
                DotNetGenericOwnerCallReceiverProvenance.UNRESOLVED,
            ),
            DotNetGenericOwnerCallRouteRequirement.SEMANTIC_CAPABILITY,
        )
        requireCallRoute(
            "readExactTypedStoreField",
            "HostileTypedStore",
            "read",
            setOf(DotNetGenericOwnerCallReceiverProvenance.EXACT_CONSTRUCTION),
            DotNetGenericOwnerCallRouteRequirement.EXACT_TYPED_ENTRY,
        )
        requireCallRoute(
            "readStarTypedStoreField",
            "HostileTypedStore",
            "read",
            setOf(
                DotNetGenericOwnerCallReceiverProvenance.SEMANTIC_VIEW,
                DotNetGenericOwnerCallReceiverProvenance.UNRESOLVED,
            ),
            DotNetGenericOwnerCallRouteRequirement.SEMANTIC_CAPABILITY,
        )
        requireCallRoute(
            "readReturnedTypedStore",
            "HostileTypedStore",
            "read",
            setOf(DotNetGenericOwnerCallReceiverProvenance.EXACT_CONSTRUCTION),
            DotNetGenericOwnerCallRouteRequirement.EXACT_TYPED_ENTRY,
        )
        requireCallRoute(
            "labelStarUnsafeStore",
            "HostileUnsafeStore",
            "label",
            setOf(
                DotNetGenericOwnerCallReceiverProvenance.SEMANTIC_VIEW,
                DotNetGenericOwnerCallReceiverProvenance.UNRESOLVED,
            ),
            DotNetGenericOwnerCallRouteRequirement.SEMANTIC_CAPABILITY,
        )
    }

    prototypes.singleOrNull { prototype -> prototype.hasSimpleName("WidenedProbe") }?.let { probe ->
        val states = probe.states.associateBy { state -> state.fieldName }
        val expected = states["expected"]
        val lastPacket = states["lastPacket"]
        check(states.keys == setOf("expected", "lastPacket") && expected?.let { state ->
            state.isFinal &&
                    state.requirement ==
                    DotNetGenericOwnerStateCarrierRequirement.TYPED_STORAGE_PRODUCER_GRAPH_PROVEN &&
                    state.exactTypedCarrierType?.kind ==
                    DotNetGenericOwnerPrototypeTypeKind.OWNER_TYPE_PARAMETER
        } == true && lastPacket?.let { state ->
            !state.isFinal &&
                    state.requirement ==
                    DotNetGenericOwnerStateCarrierRequirement.DECLARATION_INDEPENDENT_STORAGE &&
                    state.exactTypedCarrierType?.kind == DotNetGenericOwnerPrototypeTypeKind.OBJECT &&
                    state.initializers.singleOrNull()?.kind ==
                    DotNetGenericOwnerPrototypeStateInitializerKind.DEFAULT_NULL_REFERENCE
        } == true) {
            "WidenedProbe must separate owner-dependent expected:T from exact lastPacket:Any? state: ${probe.states}"
        }
    }

    prototypes.singleOrNull { prototype -> prototype.hasSimpleName("ConsumerUnsafeLeaf") }?.let { consumer ->
        check(consumer.disposition ==
                DotNetGenericOwnerCandidateDisposition.REQUIRES_EXTERNAL_OVERRIDE_BINDING_SCHEMA) {
            "A generic consumer subclass must remain blocked until the producer family binding schema is available: $consumer"
        }
        mapOf(
            "writeUnsafe" to setOf(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY),
            "read" to setOf(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY),
            "echo" to setOf(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY),
            "label" to setOf(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY),
        ).forEach { entry ->
            val memberName = entry.key
            val expectedRoles = entry.value
            val member = consumer.members.single { candidate -> candidate.sourceName == memberName }
            check(member.overrideBindings.map { binding -> binding.role }.toSet() == expectedRoles &&
                    member.overrideBindings.all { binding ->
                        binding.targetKind == DotNetGenericOwnerOverrideTargetKind.EXTERNAL_LOGICAL_BINDING_REQUIRED &&
                        binding.overriddenLogicalBindingKey != null
                    }) {
                "ConsumerUnsafeLeaf.$memberName must retain an external logical family requirement: $member"
            }
        }
    }

    // This is a test-fixture assertion, not a compiler selector. The normal backend constructs
    // snapshots for every generic class and always emits the erased production ABI. When the
    // hostile oracle is present, require its exact detached prototype before discarding snapshots.
    if (prototypes.none { prototype -> prototype.hasSimpleName("HostileUnsafeProducer") }) return

    val unsafeProducer = prototypes.single { prototype ->
        prototype.hasSimpleName("HostileUnsafeProducer")
    }
    val producerState = unsafeProducer.states.single()
    check(producerState.requirement ==
            DotNetGenericOwnerStateCarrierRequirement.TYPED_STORAGE_PRODUCER_GRAPH_PROVEN &&
            producerState.initializationWriterLabels == listOf("<field-initializer:expected>") &&
            producerState.writes.singleOrNull()?.let { write ->
                write.producerName == "<field-initializer:expected>" &&
                        write.provenance == DotNetGenericOwnerWriteValueProvenance.PHYSICALLY_TYPED
            } == true &&
            !producerState.externalAccessGraphRequired) {
        "HostileUnsafeProducer's private read-only state must remain typed after complete producer analysis: $producerState"
    }
    val mixed = prototypes.single { prototype -> prototype.hasSimpleName("HostileMixed") }
    val describe = mixed.members.single { member -> member.sourceName == "describe" }
    check(describe.returnSlotDomain == DotNetGenericOwnerPhysicalSlotDomain.DECLARATION_INDEPENDENT &&
            describe.parameterSlotDomains == listOf(
                DotNetGenericOwnerPhysicalSlotDomain.STRICT_OWNER_INPUT,
                DotNetGenericOwnerPhysicalSlotDomain.BROAD_CANDIDATE_INPUT,
            )) {
        "HostileMixed.describe must classify strict and broad owner inputs independently: $describe"
    }

    val nullableDerived = prototypes.single { prototype ->
        prototype.hasSimpleName("HostileNullableDerived")
    }
    check(nullableDerived.disposition ==
            DotNetGenericOwnerCandidateDisposition.BLOCKED_METADATA_FIXED_CONDITIONAL_SUPERTYPE) {
        "HostileNullableDerived must remain blocked by its metadata-fixed T? supertype"
    }
    check(nullableDerived.metadataFixedConditionalSupertypeCount == 1) {
        "HostileNullableDerived must record exactly one metadata-fixed conditional supertype"
    }
    val conditionalBase = nullableDerived.directSupertypes.single()
    check(conditionalBase.kind == DotNetGenericOwnerDirectSupertypeKind.BASE_CLASS &&
            (conditionalBase.logicalClassifierKey != null || nullableDerived.logicalBindingKey == null) &&
            conditionalBase.disposition ==
            DotNetGenericOwnerPrototypeSupertypeDisposition.CONDITIONAL_OPEN_NULLABLE_ARGUMENT &&
            conditionalBase.exactPhysicalType == null &&
            conditionalBase.nullableReferenceFlags == null &&
            conditionalBase.conditionalOwnerParameterIndices == listOf(0)) {
        "HostileNullableDerived must retain the exact reason its T? base cannot become one CLR TypeSpec: " +
                conditionalBase
    }
    val directBaseRead = nullableDerived.members.single { member ->
        member.sourceName == "readDirectFromBase"
    }
    check(directBaseRead.directSuperCallCount == 1) {
        "HostileNullableDerived.readDirectFromBase must retain one exact direct-super target"
    }

    val nullableReferenceBase = prototypes.single { prototype ->
        prototype.hasSimpleName("HostileNullableReferenceBase")
    }
    val nullableReferenceDerived = prototypes.single { prototype ->
        prototype.hasSimpleName("HostileNullableReferenceDerived")
    }
    val referenceBaseEdge = nullableReferenceDerived.directSupertypes.single { supertype ->
        supertype.kind == DotNetGenericOwnerDirectSupertypeKind.BASE_CLASS
    }
    val referenceInterfaceEdge = nullableReferenceDerived.directSupertypes.single { supertype ->
        supertype.kind == DotNetGenericOwnerDirectSupertypeKind.INTERFACE
    }
    fun hasNestedNullableReferenceTransform(
        edge: org.jetbrains.kotlin.backend.dotnet.DotNetGenericOwnerPrototypeSupertypeSnapshot,
        nestedClassifierKey: String,
    ): Boolean {
        val physicalType = edge.exactPhysicalType ?: return false
        val nestedType = physicalType.arguments.singleOrNull() ?: return false
        return edge.disposition == DotNetGenericOwnerPrototypeSupertypeDisposition.EXACT_PHYSICAL_EDGE &&
                edge.nullableReferenceFlags == listOf(
                    DotNetNullableReferenceFlag.NON_NULL,
                    DotNetNullableReferenceFlag.NULLABLE,
                    DotNetNullableReferenceFlag.NON_NULL,
                ) && nestedType.kind == DotNetGenericOwnerPrototypeTypeKind.LOGICAL_GENERIC_CLASSIFIER &&
                nestedType.logicalClassifierKey == nestedClassifierKey &&
                nestedType.arguments.singleOrNull()?.let { argument ->
                    argument.kind == DotNetGenericOwnerPrototypeTypeKind.OWNER_TYPE_PARAMETER &&
                            argument.parameterIndex == 0
                } == true
    }
    val nestedReferenceGraphIsComplete = if (nullableReferenceDerived.logicalBindingKey == null) {
        nullableReferenceDerived.directSupertypes.all { supertype ->
            supertype.disposition == DotNetGenericOwnerPrototypeSupertypeDisposition.UNSUPPORTED_PHYSICAL_EDGE &&
                    supertype.logicalClassifierKey == null
        }
    } else {
        referenceBaseEdge.logicalClassifierKey == nullableReferenceBase.logicalBindingKey &&
                hasNestedNullableReferenceTransform(
                    referenceBaseEdge,
                    checkNotNull(prototypes.single {
                        prototype -> prototype.hasSimpleName("HostileTypedStore")
                    }.logicalBindingKey),
                ) && referenceInterfaceEdge.logicalClassifierKey != null &&
                hasNestedNullableReferenceTransform(
                    referenceInterfaceEdge,
                    checkNotNull(prototypes.single {
                        prototype -> prototype.hasSimpleName("HostileAbstractPropertyStorage")
                    }.logicalBindingKey),
                )
    }
    check(nullableReferenceBase.directSupertypes.single().let { supertype ->
        supertype.kind == DotNetGenericOwnerDirectSupertypeKind.BASE_CLASS &&
                supertype.logicalClassifierKey == null &&
                supertype.disposition == DotNetGenericOwnerPrototypeSupertypeDisposition.EXACT_PHYSICAL_EDGE &&
                supertype.exactPhysicalType == DotNetGenericOwnerPrototypeTypeSnapshot.objectType() &&
                supertype.nullableReferenceFlags == listOf(DotNetNullableReferenceFlag.NON_NULL)
    } && nestedReferenceGraphIsComplete) {
        "The nested nullable base/interface graph lost its exact physical transform: " +
                "$nullableReferenceBase / $nullableReferenceDerived"
    }

    val unsafeStore = prototypes.single { prototype ->
        prototype.hasSimpleName("HostileUnsafeStore")
    }
    val primaryConstructor = unsafeStore.constructors.single { constructor ->
        constructor.parameterSlotDomains == listOf(DotNetGenericOwnerPhysicalSlotDomain.STRICT_OWNER_INPUT)
    }
    val secondaryConstructor = unsafeStore.constructors.single { constructor ->
        constructor.parameterSlotDomains == listOf(
            DotNetGenericOwnerPhysicalSlotDomain.STRICT_OWNER_INPUT,
            DotNetGenericOwnerPhysicalSlotDomain.DECLARATION_INDEPENDENT,
        )
    }
    check(!primaryConstructor.delegatesToThis && secondaryConstructor.delegatesToThis &&
            secondaryConstructor.delegatedConstructorLogicalBindingKey == primaryConstructor.logicalBindingKey) {
        "HostileUnsafeStore must retain exact primary/secondary construction joins: ${unsafeStore.constructors}"
    }
    check(primaryConstructor.exactPathUnboundSignature?.parameterSlots?.singleOrNull()?.type?.kind ==
            DotNetGenericOwnerPrototypeTypeKind.OWNER_TYPE_PARAMETER &&
            secondaryConstructor.exactPathUnboundSignature?.parameterSlots?.map { slot -> slot.type.kind } == listOf(
                DotNetGenericOwnerPrototypeTypeKind.OWNER_TYPE_PARAMETER,
                DotNetGenericOwnerPrototypeTypeKind.INT32,
            )) {
        "HostileUnsafeStore constructors must use compiler-derived owner/int carriers"
    }
    check(unsafeStore.disposition ==
            DotNetGenericOwnerCandidateDisposition.BLOCKED_OPEN_OUTPUT_STATE_COHERENCE) {
        "HostileUnsafeStore must remain blocked until typed/semantic output overrides are coherent"
    }
    val unsafeState = unsafeStore.states.single()
    check(unsafeState.requirement == DotNetGenericOwnerStateCarrierRequirement.SEMANTIC_OBJECT_REQUIRED) {
        "HostileUnsafeStore's one state field must accept widened semantic writes"
    }
    check(unsafeState.fieldName == "stored" &&
            unsafeState.directWriterNames == listOf("<set-stored>") &&
            unsafeState.semanticReachableWriterNames == listOf("<set-stored>") &&
            unsafeState.initializationWriterLabels == listOf("<field-initializer:stored>") &&
            unsafeState.writes.associate { write -> write.producerName to write.provenance } == mapOf(
                "<set-stored>" to DotNetGenericOwnerWriteValueProvenance.SEMANTIC_OBJECT,
                "<field-initializer:stored>" to DotNetGenericOwnerWriteValueProvenance.PHYSICALLY_TYPED,
            ) &&
            !unsafeState.externalAccessGraphRequired) {
        "HostileUnsafeStore's private state write must be found through its lowered setter call graph: $unsafeState"
    }

    val write = unsafeStore.members.single { member -> member.sourceName == "writeUnsafe" }
    check(write.policy == DotNetGenericOwnerMemberPolicy.SEMANTIC_BODY)
    check(write.roles == setOf(
        DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
        DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK,
        DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
    ))
    check(write.semanticHookReasons ==
            setOf(DotNetGenericOwnerSemanticHookReason.GENERAL_WIDENED_BODY))
    check(write.typedRetainsOwnerDependentInput && write.semanticErasesOwnerDependentInput)
    check(write.returnSlotDomain == DotNetGenericOwnerPhysicalSlotDomain.DECLARATION_INDEPENDENT &&
            write.parameterSlotDomains == listOf(DotNetGenericOwnerPhysicalSlotDomain.BROAD_CANDIDATE_INPUT)) {
        "HostileUnsafeStore.writeUnsafe must retain its exact broad-candidate domain vector: $write"
    }
    check(write.exactPathUnboundSignatures?.keys == write.roles &&
            write.exactPathUnboundSignatures?.get(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY)
                ?.parameterSlots?.singleOrNull()?.type?.kind ==
                DotNetGenericOwnerPrototypeTypeKind.OWNER_TYPE_PARAMETER &&
            write.exactPathUnboundSignatures?.get(DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER)
                ?.parameterSlots?.singleOrNull()?.type?.kind == DotNetGenericOwnerPrototypeTypeKind.OBJECT) {
        "HostileUnsafeStore.writeUnsafe must retain its compiler-derived typed/capability carriers"
    }
    check(write.requiresDirectSuperTargets)
    check(write.directStateWriteNames.isEmpty() &&
            write.directProducerCallNames == listOf("installUnchecked") &&
            write.transitiveStateWriteNames == listOf("stored")) {
        "HostileUnsafeStore.writeUnsafe must reach, but not directly contain, its semantic state write: $write"
    }

    val installer = unsafeStore.members.single { member -> member.sourceName == "installUnchecked" }
    check(installer.policy == DotNetGenericOwnerMemberPolicy.STRICT_TYPED &&
            installer.directStateWriteNames.isEmpty() &&
            installer.directProducerCallNames == listOf("<set-stored>") &&
            installer.transitiveStateWriteNames == listOf("stored") &&
            installer.reachableFromSemanticEntry) {
        "HostileUnsafeStore.installUnchecked must be tainted by the widened entry call closure: $installer"
    }
    val storedSetter = unsafeStore.members.single { member -> member.sourceName == "<set-stored>" }
    check(storedSetter.policy == DotNetGenericOwnerMemberPolicy.STRICT_TYPED &&
            storedSetter.directStateWriteNames == listOf("stored") &&
            storedSetter.reachableFromSemanticEntry) {
        "The private lowered setter must be a strict helper reached from, not itself classified as, a semantic entry: $storedSetter"
    }

    val typedStore = prototypes.single { prototype ->
        prototype.hasSimpleName("HostileTypedStore")
    }
    val typedState = typedStore.states.single { state -> state.fieldName == "stored" }
    val volatileState = typedStore.states.single { state -> state.fieldName == "published" }
    check(typedState.requirement ==
            DotNetGenericOwnerStateCarrierRequirement.TYPED_STORAGE_PRODUCER_GRAPH_PROVEN &&
            typedState.memorySemantics == DotNetGenericOwnerStateMemorySemantics.PLAIN &&
            typedState.writes.associate { write -> write.producerName to write.provenance } == mapOf(
                "<set-stored>" to DotNetGenericOwnerWriteValueProvenance.PHYSICALLY_TYPED,
                "<field-initializer:stored>" to DotNetGenericOwnerWriteValueProvenance.PHYSICALLY_TYPED,
            )) {
        "HostileTypedStore must prove both initializer and function writes physically typed: $typedState"
    }
    check(typedStore.disposition == DotNetGenericOwnerCandidateDisposition.REQUIRES_STATE_MEMORY_MODEL_PROOF &&
            volatileState.requirement ==
            DotNetGenericOwnerStateCarrierRequirement.VOLATILE_OBJECT_STORAGE_REQUIRED &&
            volatileState.memorySemantics == DotNetGenericOwnerStateMemorySemantics.VOLATILE &&
            volatileState.exactTypedCarrierType?.kind ==
            DotNetGenericOwnerPrototypeTypeKind.OWNER_TYPE_PARAMETER &&
            volatileState.writes.associate { write -> write.producerName to write.provenance } == mapOf(
                "<set-published>" to DotNetGenericOwnerWriteValueProvenance.PHYSICALLY_TYPED,
                "<field-initializer:published>" to DotNetGenericOwnerWriteValueProvenance.PHYSICALLY_TYPED,
            )) {
        "HostileTypedStore must keep volatile T state on one ordered object carrier: $volatileState"
    }
    val typedWrite = typedStore.members.single { member -> member.sourceName == "write" }
    check(typedWrite.directProducerCallNames == listOf("installBoxed") &&
            typedWrite.transitiveStateWriteNames == listOf("stored")) {
        "HostileTypedStore.write must retain its boxed helper write chain: $typedWrite"
    }

    val unsafeDerived = prototypes.singleOrNull { prototype ->
        prototype.hasSimpleName("HostileUnsafeDerived")
    } ?: prototypes.single { prototype ->
        prototype.hasSimpleName("HostileUnsafeMid")
    }
    check(unsafeDerived.constructors.singleOrNull()?.let { constructor ->
        !constructor.delegatesToThis &&
                constructor.parameterSlotDomains ==
                listOf(DotNetGenericOwnerPhysicalSlotDomain.STRICT_OWNER_INPUT) &&
                constructor.delegatedConstructorLogicalBindingKey == primaryConstructor.logicalBindingKey &&
                constructor.delegatedOwnerName?.endsWith("HostileUnsafeStore") == true
    } == true) {
        "${unsafeDerived.ownerName} must retain its exact generic base-constructor join: ${unsafeDerived.constructors}"
    }
    listOf("writeUnsafe", "read").forEach { memberName ->
        val member = unsafeDerived.members.single { candidate -> candidate.sourceName == memberName }
        check(DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK in member.roles &&
                DotNetGenericOwnerSemanticHookReason.INHERITED_SEMANTIC_OVERRIDE in member.semanticHookReasons &&
                member.overrideBindings.map { binding -> binding.role }.toSet() == setOf(
                    DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
                    DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK,
                ) &&
                member.overrideBindings.all { binding ->
                    binding.targetKind == DotNetGenericOwnerOverrideTargetKind.LOCAL_DETACHED_PROTOTYPE
                } && member.directSuperCalls.size == member.directSuperCallCount &&
                member.directSuperCalls.singleOrNull()?.let { call ->
                    call.logicalOwnerName.endsWith("HostileUnsafeStore") &&
                            call.superQualifierName.endsWith("HostileUnsafeStore")
                } == true) {
            "${unsafeDerived.ownerName}.$memberName must bind typed and inherited semantic families independently: $member"
        }
    }

    val read = unsafeStore.members.single { member -> member.sourceName == "read" }
    check(read.policy == DotNetGenericOwnerMemberPolicy.STRICT_TYPED)
    check(read.roles == setOf(
        DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
        DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK,
        DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
    ))
    check(read.semanticHookReasons ==
            setOf(DotNetGenericOwnerSemanticHookReason.PAIRED_OPEN_OUTPUT_STATE))
    check(read.typedRetainsOwnerDependentOutput && read.semanticErasesOwnerDependentOutput)
    check(read.returnSlotDomain == DotNetGenericOwnerPhysicalSlotDomain.STRICT_OWNER_OUTPUT &&
            read.parameterSlotDomains.isEmpty()) {
        "HostileUnsafeStore.read must retain its exact strict-output domain vector: $read"
    }
    check(read.requiresDirectSuperTargets)

    val exposedGetter = unsafeStore.members.singleOrNull { member ->
        member.physicalPropertyName == "exposed" &&
                member.propertyAccessorKind == DotNetGenericOwnerPropertyAccessorKind.GETTER
    } ?: error("HostileUnsafeStore has no unique exposed getter: ${unsafeStore.members}")
    val exposedSetter = unsafeStore.members.singleOrNull { member ->
        member.physicalPropertyName == "exposed" &&
                member.propertyAccessorKind == DotNetGenericOwnerPropertyAccessorKind.SETTER
    } ?: error("HostileUnsafeStore has no unique exposed setter: ${unsafeStore.members}")
    check(exposedGetter.policy == DotNetGenericOwnerMemberPolicy.STRICT_TYPED &&
            exposedGetter.returnSlotDomain == DotNetGenericOwnerPhysicalSlotDomain.STRICT_OWNER_OUTPUT &&
            exposedGetter.roles == setOf(
                DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
                DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK,
                DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
            ) && exposedGetter.semanticHookReasons == setOf(
                DotNetGenericOwnerSemanticHookReason.PAIRED_OPEN_OUTPUT_STATE,
            )) {
        "HostileUnsafeStore.exposed getter must retain a paired raw semantic output: $exposedGetter"
    }
    check(exposedSetter.policy == DotNetGenericOwnerMemberPolicy.SEMANTIC_BODY &&
            exposedSetter.parameterSlotDomains == listOf(
                DotNetGenericOwnerPhysicalSlotDomain.BROAD_CANDIDATE_INPUT,
            ) && exposedSetter.roles == setOf(
                DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
                DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK,
                DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
            ) && exposedSetter.semanticHookReasons == setOf(
                DotNetGenericOwnerSemanticHookReason.GENERAL_WIDENED_BODY,
            ) && exposedSetter.transitiveStateWriteNames == listOf("stored")) {
        "HostileUnsafeStore.exposed setter must retain its widened semantic state write: $exposedSetter"
    }
    check(exposedGetter.exactPathUnboundSignatures?.let { signatures ->
        signatures.getValue(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY).returnSlot.let { slot ->
            slot.type.kind == DotNetGenericOwnerPrototypeTypeKind.OWNER_TYPE_PARAMETER &&
                    slot.nullableReferenceFlags == listOf(DotNetNullableReferenceFlag.NON_NULL)
        } && signatures.getValue(DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK).returnSlot.let { slot ->
            slot.type.kind == DotNetGenericOwnerPrototypeTypeKind.OBJECT &&
                    slot.nullableReferenceFlags == listOf(DotNetNullableReferenceFlag.NULLABLE)
        }
    } == true && exposedSetter.exactPathUnboundSignatures?.let { signatures ->
        signatures.getValue(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY).parameterSlots.single().let { slot ->
            slot.type.kind == DotNetGenericOwnerPrototypeTypeKind.OWNER_TYPE_PARAMETER &&
                    slot.nullableReferenceFlags == listOf(DotNetNullableReferenceFlag.NON_NULL)
        } && signatures.getValue(DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK)
            .parameterSlots.single().let { slot ->
                slot.type.kind == DotNetGenericOwnerPrototypeTypeKind.OBJECT &&
                        slot.nullableReferenceFlags == listOf(DotNetNullableReferenceFlag.NULLABLE)
            }
    } == true) {
        "HostileUnsafeStore.exposed lost its typed/semantic nullable carrier split"
    }

    val abstractProperty = prototypes.single { prototype ->
        prototype.hasSimpleName("HostileAbstractProperty")
    }
    check(abstractProperty.physicalDispatch == DotNetGenericOwnerPhysicalTypeDispatch.ABSTRACT &&
            abstractProperty.states.isEmpty()) {
        "HostileAbstractProperty must remain a stateless abstract contract: $abstractProperty"
    }
    val abstractPropertyGetter = abstractProperty.members.single { member ->
        member.physicalPropertyName == "exposed" &&
                member.propertyAccessorKind == DotNetGenericOwnerPropertyAccessorKind.GETTER
    }
    val abstractPropertySetter = abstractProperty.members.single { member ->
        member.physicalPropertyName == "exposed" &&
                member.propertyAccessorKind == DotNetGenericOwnerPropertyAccessorKind.SETTER
    }
    check(abstractPropertyGetter.isAbstract && abstractPropertySetter.isAbstract &&
            abstractPropertyGetter.roles == setOf(
                DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
                DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK,
                DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
            ) && abstractPropertyGetter.semanticHookReasons == setOf(
                DotNetGenericOwnerSemanticHookReason.ABSTRACT_BROAD_PROPERTY_OBLIGATION,
            ) && abstractPropertySetter.roles == setOf(
                DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
                DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK,
                DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
            ) && abstractPropertySetter.semanticHookReasons == setOf(
                DotNetGenericOwnerSemanticHookReason.GENERAL_WIDENED_BODY,
            )) {
        "HostileAbstractProperty must retain both abstract typed and semantic obligations: " +
                "$abstractPropertyGetter / $abstractPropertySetter"
    }
    val abstractPropertyStorage = prototypes.single { prototype ->
        prototype.hasSimpleName("HostileAbstractPropertyStorage")
    }
    val storagePropertyAccessors = abstractPropertyStorage.members.filter { member ->
        member.physicalPropertyName == "exposed" && member.propertyAccessorKind != null
    }
    check(storagePropertyAccessors.size == 2 && storagePropertyAccessors.all { member ->
        !member.isAbstract &&
                DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK in member.roles &&
                DotNetGenericOwnerSemanticHookReason.INHERITED_SEMANTIC_OVERRIDE in member.semanticHookReasons
    }) {
        "HostileAbstractPropertyStorage did not inherit the complete broad property family: " +
                storagePropertyAccessors
    }

    val collidingOverloads = unsafeStore.members.filter { member -> member.sourceName == "collide" }
    val collisionSignatures = collidingOverloads.map { member -> member.exactPathUnboundSignatures }
    val collisionSignatureShapeIsComplete = when {
        collisionSignatures.all { signatures -> signatures == null } -> true
        collisionSignatures.any { signatures -> signatures == null } -> false
        else -> {
            val typedCollisionParameters = collisionSignatures.map { signatures ->
                checkNotNull(signatures)
                    .getValue(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY)
                    .parameterSlots.single().type
            }
            val semanticCollisionParameters = collisionSignatures.map { signatures ->
                checkNotNull(signatures)
                    .getValue(DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK)
                    .parameterSlots.single().type
            }
            typedCollisionParameters.toSet().size == 2 && typedCollisionParameters.all { type ->
                type.kind == DotNetGenericOwnerPrototypeTypeKind.LOGICAL_GENERIC_CLASSIFIER
            } && semanticCollisionParameters == listOf(
                DotNetGenericOwnerPrototypeTypeSnapshot.objectType(),
                DotNetGenericOwnerPrototypeTypeSnapshot.objectType(),
            )
        }
    }
    check(collidingOverloads.size == 2 && collidingOverloads.map { member -> member.physicalBaseName }
        .distinct() == listOf("collide") && collidingOverloads.all { member -> member.roles == setOf(
            DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
            DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK,
            DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
        ) } && collisionSignatureShapeIsComplete) {
        "HostileUnsafeStore.collide did not retain distinct typed overloads and one erased semantic shape: " +
                collidingOverloads
    }

    val echo = unsafeStore.members.single { member -> member.sourceName == "echo" }
    check(echo.returnSlotDomain == DotNetGenericOwnerPhysicalSlotDomain.STRICT_OWNER_OUTPUT &&
            echo.parameterSlotDomains == listOf(DotNetGenericOwnerPhysicalSlotDomain.BROAD_CANDIDATE_INPUT)) {
        "HostileUnsafeStore.echo must retain its nested broad-input/strict-output domain vector: $echo"
    }
    val systemArray = DotNetGenericOwnerPrototypeTypeSnapshot.systemArrayType()
    check(checkNotNull(echo.exactPathUnboundSignatures).values.all { signature ->
        signature.returnSlot.type == systemArray &&
                signature.parameterSlots.single().type == systemArray
    }) {
        "HostileUnsafeStore.echo(Array<out T>) must retain its truthful projected System.Array carrier: $echo"
    }
    val relay = unsafeStore.members.single { member -> member.sourceName == "relay" }
    check(relay.returnSlotDomain == DotNetGenericOwnerPhysicalSlotDomain.DECLARATION_INDEPENDENT &&
            relay.parameterSlotDomains == listOf(DotNetGenericOwnerPhysicalSlotDomain.DECLARATION_INDEPENDENT) &&
            relay.exactPathUnboundSignatures?.get(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY)
                ?.returnSlot?.type?.arguments?.singleOrNull()?.kind ==
                DotNetGenericOwnerPrototypeTypeKind.METHOD_TYPE_PARAMETER) {
        "HostileUnsafeStore.relay must keep method-owned carriers outside the owner slot domain: $relay"
    }
    val label = unsafeStore.members.single { member -> member.sourceName == "label" }
    check(label.hasMaskedDefaultDispatcher &&
            label.exactMaskedDefaultDispatcher?.parameterSlotsAfterReceiver?.map { slot -> slot.type.kind } ==
            listOf(DotNetGenericOwnerPrototypeTypeKind.STRING, DotNetGenericOwnerPrototypeTypeKind.INT32)) {
        "HostileUnsafeStore.label must retain the lowered compiler-derived default helper tail"
    }

    val hostileCell = prototypes.single { prototype -> prototype.hasSimpleName("HostileCell") }
    val readOr = hostileCell.members.single { member -> member.sourceName == "readOr" }
    check(readOr.hasMaskedDefaultDispatcher) {
        "HostileCell.readOr must retain its selected masked default dispatcher"
    }

    if (unsafeStore.ownerName.contains('.')) {
        check(unsafeStore.logicalBindingKey != null &&
                write.logicalBindingKey != null && read.logicalBindingKey != null) {
            "The separate hostile producer must retain owner/member KLIB binding identities"
        }
    }
}

