/** Validates the real producer resource consumed by the supported C# source-authoring tool. */
private fun validateReifiedGenericInterfaceCSharpManifest(
    producer: File,
    expectedDeclaredOwner: String = "RehearsalSeparateProducer`1",
    expectedMemberName: String = "produce",
    expectedMemberKind: DotNetCSharpMemberKind = DotNetCSharpMemberKind.METHOD,
    expectedNaturalPropertyName: String? = null,
    expectedContractMemberCount: Int = 1,
    expectedVariance: DotNetCSharpTypeParameterVariance = DotNetCSharpTypeParameterVariance.OUT,
    expectedSemanticReturnType: String = "object",
    expectedSemanticParameterTypes: List<String> = emptyList(),
    expectedNaturalReturnType: String = "!0",
    expectedNaturalParameterTypes: List<String> = emptyList(),
    expectedMethodGenericArity: Int = 0,
    expectedDefaultKind: DotNetCSharpDefaultKind = DotNetCSharpDefaultKind.ABSTRACT,
    expectedErasedOwnerRelativeConstraints: List<Pair<Int, Int>> = emptyList(),
) {
    val resource = checkNotNull(
        DotNetManagedResourceReader.read(
            producer,
            DotNetCSharpImplementationManifestCodec.MANAGED_RESOURCE_NAME,
        )
    ) {
        "The reified generic-interface producer has no C# implementation manifest"
    }
    check(resource.isPublic) {
        "The reified generic-interface C# implementation manifest must remain publicly discoverable"
    }
    val manifest = DotNetCSharpImplementationManifestCodec.decodeManagedResource(resource.content)
    val contract = manifest.interfaces.single { candidate ->
        candidate.declaredOwnerPath?.lastOrNull() == expectedDeclaredOwner
    }
    check(contract.sourceAuthoringSupported && contract.unsupportedReasons.isEmpty()) {
        "The admitted reified generic interface is not supported for C# source authoring"
    }
    check(contract.typeParameters.single().variance == expectedVariance) {
        "The reified generic-interface manifest lost Kotlin declaration-site variance"
    }
    check(contract.exactOwnerPath == null &&
            contract.canonicalOwnerPath != contract.declaredOwnerPath) {
        "The reified generic-interface manifest did not separate natural and semantic owners"
    }
    if (expectedDeclaredOwner.endsWith("ChildProducer`1")) {
        val capabilityPrefix = "I${expectedDeclaredOwner.removeSuffix("`1")}KotlinSemantic"
        check(contract.canonicalOwnerPath.last().startsWith(capabilityPrefix)) {
            "The member-declaring child did not publish its own semantic capability"
        }
    }
    val member = contract.members.singleOrNull { candidate ->
        candidate.sourceName == expectedMemberName && candidate.kind == expectedMemberKind
    }
    check(contract.members.size == expectedContractMemberCount && member != null) {
        "The reified generic-interface contract copied, lost, or duplicated declared members"
    }
    check(member.authoringView == DotNetCSharpInterfaceView.DECLARED) {
        "C# authoring must target the natural generic interface"
    }
    check(member.defaultKind == expectedDefaultKind) {
        "The reified generic-interface manifest recorded an unexpected default-body profile"
    }
    check(member.erasedOwnerRelativeConstraints.map { constraint ->
            constraint.methodTypeParameterIndex to constraint.ownerTypeParameterIndex
        } == expectedErasedOwnerRelativeConstraints
    ) {
        "The reified generic-interface manifest lost its erased owner-relative constraint"
    }
    val expectedRoles = linkedSetOf(
        DotNetCSharpSlotRole.ERASED,
        DotNetCSharpSlotRole.DECLARED,
    ).apply {
        if (expectedDefaultKind != DotNetCSharpDefaultKind.ABSTRACT) {
            add(DotNetCSharpSlotRole.HELPER)
        }
    }
    check(member.slots.mapTo(linkedSetOf()) { slot -> slot.role } == expectedRoles) {
        "The reified generic-interface manifest has an incomplete physical member family"
    }
    val semantic = member.slots.single { slot -> slot.role == DotNetCSharpSlotRole.ERASED }
    val natural = member.slots.single { slot -> slot.role == DotNetCSharpSlotRole.DECLARED }
    check(semantic.ownerPath == contract.canonicalOwnerPath &&
            semantic.propertyName == null &&
            semantic.genericArity == expectedMethodGenericArity &&
            semantic.returnType == expectedSemanticReturnType &&
            semantic.parameterTypes == expectedSemanticParameterTypes) {
        "The declaration-semantic interface slot is not the expected object-domain capability"
    }
    check(natural.ownerPath == contract.declaredOwnerPath &&
            natural.propertyName == expectedNaturalPropertyName &&
            natural.genericArity == expectedMethodGenericArity &&
            natural.returnType == expectedNaturalReturnType &&
            natural.parameterTypes == expectedNaturalParameterTypes) {
        "The natural generic-interface slot did not retain its CLR owner parameter"
    }
    member.slots.singleOrNull { slot -> slot.role == DotNetCSharpSlotRole.HELPER }
        ?.let { helper ->
            check(helper.genericArity == contract.typeParameters.size + expectedMethodGenericArity) {
                "The generic-interface default helper lost an owner or method type parameter"
            }
        }
}

/** Returns the Gradle-produced Roslyn tooling without mutating repository state inside a test. */
private fun genericOwnerCSharpAuthoringTooling(): File =
    System.getProperty(DOTNET_CSHARP_AUTHORING_TOOLING_PROPERTY)
        ?.let(::File)
        ?.takeIf(File::isFile)
        ?: error(
            "Missing Kotlin C# authoring tooling from system property " +
                    "'$DOTNET_CSHARP_AUTHORING_TOOLING_PROPERTY'"
        )

/**
 * Proves against the actual Kotlin rehearsal product that the natural typed MethodDef remains
 * the complete C# override obligation. A Kotlin widened call must dispatch through that ordinary
 * C# override rather than bypassing it through the protected compiler semantic hook.
 */
private fun validateGenericOwnerForeignCSharpOverride(
    genericOwnerRehearsal: Boolean,
    producesLibrary: Boolean,
    target: DotNetTarget,
    producer: File,
    testDataFile: File,
    directory: File,
) {
    if (!genericOwnerRehearsal) return
    val testSource = testDataFile.readText()
    val isDirectProbe = GENERIC_OWNER_FOREIGN_OVERRIDE_PROBE_MARKER in testSource
    val isSeparateProbe = GENERIC_OWNER_FOREIGN_OVERRIDE_SEPARATE_PROBE_MARKER in testSource
    if (!isDirectProbe && !isSeparateProbe) return
    check(isDirectProbe xor isSeparateProbe) {
        "A generic-owner foreign override oracle must select exactly one compilation shape"
    }
    check(target != DotNetTarget.NETSTANDARD_2_0) {
        "The generic-owner foreign override probe requires an executable target"
    }
    directory.mkdirs()
    producer.copyTo(directory.resolve(producer.name), overwrite = true)
    if (isSeparateProbe && producesLibrary) {
        when {
            producer.name.equals("lib.dll", ignoreCase = true) -> {
                validateReifiedGenericInterfaceCSharpManifest(producer)
                validateReifiedGenericInterfaceCSharpManifest(
                    producer,
                    expectedDeclaredOwner = "RehearsalSeparateSecondaryProducer`1",
                    expectedMemberName = "produceSecondary",
                )
                validateReifiedGenericInterfaceCSharpManifest(
                    producer,
                    expectedDeclaredOwner = "RehearsalSeparateConsumer`1",
                    expectedMemberName = "consume",
                    expectedVariance = DotNetCSharpTypeParameterVariance.IN,
                    expectedSemanticReturnType = "void",
                    expectedSemanticParameterTypes = listOf("object"),
                    expectedNaturalReturnType = "void",
                    expectedNaturalParameterTypes = listOf("!0"),
                )
                validateReifiedGenericInterfaceCSharpManifest(
                    producer,
                    expectedDeclaredOwner = "RehearsalSeparateDefaultConsumer`1",
                    expectedMemberName = "consumeDefault",
                    expectedVariance = DotNetCSharpTypeParameterVariance.IN,
                    expectedSemanticReturnType = "void",
                    expectedSemanticParameterTypes = listOf("object"),
                    expectedNaturalReturnType = "void",
                    expectedNaturalParameterTypes = listOf("!0"),
                    expectedDefaultKind = when (target) {
                        DotNetTarget.NET48 -> DotNetCSharpDefaultKind.PORTABLE_HELPER
                        DotNetTarget.NET10_0 -> DotNetCSharpDefaultKind.DIM_WITH_HELPER
                        DotNetTarget.NETSTANDARD_2_0 ->
                            error("netstandard2.0 has no executable default-consumer probe")
                    },
                )
                validateReifiedGenericInterfaceCSharpManifest(
                    producer,
                    expectedDeclaredOwner =
                        "RehearsalSeparateDefaultPropertyProducer`1",
                    expectedMemberName = "defaultPropertyValue",
                    expectedMemberKind = DotNetCSharpMemberKind.PROPERTY_GETTER,
                    expectedNaturalPropertyName = "defaultPropertyValue",
                    expectedVariance = DotNetCSharpTypeParameterVariance.OUT,
                    expectedDefaultKind = when (target) {
                        DotNetTarget.NET48 -> DotNetCSharpDefaultKind.PORTABLE_HELPER
                        DotNetTarget.NET10_0 -> DotNetCSharpDefaultKind.DIM_WITH_HELPER
                        DotNetTarget.NETSTANDARD_2_0 ->
                            error("netstandard2.0 has no executable default-property probe")
                    },
                )
                validateReifiedGenericInterfaceCSharpManifest(
                    producer,
                    expectedDeclaredOwner = "RehearsalSeparateReadOnlyPropertyParent`1",
                    expectedMemberName = "parentReadOnlyProperty",
                    expectedMemberKind = DotNetCSharpMemberKind.PROPERTY_GETTER,
                    expectedNaturalPropertyName = "parentReadOnlyProperty",
                    expectedVariance = DotNetCSharpTypeParameterVariance.OUT,
                )
                validateReifiedGenericInterfaceCSharpManifest(
                    producer,
                    expectedDeclaredOwner =
                        "RehearsalSeparateDefaultMethodGenericProducer`1",
                    expectedMemberName = "produceDefaultGeneric",
                    expectedVariance = DotNetCSharpTypeParameterVariance.OUT,
                    expectedSemanticReturnType = "object",
                    expectedSemanticParameterTypes = listOf("!!0"),
                    expectedNaturalReturnType = "!0",
                    expectedNaturalParameterTypes = listOf("!!0"),
                    expectedMethodGenericArity = 1,
                    expectedDefaultKind = when (target) {
                        DotNetTarget.NET48 -> DotNetCSharpDefaultKind.PORTABLE_HELPER
                        DotNetTarget.NET10_0 -> DotNetCSharpDefaultKind.DIM_WITH_HELPER
                        DotNetTarget.NETSTANDARD_2_0 ->
                            error("netstandard2.0 has no executable method-generic default probe")
                    },
                )
                validateReifiedGenericInterfaceCSharpManifest(
                    producer,
                    expectedDeclaredOwner =
                        "RehearsalSeparateConstrainedDefaultMethodGenericProducer`1",
                    expectedMemberName = "produceConstrainedDefaultGeneric",
                    expectedVariance = DotNetCSharpTypeParameterVariance.OUT,
                    expectedSemanticReturnType = "object",
                    expectedSemanticParameterTypes = listOf("!!0"),
                    expectedNaturalReturnType = "!0",
                    expectedNaturalParameterTypes = listOf("!!0"),
                    expectedMethodGenericArity = 1,
                    expectedDefaultKind = when (target) {
                        DotNetTarget.NET48 -> DotNetCSharpDefaultKind.PORTABLE_HELPER
                        DotNetTarget.NET10_0 -> DotNetCSharpDefaultKind.DIM_WITH_HELPER
