                    RehearsalSeparateProducer<int>,
                    RehearsalSeparateProducer<string>
                {
                    int RehearsalSeparateProducer<int>.produce()
                    {
                        return 89;
                    }

                    string RehearsalSeparateProducer<string>.produce()
                    {
                        return "ambiguous";
                    }
                }
                """.trimIndent()
            )
        }
        directory.resolve("RehearsalPrecompiledForeignProducer.dll").also { output ->
            val rawCompilation = when (target) {
                DotNetTarget.NET48 -> compileFrameworkSnapshotCSharp(
                    checkNotNull(DotNetIlAssembler.findFrameworkCSharpCompiler()) {
                        ".NET Framework C# compiler is required for the precompiled foreign producer probe"
                    },
                    rawSource,
                    output,
                    references = producerReferences + listOf(runtime, stdlib),
                    executable = false,
                    warningsAsErrors = true,
                )
                DotNetTarget.NET10_0 -> compileModernSnapshotCSharp(
                    modernCSharp,
                    rawSource,
                    output,
                    references = producerReferences + listOf(runtime, stdlib),
                    executable = false,
                    warningsAsErrors = true,
                )
                DotNetTarget.NETSTANDARD_2_0 ->
                    error("netstandard2.0 has no executable foreign producer probe")
            }
            check(rawCompilation.exitCode == 0) {
                "The ordinary precompiled C# producer must not require Kotlin authoring tooling:\n" +
                        rawCompilation.output
            }
        }
    } else {
        null
    }
    val authoringTooling = genericOwnerCSharpAuthoringTooling()
    val generatedDirectory = directory.resolve("generated-${target.description}")
    val compilation = when (target) {
        DotNetTarget.NET48 -> compileFrameworkSnapshotCSharp(
            checkNotNull(DotNetIlAssembler.findFrameworkCSharpCompiler()) {
                ".NET Framework C# compiler is required for the generic-owner foreign override probe"
            },
            source,
            consumer,
            references = producerReferences + listOfNotNull(rawProducer) + listOf(runtime, stdlib),
            executable = true,
            warningsAsErrors = true,
            analyzers = listOf(authoringTooling),
            generatedFilesDirectory = generatedDirectory,
        )
        DotNetTarget.NET10_0 -> compileModernSnapshotCSharp(
            modernCSharp,
            source,
            consumer,
            references = producerReferences + listOfNotNull(rawProducer) + listOf(runtime, stdlib),
            executable = true,
            warningsAsErrors = true,
            analyzers = listOf(authoringTooling),
            generatedFilesDirectory = generatedDirectory,
        )
        DotNetTarget.NETSTANDARD_2_0 -> error("netstandard2.0 has no executable override probe")
    }
    check(compilation.exitCode == 0) { compilation.output }
    if (isSeparateProbe) {
        val generated = generatedDirectory.walkTopDown()
            .filter { file ->
                file.isFile && file.name.endsWith(".KotlinInterfaceImplementation.g.cs")
            }
            .joinToString("\n", transform = File::readText)
        check("RehearsalSeparateProducer" in generated) {
            "The C# authoring tool did not generate the real Kotlin interface bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpChildProducer" in generated) {
            "The C# authoring tool did not generate the foreign subinterface implementation bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpReadOnlyPropertyChild" in generated) {
            "The C# authoring tool did not generate the read-only property-child bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpLocalIntersectionProducer" in generated) {
            "The C# authoring tool did not generate the local interface-intersection bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpDefaultConsumer" in generated) {
            "The C# authoring tool did not generate the default-consumer bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpDefaultOverrideConsumer" in generated) {
            "The C# authoring tool did not generate the default-override consumer bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpDefaultPropertyProducer" in generated) {
            "The C# authoring tool did not generate the default-property bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpDefaultPropertyOverrideProducer" in generated) {
            "The C# authoring tool did not generate the default-property override bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpDefaultMethodGenericProducer" in generated) {
            "The C# authoring tool did not generate the method-generic default bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpDefaultMethodGenericOverrideProducer" in generated) {
            "The C# authoring tool did not generate the method-generic default override bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpConstrainedDefaultMethodGenericProducer" in generated) {
            "The C# authoring tool did not generate the constrained default bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpConstrainedDefaultMethodGenericOverrideProducer" in generated) {
            "The C# authoring tool did not generate the constrained default override bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpMultiConstrainedDefaultProducer" in generated) {
            "The C# authoring tool did not generate the multi-constrained default bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpMultiConstrainedDefaultOverrideProducer" in generated) {
            "The C# authoring tool did not generate the multi-constrained default override bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpNominalConstrainedDefaultProducer" in generated) {
            "The C# authoring tool did not generate the nominal-constrained default bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpNominalConstrainedDefaultOverrideProducer" in generated) {
            "The C# authoring tool did not generate the nominal-constrained override bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpAbstractMethodGenericProducer" in generated) {
            "The C# authoring tool did not generate the abstract method-generic bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpConstrainedMethodGenericProducer" in generated) {
            "The C# authoring tool did not generate the constrained method-generic bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpOwnerRelativeMethodGenericProducer" in generated) {
            "The C# authoring tool did not generate the owner-relative method-generic bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpOwnerRelativeDefaultMethodGenericProducer" in generated) {
            "The C# authoring tool did not generate the owner-relative default bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpOwnerRelativeDefaultMethodGenericOverrideProducer" in generated) {
            "The C# authoring tool did not generate the owner-relative default override bridge:\n$generated"
        }
        check("partial class RehearsalSeparateCSharpMethodConstraintValue" in generated) {
            "The C# authoring tool did not generate the method-constraint value bridge:\n$generated"
        }
        check("RehearsalSeparateCSharpDerivedDefaultConsumer" !in generated) {
            "The ordinary C# subclass unexpectedly required a generated semantic bridge:\n$generated"
        }
        check("KotlinSemantic" !in source.readText()) {
            "Authored C# source must not name the Kotlin semantic capability"
        }
    }
    val stagedDependencies = if (isSeparateProbe) {
        producerReferences.map { dependency -> dependency to dependency.name }
    } else {
        listOf(producer to "${testDataFile.nameWithoutExtension}.dll")
    }
    (stagedDependencies + listOf(runtime to runtime.name, stdlib to stdlib.name)).forEach { dependencyEntry ->
        val dependency = dependencyEntry.first
        val assemblyFileName = dependencyEntry.second
        val staged = directory.resolve(assemblyFileName)
        if (dependency.canonicalFile != staged.canonicalFile) dependency.copyTo(staged, overwrite = true)
    }
    executeSnapshotConsumer(target, consumer, directory)
}

private fun genericOwnerCallRouteTraceKey(directory: File): String =
    directory.absoluteFile.normalize().path

private fun prepareGenericOwnerCallRouteTraceExport(
    exportDirectory: File,
    encodedCallRouteManifest: String,
) {
    check(!exportDirectory.exists() || exportDirectory.isDirectory) {
        "Generic-owner call-route trace export path is not a directory: $exportDirectory"
    }
    check(exportDirectory.mkdirs() || exportDirectory.isDirectory) {
        "Cannot create generic-owner call-route trace export directory: $exportDirectory"
    }
    check(exportDirectory.list()?.isEmpty() == true) {
        "Generic-owner call-route trace export directory must be empty: $exportDirectory"
    }
    exportDirectory.resolve(GENERIC_OWNER_CALL_ROUTE_MANIFEST_FILE).writeText(encodedCallRouteManifest)
    check(genericOwnerCallRouteTraceManifests.put(
        genericOwnerCallRouteTraceKey(exportDirectory),
        encodedCallRouteManifest,
    ) == null) {
        "The generic-owner call-route trace export directory was registered more than once"
    }
}

private fun genericOwnerErasedConsumerFile(target: DotNetTarget): String =
    if (target == DotNetTarget.NET48) "ErasedConsumer.exe" else "ErasedConsumer.dll"

private fun genericOwnerErasedCSharpAssemblyFile(target: DotNetTarget): String =
    if (target == DotNetTarget.NET48) "ErasedCSharpConsumer.exe" else "ErasedCSharpConsumer.dll"

private fun genericOwnerPrototypePhysicalMethodName(
    member: DotNetGenericOwnerPrototypeMemberSnapshot,
    role: DotNetGenericOwnerMemberFamilyRole,
    overrideRootLogicalMemberKeys: List<String>,
): String = dotNetGenericOwnerPhysicalMemberName(
    member.physicalBaseName,
    overrideRootLogicalMemberKeys,
    role,
)

private fun genericOwnerPhysicalReflectionCallables(
    members: List<DotNetGenericOwnerPhysicalMemberFamilyRecord>,
): List<DotNetGenericOwnerPhysicalCallableReflectionRecord> = members.map { member ->
    val invocationRole = if (DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK in member.roles) {
        DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER
    } else {
        DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY
    }
    val invocationSlot = member.slots.single { slot -> slot.role == invocationRole }
    DotNetGenericOwnerPhysicalCallableReflectionRecord(
        logicalMemberKey = member.logicalMemberKey,
        exposure = DotNetGenericOwnerReflectionCallableExposure.SINGLE_LOGICAL_DECLARATION,
        invocationRole = invocationRole,
        invocationMethod = DotNetGenericOwnerPhysicalMethodIdentityRecord(
            invocationSlot.physicalOwnerPath,
            invocationSlot.physicalMethodName,
            invocationSlot.signature,
        ),
        physicalMethods = buildList {
            member.slots.forEach { slot ->
                add(DotNetGenericOwnerPhysicalMethodIdentityRecord(
                    slot.physicalOwnerPath,
                    slot.physicalMethodName,
                    slot.signature,
                ))
                slot.capabilitySlot?.let(::add)
            }
            member.defaultDispatcher?.let { dispatcher ->
                add(DotNetGenericOwnerPhysicalMethodIdentityRecord(
                    dispatcher.physicalOwnerPath,
                    dispatcher.physicalMethodName,
                    dispatcher.signature,
                ))
            }
        },
    )
}

private fun genericOwnerPhysicalProperties(
    prototype: DotNetGenericOwnerPrototypeSnapshot,
    members: List<DotNetGenericOwnerPhysicalMemberFamilyRecord>,
    scenario: String,
): List<DotNetGenericOwnerPhysicalPropertyRecord> = prototype.members.asSequence()
    .filter { member ->
        member.logicalBindingKey != null && member.propertyAccessorKind != null &&
                !member.isFakeOverride &&
                member.physicalVisibility != DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE
    }
    .groupBy { member -> checkNotNull(member.physicalPropertyName) }
    .map { entry ->
        val physicalPropertyName = entry.key
        val accessors = entry.value
        check(accessors.map { accessor -> accessor.propertyAccessorKind }.toSet().size == accessors.size) {
            "$scenario physical property '$physicalPropertyName' has duplicate accessor kinds"
        }
        val getter = accessors.singleOrNull { accessor ->
            accessor.propertyAccessorKind == DotNetGenericOwnerPropertyAccessorKind.GETTER
        }
        val setter = accessors.singleOrNull { accessor ->
            accessor.propertyAccessorKind == DotNetGenericOwnerPropertyAccessorKind.SETTER
        }
        fun typedMethod(
            accessor: DotNetGenericOwnerPrototypeMemberSnapshot?,
        ): Pair<String, DotNetGenericOwnerPhysicalMethodIdentityRecord>? {
            accessor ?: return null
            val logicalKey = checkNotNull(accessor.logicalBindingKey)
            val slot = members.single { member -> member.logicalMemberKey == logicalKey }
                .slots.single { slot -> slot.role == DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY }
            return logicalKey to DotNetGenericOwnerPhysicalMethodIdentityRecord(
                physicalOwnerPath = slot.physicalOwnerPath,
                physicalMethodName = slot.physicalMethodName,
                signature = slot.signature,
            )
        }
        val getterBinding = typedMethod(getter)
        val setterBinding = typedMethod(setter)
        val propertyType = getterBinding?.second?.signature?.let { signature ->
            check(signature.parameterSlots.isEmpty()) {
                "$scenario PropertyDef proof only admits ordinary non-indexed getters"
            }
            signature.returnSlot.type
        } ?: setterBinding?.second?.signature?.let { signature ->
            check(signature.parameterSlots.size == 1) {
                "$scenario PropertyDef proof only admits ordinary non-indexed setters"
            }
            signature.parameterSlots.single().type
        } ?: error("$scenario physical property '$physicalPropertyName' has no accessor")
        val propertyNullableReferenceFlags = getterBinding?.second?.signature?.returnSlot
            ?.nullableReferenceFlags
            ?: setterBinding?.second?.signature?.parameterSlots?.single()?.nullableReferenceFlags
            ?: error("$scenario physical property '$physicalPropertyName' has no nullable contract")
        check(setterBinding == null || setterBinding.second.signature.parameterSlots.singleOrNull()?.type ==
                propertyType && setterBinding.second.signature.parameterSlots.single().nullableReferenceFlags ==
                propertyNullableReferenceFlags) {
            "$scenario physical property '$physicalPropertyName' has mismatched accessor types"
        }
        DotNetGenericOwnerPhysicalPropertyRecord(
            physicalPropertyName = physicalPropertyName,
            physicalType = propertyType,
            nullableReferenceFlags = propertyNullableReferenceFlags,
            getterLogicalMemberKey = getterBinding?.first,
            getterPhysicalMethod = getterBinding?.second,
            setterLogicalMemberKey = setterBinding?.first,
            setterPhysicalMethod = setterBinding?.second,
            getterRoute = if (getter?.roles?.contains(
                DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK,
            ) == true) {
                DotNetGenericOwnerPhysicalPropertyGetterRoute.SEMANTIC_HOOK
            } else {
                DotNetGenericOwnerPhysicalPropertyGetterRoute.TYPED_ENTRY
            },
            setterRoute = when {
                setter == null -> DotNetGenericOwnerPhysicalPropertySetterRoute.ABSENT
                DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK in setter.roles ->
                    DotNetGenericOwnerPhysicalPropertySetterRoute.COMPATIBLE_TYPED_ELSE_SEMANTIC_HOOK
                else -> DotNetGenericOwnerPhysicalPropertySetterRoute.TYPED_ENTRY
            },
        )
    }
    .sortedBy { property -> property.physicalPropertyName }

private fun createGenericOwnerPhysicalFamilyArtifact(
    prototypes: List<DotNetGenericOwnerPrototypeSnapshot>,
    producerFingerprint: String,
    target: DotNetTarget,
): DotNetGenericOwnerPhysicalFamilyArtifact {
    fun DotNetGenericOwnerPrototypeSnapshot.hasSimpleName(name: String): Boolean =
        ownerName == name || ownerName.endsWith(".$name")

    val membersByLogicalKey = prototypes.flatMap { prototype -> prototype.members }
        .mapNotNull { member -> member.logicalBindingKey?.let { key -> key to member } }
        .toMap()
    val constructorsByLogicalKey = prototypes.flatMap { prototype ->
        prototype.constructors.mapNotNull { constructor ->
            constructor.logicalBindingKey?.let { key -> key to (prototype to constructor) }
        }
    }.toMap()
    val classifications = prototypes.mapNotNull { prototype ->
        val logicalOwnerKey = prototype.logicalBindingKey ?: return@mapNotNull null
        DotNetGenericOwnerCandidateClassificationRecord(
            logicalOwnerKey = logicalOwnerKey,
            genericArity = prototype.genericArity,
            disposition = prototype.disposition,
            logicalConstructorKeys = prototype.constructors.mapNotNull { constructor ->
                constructor.logicalBindingKey
            }.distinct().sorted(),
            logicalMemberKeys = prototype.members.mapNotNull { member ->
                member.logicalBindingKey
            }.distinct().sorted(),
            conditionalSupertypes = prototype.directSupertypes.mapNotNull { supertype ->
                if (supertype.disposition !=
                        DotNetGenericOwnerPrototypeSupertypeDisposition.CONDITIONAL_OPEN_NULLABLE_ARGUMENT
                ) return@mapNotNull null
                DotNetGenericOwnerConditionalSupertypeRecord(
                    kind = supertype.kind,
                    logicalClassifierKey = checkNotNull(supertype.logicalClassifierKey) {
                        "The separate hostile producer requires a logical conditional-supertype binding"
                    },
                    conditionalOwnerParameterIndices = supertype.conditionalOwnerParameterIndices,
                )
            }.distinct().sortedWith(compareBy(
                { supertype -> supertype.kind.name },
                { supertype -> supertype.logicalClassifierKey },
            )),
        )
    }.sortedBy { classification -> classification.logicalOwnerKey }
    fun overrideRoots(
        member: DotNetGenericOwnerPrototypeMemberSnapshot,
        visiting: Set<String> = emptySet(),
    ): Set<String> {
        val logicalKey = checkNotNull(member.logicalBindingKey)
        check(logicalKey !in visiting) { "Generic-owner override-family roots contain a cycle at '$logicalKey'" }
        val overriddenKeys = member.overrideBindings.mapNotNull { binding -> binding.overriddenLogicalBindingKey }
        if (overriddenKeys.isEmpty()) return setOf(logicalKey)
        return overriddenKeys.flatMapTo(linkedSetOf()) { overriddenKey ->
            membersByLogicalKey[overriddenKey]
                ?.let { overridden -> overrideRoots(overridden, visiting + logicalKey) }
                ?: setOf(overriddenKey)
        }
    }

    val selectedPrototypes = listOf(
        "HostileUnsafeStore",
        "HostileUnsafeMid",
        "HostileTypedStore",
        "HostileAbstractProperty",
        "HostileAbstractPropertyStorage",
        "HostileNullableReferenceBase",
        "HostileNullableReferenceDerived",
    ).map { simpleName ->
        prototypes.single { candidate -> candidate.hasSimpleName(simpleName) }
    }
    val nullableReferenceDerived = selectedPrototypes.single { prototype ->
        prototype.hasSimpleName("HostileNullableReferenceDerived")
    }
    val markerLogicalKey = checkNotNull(nullableReferenceDerived.directSupertypes.single { supertype ->
        supertype.kind == DotNetGenericOwnerDirectSupertypeKind.INTERFACE &&
                supertype.disposition == DotNetGenericOwnerPrototypeSupertypeDisposition.EXACT_PHYSICAL_EDGE
    }.logicalClassifierKey) {
        "The separate hostile producer requires the nullable marker interface binding"
    }
    val markerPhysicalPath = listOf("KotlinSnapshotPrototype", "HostileNullableMarker")
    val physicalOwnerPathsByLogicalKey = selectedPrototypes.associate { prototype ->
        checkNotNull(prototype.logicalBindingKey) to
                listOf("KotlinSnapshotPrototype", prototype.ownerName.substringAfterLast('.'))
    } + (markerLogicalKey to markerPhysicalPath)
    val physicalNamedTypeCategoriesByLogicalKey = physicalOwnerPathsByLogicalKey.keys.associateWith { logicalKey ->
        if (logicalKey == markerLogicalKey) {
            DotNetGenericOwnerPhysicalNamedTypeCategory.INTERFACE
        } else {
            DotNetGenericOwnerPhysicalNamedTypeCategory.CLASS
        }
    }
    val interfaceTypes = listOf(
        DotNetGenericOwnerPhysicalInterfaceTypeRecord(
            logicalInterfaceKey = markerLogicalKey,
            physicalTypePath = markerPhysicalPath,
            physicalVisibility = DotNetGenericOwnerPhysicalTypeVisibility.PUBLIC,
            genericArity = 1,
            physicalGenericParameters = listOf(
                DotNetGenericOwnerPhysicalGenericParameterRecord(0, emptySet(), emptyList())
            ),
        )
    )
    val owners = selectedPrototypes.map { prototype ->
        val simpleName = prototype.ownerName.substringAfterLast('.')
        val ownerPath = listOf("KotlinSnapshotPrototype", simpleName)
        val baseOwnerPath = listOf("KotlinSnapshotPrototype", when (simpleName) {
            "HostileUnsafeMid" -> "HostileUnsafeStore"
            "HostileAbstractPropertyStorage" -> "HostileAbstractProperty"
            else -> simpleName
        })
        val hasCapabilityFamily = prototype.members.any { member ->
            member.logicalBindingKey != null &&
                    DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER in member.roles
        }
        val capabilityOwnerPath = if (hasCapabilityFamily) {
            listOf(
                "KotlinSnapshotPrototype",
                when (simpleName) {
                    "HostileTypedStore" -> "IHostileTypedStoreSemantic"
                    "HostileAbstractProperty", "HostileAbstractPropertyStorage" ->
                        "IHostileAbstractPropertySemantic"
                    else -> "IHostileUnsafeStoreSemantic"
                },
            )
        } else {
            null
        }
        val exactDirectSupertypes = prototype.directSupertypes.mapNotNull { supertype ->
            if (supertype.disposition != DotNetGenericOwnerPrototypeSupertypeDisposition.EXACT_PHYSICAL_EDGE) {
                return@mapNotNull null
            }
            val prototypeType = checkNotNull(supertype.exactPhysicalType)
            val physicalType = if (prototypeType.kind == DotNetGenericOwnerPrototypeTypeKind.OBJECT) {
                DotNetGenericOwnerPhysicalTypeExpressionRecord.coreType(
                    typePath = listOf("System", "Object"),
                    category = DotNetGenericOwnerPhysicalNamedTypeCategory.CLASS,
                )
            } else {
                prototypeType.bindProducerTypes(
                    physicalOwnerPathsByLogicalKey,
                    physicalNamedTypeCategoriesByLogicalKey,
                )
            }
            DotNetGenericOwnerPhysicalDirectSupertypeRecord(
                kind = supertype.kind,
                logicalClassifierKey = supertype.logicalClassifierKey,
                isSemanticCapability = false,
                physicalType = physicalType,
                nullableReferenceFlags = checkNotNull(supertype.nullableReferenceFlags).toMutableList().apply {
                    this[0] = DotNetNullableReferenceFlag.OBLIVIOUS
                },
            )
        }
        val ownsCapabilityDispatchers = hasCapabilityFamily && baseOwnerPath == ownerPath
        val directSupertypes = exactDirectSupertypes + if (ownsCapabilityDispatchers) {
            listOf(
                DotNetGenericOwnerPhysicalDirectSupertypeRecord(
                    kind = DotNetGenericOwnerDirectSupertypeKind.INTERFACE,
                    logicalClassifierKey = null,
                    isSemanticCapability = true,
                    physicalType = DotNetGenericOwnerPhysicalTypeExpressionRecord.producerType(
                        typePath = checkNotNull(capabilityOwnerPath),
                        category = DotNetGenericOwnerPhysicalNamedTypeCategory.INTERFACE,
                    ),
                    nullableReferenceFlags = listOf(DotNetNullableReferenceFlag.OBLIVIOUS),
                )
            )
        } else {
            emptyList()
        }
        val physicalBaseType = directSupertypes.single { supertype ->
            supertype.kind == DotNetGenericOwnerDirectSupertypeKind.BASE_CLASS
        }.physicalType
        val constructors = prototype.constructors.map { constructor ->
            val logicalConstructorKey = checkNotNull(constructor.logicalBindingKey) {
                "The hostile physical family requires a logical constructor binding"
            }
            val signature = checkNotNull(constructor.exactPathUnboundSignature) {
                "The hostile physical family requires a compiler-derived constructor signature"
            }.bindProducerTypes(physicalOwnerPathsByLogicalKey)
            checkNotNull(constructor.delegatedOwnerName) {
                "The hostile physical family requires an exact delegated constructor owner"
            }
            val delegated = constructor.delegatedConstructorLogicalBindingKey?.let(constructorsByLogicalKey::get)
            val delegatedSignature = delegated?.let { pair ->
                checkNotNull(pair.second.exactPathUnboundSignature) {
                    "The hostile physical family requires a compiler-derived delegated constructor signature"
                }.bindProducerTypes(physicalOwnerPathsByLogicalKey)
            } ?: DotNetGenericOwnerPhysicalMethodSignatureRecord(
                isInstance = true,
                genericArity = 0,
                returnSlot = DotNetGenericOwnerPhysicalValueSlotRecord(
                    DotNetGenericOwnerPhysicalSlotDomain.DECLARATION_INDEPENDENT,
                    DotNetGenericOwnerPhysicalTypeExpressionRecord.voidType(),
                ),
                parameterSlots = emptyList(),
            )
            val delegatedOwnerType = if (constructor.delegatesToThis) {
                DotNetGenericOwnerPhysicalTypeExpressionRecord.producerType(
                    typePath = ownerPath,
                    category = DotNetGenericOwnerPhysicalNamedTypeCategory.CLASS,
                    arguments = List(prototype.genericArity) { index ->
                        DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(index)
                    },
                )
            } else {
                physicalBaseType
            }
            DotNetGenericOwnerPhysicalConstructorRecord(
                logicalConstructorKey = logicalConstructorKey,
                constructionMode = DotNetGenericOwnerConstructionMode.STATIC_EXACT,
                visibility = DotNetGenericOwnerPhysicalConstructorVisibility.PUBLIC,
                constructedOwnerType = DotNetGenericOwnerPhysicalTypeExpressionRecord.producerType(
                    typePath = ownerPath,
                    category = DotNetGenericOwnerPhysicalNamedTypeCategory.CLASS,
                    arguments = List(prototype.genericArity) { index ->
                        DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(index)
                    },
                ),
                physicalConstructor = DotNetGenericOwnerPhysicalMethodIdentityRecord(
                    physicalOwnerPath = ownerPath,
                    physicalMethodName = ".ctor",
                    signature = signature,
                ),
                delegation = DotNetGenericOwnerPhysicalDelegatingConstructorRecord(
                    kind = if (constructor.delegatesToThis) {
                        DotNetGenericOwnerConstructorDelegationKind.THIS
                    } else {
                        DotNetGenericOwnerConstructorDelegationKind.BASE
                    },
                    logicalConstructorKey = constructor.delegatedConstructorLogicalBindingKey,
                    physicalOwnerType = delegatedOwnerType,
                    physicalMethodName = ".ctor",
                    signature = delegatedSignature,
                ),
            )
        }
        check(constructors.map { constructor -> constructor.logicalConstructorKey }.toSet() ==
                prototype.constructors.mapNotNull { constructor -> constructor.logicalBindingKey }.toSet()) {
            "The hostile producer physical-family record omitted a bindable logical constructor"
        }
        val members = prototype.members.mapNotNull { member ->
            val logicalMemberKey = member.logicalBindingKey ?: return@mapNotNull null
            val memberOverrideRoots = overrideRoots(member).sorted()
            DotNetGenericOwnerPhysicalMemberFamilyRecord(
                logicalMemberKey = logicalMemberKey,
                overrideRootLogicalMemberKeys = memberOverrideRoots,
                policy = member.policy,
                roles = member.roles,
                semanticHookReasons = member.semanticHookReasons,
                slots = member.roles.map { role ->
                    val methodName = genericOwnerPrototypePhysicalMethodName(member, role, memberOverrideRoots)
                    val signature = checkNotNull(member.exactPathUnboundSignatures?.get(role)) {
                        "The hostile physical family requires a compiler-derived signature for ${member.sourceName}/$role"
                    }.bindProducerTypes(physicalOwnerPathsByLogicalKey)
                    val isCapability = role == DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER
                    DotNetGenericOwnerPhysicalMemberSlotRecord(
                        role = role,
                        visibility = when (role) {
                            DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY -> member.physicalVisibility
                            DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK ->
                                DotNetGenericOwnerPhysicalMemberVisibility.FAMILY
                            DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER ->
                                DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE
                        },
                        physicalOwnerPath = if (isCapability) baseOwnerPath else ownerPath,
                        physicalMethodName = if (isCapability) {
                            "${checkNotNull(capabilityOwnerPath).joinToString(".")}.$methodName"
                        } else {
                            methodName
                        },
                        dispatch = when {
                            isCapability ->
                                DotNetGenericOwnerPhysicalMemberDispatch.FINAL
                            member.isAbstract -> DotNetGenericOwnerPhysicalMemberDispatch.ABSTRACT
                            member.isOverridable -> DotNetGenericOwnerPhysicalMemberDispatch.OVERRIDABLE
                            else -> DotNetGenericOwnerPhysicalMemberDispatch.FINAL
                        },
                        signature = signature,
                        capabilitySlot = if (isCapability) {
                            DotNetGenericOwnerPhysicalMethodIdentityRecord(
                                physicalOwnerPath = checkNotNull(capabilityOwnerPath),
                                physicalMethodName = methodName,
                                signature = signature,
                            )
                        } else {
                            null
                        },
                    )
                },
                directSuperTargets = member.directSuperCalls.flatMap { call ->
                    val logicalTargetKey = checkNotNull(call.logicalMemberKey) {
                        "The separate hostile producer requires logical direct-super targets"
                    }
                    member.roles.filter { role ->
                        role != DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER
                    }.map { role ->
                        val targetMember = checkNotNull(membersByLogicalKey[logicalTargetKey]) {
                            "The separate hostile producer requires a recorded direct-super member"
                        }
                        DotNetGenericOwnerPhysicalDirectSuperTargetRecord(
                            role = role,
                            logicalTargetMemberKey = logicalTargetKey,
                            physicalOwnerPath = listOf(
                                "KotlinSnapshotPrototype",
                                call.superQualifierName.substringAfterLast('.'),
                            ),
                            physicalMethodName = genericOwnerPrototypePhysicalMethodName(
                                targetMember,
                                role,
                                overrideRoots(targetMember).sorted(),
                            ),
                            signature = checkNotNull(member.exactPathUnboundSignatures?.get(role)) {
                                "The hostile physical family requires a compiler-derived direct-super signature"
                            }.bindProducerTypes(physicalOwnerPathsByLogicalKey),
                        )
                    }
                },
                defaultDispatcher = if (member.hasMaskedDefaultDispatcher) {
                    val dispatcher = checkNotNull(member.exactMaskedDefaultDispatcher) {
                        "The hostile physical family requires a compiler-derived default helper signature"
                    }
                    DotNetGenericOwnerPhysicalDefaultDispatcherRecord(
                        physicalOwnerPath = listOf("KotlinSnapshotPrototype", simpleName),
                        physicalMethodName = dotNetGenericOwnerPhysicalDefaultDispatcherName(
                            genericOwnerPrototypePhysicalMethodName(
                                member,
                                DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
                                memberOverrideRoots,
                            ),
                            logicalMemberKey,
                        ),
                        signature = dispatcher.physicalSignature(
                            ownerPath,
                            prototype.genericArity,
                            physicalOwnerPathsByLogicalKey,
                        ),
                    )
                } else {
                    null
                },
            )
        }
        check(members.map { member -> member.logicalMemberKey }.toSet() ==
                prototype.members.mapNotNull { member -> member.logicalBindingKey }.toSet()) {
            "The hostile producer physical-family record omitted a bindable logical member"
        }
        val properties = genericOwnerPhysicalProperties(prototype, members, "The hostile owner")
        DotNetGenericOwnerPhysicalFamilyRecord(
            logicalOwnerKey = checkNotNull(prototype.logicalBindingKey) {
                "The separate hostile producer requires a logical owner binding"
            },
            physicalOwnerPath = ownerPath,
            physicalCapabilityOwnerPath = capabilityOwnerPath,
            physicalVisibility = prototype.physicalVisibility,
            physicalDispatch = prototype.physicalDispatch,
            genericArity = prototype.genericArity,
            physicalGenericParameters = checkNotNull(prototype.physicalGenericParameters) {
                "The hostile physical family requires exact GenericParam constraints"
            },
            directSupertypes = directSupertypes,
            disposition = prototype.disposition,
            runtimeClassificationMode = DotNetGenericOwnerRuntimeClassificationMode.OPEN_TYPEDEF_ANCESTRY,
            constructionModes = setOf(DotNetGenericOwnerConstructionMode.STATIC_EXACT),
            constructors = constructors,
            reflection = DotNetGenericOwnerPhysicalReflectionRecord(
                logicalClassifierKey = checkNotNull(prototype.logicalBindingKey),
                physicalOpenTypeDefinition = DotNetGenericOwnerPhysicalOpenTypeDefinitionRecord(
                    physicalTypePath = ownerPath,
                    genericArity = prototype.genericArity,
                ),
                classifierNormalizationMode =
                    DotNetGenericOwnerReflectionClassifierNormalizationMode.EXACT_OPEN_TYPEDEF,
                instanceClassificationMode = DotNetGenericOwnerRuntimeClassificationMode.OPEN_TYPEDEF_ANCESTRY,
                typeArgumentAuthority = DotNetGenericOwnerReflectionTypeArgumentAuthority.KLIB_LOGICAL_GRAPH,
                capabilityExposure = DotNetGenericOwnerReflectionCapabilityExposure.HIDDEN_COMPILER_ABI,
                callables = genericOwnerPhysicalReflectionCallables(members),
            ),
            members = members,
            properties = properties,
            states = prototype.states.map { state ->
                fun access(
                    source: DotNetGenericOwnerPrototypeMemberSnapshot,
                    domain: DotNetGenericOwnerPhysicalStateAccessDomain,
                    operation: DotNetGenericOwnerPhysicalStateAccessOperation,
                    conversion: DotNetGenericOwnerPhysicalStateAccessConversion,
                ): DotNetGenericOwnerPhysicalStateAccessRecord {
                    val logicalMemberKey = checkNotNull(source.logicalBindingKey)
                    val role = when (domain) {
                        DotNetGenericOwnerPhysicalStateAccessDomain.TYPED ->
                            DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY
                        DotNetGenericOwnerPhysicalStateAccessDomain.SEMANTIC ->
                            DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK
                    }
                    val slot = members.single { member -> member.logicalMemberKey == logicalMemberKey }
                        .slots.single { candidate -> candidate.role == role }
                    return DotNetGenericOwnerPhysicalStateAccessRecord(
                        domain = domain,
                        operation = operation,
                        conversion = conversion,
                        bindingKind = DotNetGenericOwnerPhysicalStateAccessBindingKind.LOGICAL_MEMBER_FAMILY,
                        logicalMemberKey = logicalMemberKey,
                        role = role,
                        physicalVisibility = null,
                        physicalMethod = DotNetGenericOwnerPhysicalMethodIdentityRecord(
                            physicalOwnerPath = slot.physicalOwnerPath,
                            physicalMethodName = slot.physicalMethodName,
                            signature = slot.signature,
                        ),
                    )
                }
                fun stateFamily(
                    operation: DotNetGenericOwnerPhysicalStateAccessOperation,
                ): DotNetGenericOwnerPrototypeMemberSnapshot {
                    val candidates = prototype.members.filter { member ->
                        val reachesState = when (operation) {
                            DotNetGenericOwnerPhysicalStateAccessOperation.READ ->
                                state.fieldName in member.transitiveStateReadNames
                            DotNetGenericOwnerPhysicalStateAccessOperation.WRITE ->
                                state.fieldName in member.transitiveStateWriteNames
                        }
                        reachesState &&
                                member.logicalBindingKey != null &&
                                members.any { family -> family.logicalMemberKey == member.logicalBindingKey } &&
                                when (state.requirement) {
                                    DotNetGenericOwnerStateCarrierRequirement.DECLARATION_INDEPENDENT_STORAGE -> false
                                    DotNetGenericOwnerStateCarrierRequirement.SEMANTIC_OBJECT_REQUIRED ->
                                        DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK in member.roles
                                    DotNetGenericOwnerStateCarrierRequirement.VOLATILE_OBJECT_STORAGE_REQUIRED,
                                    DotNetGenericOwnerStateCarrierRequirement.TYPED_STORAGE_PRODUCER_GRAPH_PROVEN,
                                    -> DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY in member.roles
                                    DotNetGenericOwnerStateCarrierRequirement.COMPLETE_ACCESS_GRAPH_REQUIRED,
                                    DotNetGenericOwnerStateCarrierRequirement.TYPED_WRITE_VALUE_PROVENANCE_REQUIRED,
                                    -> false
                                }
                    }
                    val publishedPropertyAccessorKeys = properties.flatMap { property ->
                        listOfNotNull(property.getterLogicalMemberKey, property.setterLogicalMemberKey)
                    }.toSet()
                    val expectedAccessorKind = when (operation) {
                        DotNetGenericOwnerPhysicalStateAccessOperation.READ ->
                            DotNetGenericOwnerPropertyAccessorKind.GETTER
                        DotNetGenericOwnerPhysicalStateAccessOperation.WRITE ->
                            DotNetGenericOwnerPropertyAccessorKind.SETTER
                    }
                    return candidates.singleOrNull { member ->
                        member.logicalBindingKey in publishedPropertyAccessorKeys &&
                                member.propertyAccessorKind == expectedAccessorKind
                    } ?: candidates.single()
                }
                val physicalInitializers = state.initializers.mapNotNull { initializer ->
                    when (initializer.kind) {
                        DotNetGenericOwnerPrototypeStateInitializerKind.DEFAULT_ZERO_VALUE,
                        DotNetGenericOwnerPrototypeStateInitializerKind.DEFAULT_NULL_REFERENCE,
                        -> null
                        DotNetGenericOwnerPrototypeStateInitializerKind.POSITIONAL_CONSTRUCTOR_PARAMETER ->
                            DotNetGenericOwnerPhysicalStateInitializerRecord(
                                kind =
                                    DotNetGenericOwnerPhysicalStateInitializerKind.POSITIONAL_CONSTRUCTOR_PARAMETER,
                                conversion = when (state.requirement) {
                                    DotNetGenericOwnerStateCarrierRequirement.DECLARATION_INDEPENDENT_STORAGE,
                                    DotNetGenericOwnerStateCarrierRequirement.TYPED_STORAGE_PRODUCER_GRAPH_PROVEN,
                                    -> DotNetGenericOwnerPhysicalStateAccessConversion.IDENTITY
                                    DotNetGenericOwnerStateCarrierRequirement.SEMANTIC_OBJECT_REQUIRED,
                                    DotNetGenericOwnerStateCarrierRequirement.VOLATILE_OBJECT_STORAGE_REQUIRED,
                                    -> DotNetGenericOwnerPhysicalStateAccessConversion
                                        .INPUT_TO_STATE_BOX_OR_REFERENCE_WIDEN
                                    DotNetGenericOwnerStateCarrierRequirement.COMPLETE_ACCESS_GRAPH_REQUIRED,
                                    DotNetGenericOwnerStateCarrierRequirement.TYPED_WRITE_VALUE_PROVENANCE_REQUIRED,
                                    -> error("An unresolved hostile state cannot publish an initializer")
                                },
                                logicalConstructorKeys =
                                    listOf(checkNotNull(initializer.constructorLogicalBindingKey)),
                                fixedElementCount = null,
                                constructorParameterIndex = checkNotNull(initializer.constructorParameterIndex),
                            )
                        DotNetGenericOwnerPrototypeStateInitializerKind.FIXED_ZEROED_SZ_ARRAY,
                        DotNetGenericOwnerPrototypeStateInitializerKind.UNSUPPORTED,
                        -> error("The hostile physical family has an unsupported state initializer: $initializer")
                    }
                }
                DotNetGenericOwnerPhysicalStateRecord(
                    logicalFieldName = state.fieldName,
                    physicalFieldName = state.fieldName,
                    physicalVisibility = DotNetGenericOwnerPhysicalStateVisibility.PRIVATE,
                    requirement = state.requirement,
                    memorySemantics = state.memorySemantics,
                    physicalType = when (state.requirement) {
                        DotNetGenericOwnerStateCarrierRequirement.DECLARATION_INDEPENDENT_STORAGE ->
                            error("The hostile family does not admit declaration-independent scenario state")
                        DotNetGenericOwnerStateCarrierRequirement.SEMANTIC_OBJECT_REQUIRED ->
                            DotNetGenericOwnerPhysicalTypeExpressionRecord.objectType()
                        DotNetGenericOwnerStateCarrierRequirement.VOLATILE_OBJECT_STORAGE_REQUIRED ->
                            DotNetGenericOwnerPhysicalTypeExpressionRecord.objectType()
                        DotNetGenericOwnerStateCarrierRequirement.TYPED_STORAGE_PRODUCER_GRAPH_PROVEN ->
                            checkNotNull(state.exactTypedCarrierType) {
                                "The hostile typed state lacks an exact compiler-derived carrier: $state"
                            }.bindProducerTypes(physicalOwnerPathsByLogicalKey)
                        DotNetGenericOwnerStateCarrierRequirement.COMPLETE_ACCESS_GRAPH_REQUIRED,
                        DotNetGenericOwnerStateCarrierRequirement.TYPED_WRITE_VALUE_PROVENANCE_REQUIRED,
                        -> error("The hostile physical family cannot publish unresolved state storage")
                    },
                    nullableReferenceFlags = checkNotNull(state.physicalCarrierNullableReferenceFlags) {
                        "The hostile physical state lacks its detached nullable contract: $state"
                    },
                    initializers = physicalInitializers,
                    accessPaths = when (state.requirement) {
                        DotNetGenericOwnerStateCarrierRequirement.DECLARATION_INDEPENDENT_STORAGE ->
                            error("The hostile family does not admit declaration-independent scenario state")
                        DotNetGenericOwnerStateCarrierRequirement.SEMANTIC_OBJECT_REQUIRED -> {
                            val writer = stateFamily(DotNetGenericOwnerPhysicalStateAccessOperation.WRITE)
                            val reader = stateFamily(DotNetGenericOwnerPhysicalStateAccessOperation.READ)
                            listOf(
                                access(
                                    writer,
                                    DotNetGenericOwnerPhysicalStateAccessDomain.TYPED,
                                    DotNetGenericOwnerPhysicalStateAccessOperation.WRITE,
                                    DotNetGenericOwnerPhysicalStateAccessConversion.INPUT_TO_STATE_BOX_OR_REFERENCE_WIDEN,
                                ),
                                access(
                                    writer,
                                    DotNetGenericOwnerPhysicalStateAccessDomain.SEMANTIC,
                                    DotNetGenericOwnerPhysicalStateAccessOperation.WRITE,
                                    DotNetGenericOwnerPhysicalStateAccessConversion.IDENTITY,
                                ),
                                access(
                                    reader,
                                    DotNetGenericOwnerPhysicalStateAccessDomain.TYPED,
                                    DotNetGenericOwnerPhysicalStateAccessOperation.READ,
                                    DotNetGenericOwnerPhysicalStateAccessConversion.STATE_TO_OUTPUT_CHECKED_CAST_OR_UNBOX,
                                ),
                                access(
                                    reader,
                                    DotNetGenericOwnerPhysicalStateAccessDomain.SEMANTIC,
                                    DotNetGenericOwnerPhysicalStateAccessOperation.READ,
                                    DotNetGenericOwnerPhysicalStateAccessConversion.IDENTITY,
                                ),
                            )
                        }
                        DotNetGenericOwnerStateCarrierRequirement.VOLATILE_OBJECT_STORAGE_REQUIRED -> {
                            val writer = stateFamily(DotNetGenericOwnerPhysicalStateAccessOperation.WRITE)
                            val reader = stateFamily(DotNetGenericOwnerPhysicalStateAccessOperation.READ)
                            listOf(
                                access(
                                    writer,
                                    DotNetGenericOwnerPhysicalStateAccessDomain.TYPED,
                                    DotNetGenericOwnerPhysicalStateAccessOperation.WRITE,
                                    DotNetGenericOwnerPhysicalStateAccessConversion.INPUT_TO_STATE_BOX_OR_REFERENCE_WIDEN,
                                ),
                                access(
                                    reader,
                                    DotNetGenericOwnerPhysicalStateAccessDomain.TYPED,
                                    DotNetGenericOwnerPhysicalStateAccessOperation.READ,
                                    DotNetGenericOwnerPhysicalStateAccessConversion.STATE_TO_OUTPUT_CHECKED_CAST_OR_UNBOX,
                                ),
                            )
                        }
                        DotNetGenericOwnerStateCarrierRequirement.TYPED_STORAGE_PRODUCER_GRAPH_PROVEN -> {
                            val writer = stateFamily(DotNetGenericOwnerPhysicalStateAccessOperation.WRITE)
                            val reader = stateFamily(DotNetGenericOwnerPhysicalStateAccessOperation.READ)
                            listOf(
                                access(
                                    writer,
                                    DotNetGenericOwnerPhysicalStateAccessDomain.TYPED,
                                    DotNetGenericOwnerPhysicalStateAccessOperation.WRITE,
                                    DotNetGenericOwnerPhysicalStateAccessConversion.IDENTITY,
                                ),
                                access(
                                    reader,
                                    DotNetGenericOwnerPhysicalStateAccessDomain.TYPED,
                                    DotNetGenericOwnerPhysicalStateAccessOperation.READ,
                                    DotNetGenericOwnerPhysicalStateAccessConversion.IDENTITY,
                                ),
                            )
                        }
                        DotNetGenericOwnerStateCarrierRequirement.COMPLETE_ACCESS_GRAPH_REQUIRED,
                        DotNetGenericOwnerStateCarrierRequirement.TYPED_WRITE_VALUE_PROVENANCE_REQUIRED,
                        -> error("The hostile physical family cannot publish unresolved state access")
                    },
                    isInitOnly = state.isFinal,
                )
            },
        )
    }
    return DotNetGenericOwnerPhysicalFamilyArtifact(
        producerFingerprint = producerFingerprint,
        targetProfile = when (target) {
            DotNetTarget.NET48 -> DotNetGenericOwnerPhysicalTargetProfile.NET48
            DotNetTarget.NET10_0 -> DotNetGenericOwnerPhysicalTargetProfile.NET10_0
            DotNetTarget.NETSTANDARD_2_0 -> error("The hostile physical family has no netstandard profile")
        },
        classifications = classifications,
        interfaceTypes = interfaceTypes,
        owners = owners,
    )
}

private fun createGenericOwnerRepresentativeOctoTreePhysicalFamilyArtifact(
    prototypes: List<DotNetGenericOwnerPrototypeSnapshot>,
    producerFingerprint: String,
    target: DotNetTarget,
): DotNetGenericOwnerPhysicalFamilyArtifact {
    val selectedPrototypes = listOf(
        "OctoTree",
        "OctoTree.Node",
        "OctoTree.Node.Branch",
        "OctoTree.Node.Leaf",
    ).map { ownerName ->
        prototypes.single { prototype -> prototype.ownerName == ownerName }
    }
    val physicalSimpleNames = mapOf(
        "OctoTree" to "OctoTree",
        "OctoTree.Node" to "OctoTreeNode",
        "OctoTree.Node.Branch" to "OctoTreeBranch",
        "OctoTree.Node.Leaf" to "OctoTreeLeaf",
    )
    val physicalOwnerPathsByLogicalKey = selectedPrototypes.associate { prototype ->
        checkNotNull(prototype.logicalBindingKey) to listOf(
            "KotlinRepresentativeCandidate",
            physicalSimpleNames.getValue(prototype.ownerName),
        )
    }
    val prototypesByLogicalKey = selectedPrototypes.associateBy { prototype ->
        checkNotNull(prototype.logicalBindingKey)
    }
    val membersByLogicalKey = prototypes.flatMap { prototype ->
        prototype.members.mapNotNull { member ->
            member.logicalBindingKey?.let { logicalKey -> logicalKey to (prototype to member) }
        }
    }.toMap()
    val constructorsByLogicalKey = selectedPrototypes.flatMap { prototype ->
        prototype.constructors.mapNotNull { constructor ->
            constructor.logicalBindingKey?.let { logicalKey -> logicalKey to (prototype to constructor) }
        }
    }.toMap()
    val classifications = prototypes.mapNotNull { prototype ->
        val logicalOwnerKey = prototype.logicalBindingKey ?: return@mapNotNull null
        DotNetGenericOwnerCandidateClassificationRecord(
            logicalOwnerKey = logicalOwnerKey,
            genericArity = prototype.genericArity,
            disposition = prototype.disposition,
            logicalConstructorKeys = prototype.constructors.mapNotNull { constructor ->
                constructor.logicalBindingKey
            }.distinct().sorted(),
            logicalMemberKeys = prototype.members.mapNotNull { member ->
                member.logicalBindingKey
            }.distinct().sorted(),
        )
    }.sortedBy { classification -> classification.logicalOwnerKey }
    fun overrideRoots(
        member: DotNetGenericOwnerPrototypeMemberSnapshot,
        visiting: Set<String> = emptySet(),
    ): Set<String> {
        val logicalKey = checkNotNull(member.logicalBindingKey)
        check(logicalKey !in visiting) { "OctoTree override-family roots contain a cycle at '$logicalKey'" }
        val overriddenKeys = member.overrideBindings.mapNotNull { binding -> binding.overriddenLogicalBindingKey }
        if (overriddenKeys.isEmpty()) return setOf(logicalKey)
        return overriddenKeys.flatMapTo(linkedSetOf()) { overriddenKey ->
            membersByLogicalKey[overriddenKey]
                ?.let { overridden -> overrideRoots(overridden.second, visiting + logicalKey) }
                ?: setOf(overriddenKey)
        }
    }

    val owners = selectedPrototypes.map { prototype ->
        val logicalOwnerKey = checkNotNull(prototype.logicalBindingKey)
        val ownerPath = physicalOwnerPathsByLogicalKey.getValue(logicalOwnerKey)
        val hasCapability = prototype.members.any { member ->
            DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER in member.roles
        }
        val capabilityOwnerPath = if (hasCapability) {
            listOf("KotlinRepresentativeCandidate", "I${physicalSimpleNames.getValue(prototype.ownerName)}Semantic")
        } else {
            null
        }
        val constructors = prototype.constructors.map { constructor ->
            val logicalConstructorKey = checkNotNull(constructor.logicalBindingKey) {
                "The OctoTree physical family requires every logical constructor binding"
            }
            val signature = checkNotNull(constructor.exactPathUnboundSignature) {
                "The OctoTree physical family requires an exact constructor signature"
            }.bindProducerTypes(physicalOwnerPathsByLogicalKey)
            val delegatesToCoreAny =
                constructor.delegatedOwnerName == "kotlin.Any" || constructor.delegatedOwnerName == "Any"
            val delegated = if (delegatesToCoreAny) {
                null
            } else {
                val delegatedLogicalKey = checkNotNull(constructor.delegatedConstructorLogicalBindingKey) {
                    "The ${prototype.ownerName} constructor '$logicalConstructorKey' has no logical target for " +
                            "its non-Any base '${constructor.delegatedOwnerName}'"
                }
                checkNotNull(constructorsByLogicalKey[delegatedLogicalKey]) {
                    "The ${prototype.ownerName} constructor '$logicalConstructorKey' delegates to " +
                            "'$delegatedLogicalKey' on '${constructor.delegatedOwnerName}' outside its selected " +
                            "physical family"
                }
            }
            val delegatedOwnerType = if (delegated == null) {
                check(delegatesToCoreAny)
                DotNetGenericOwnerPhysicalTypeExpressionRecord.coreType(
                    typePath = listOf("System", "Object"),
                    category = DotNetGenericOwnerPhysicalNamedTypeCategory.CLASS,
                )
            } else {
                val delegatedPrototype = delegated.first
                DotNetGenericOwnerPhysicalTypeExpressionRecord.producerType(
                    typePath = physicalOwnerPathsByLogicalKey.getValue(
                        checkNotNull(delegatedPrototype.logicalBindingKey),
                    ),
                    category = DotNetGenericOwnerPhysicalNamedTypeCategory.CLASS,
                    arguments = List(delegatedPrototype.genericArity) { index ->
                        DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(index)
                    },
                )
            }
            val delegatedSignature = delegated?.second?.exactPathUnboundSignature
                ?.bindProducerTypes(physicalOwnerPathsByLogicalKey)
                ?: DotNetGenericOwnerPhysicalMethodSignatureRecord(
                    isInstance = true,
                    genericArity = 0,
                    returnSlot = DotNetGenericOwnerPhysicalValueSlotRecord(
                        DotNetGenericOwnerPhysicalSlotDomain.DECLARATION_INDEPENDENT,
                        DotNetGenericOwnerPhysicalTypeExpressionRecord.voidType(),
                    ),
                    parameterSlots = emptyList(),
                )
            DotNetGenericOwnerPhysicalConstructorRecord(
                logicalConstructorKey = logicalConstructorKey,
                constructionMode = DotNetGenericOwnerConstructionMode.STATIC_EXACT,
                visibility = if (prototype.physicalDispatch == DotNetGenericOwnerPhysicalTypeDispatch.SEALED) {
                    DotNetGenericOwnerPhysicalConstructorVisibility.FAMILY_AND_ASSEMBLY
                } else {
                    constructor.physicalVisibility
                },
                constructedOwnerType = DotNetGenericOwnerPhysicalTypeExpressionRecord.producerType(
                    typePath = ownerPath,
                    category = DotNetGenericOwnerPhysicalNamedTypeCategory.CLASS,
                    arguments = List(prototype.genericArity) { index ->
                        DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(index)
                    },
                ),
                physicalConstructor = DotNetGenericOwnerPhysicalMethodIdentityRecord(
                    physicalOwnerPath = ownerPath,
                    physicalMethodName = ".ctor",
                    signature = signature,
                ),
                delegation = DotNetGenericOwnerPhysicalDelegatingConstructorRecord(
                    kind = if (constructor.delegatesToThis) {
                        DotNetGenericOwnerConstructorDelegationKind.THIS
                    } else {
                        DotNetGenericOwnerConstructorDelegationKind.BASE
                    },
                    logicalConstructorKey = constructor.delegatedConstructorLogicalBindingKey,
                    physicalOwnerType = delegatedOwnerType,
                    physicalMethodName = ".ctor",
                    signature = delegatedSignature,
                ),
            )
        }
        val members = prototype.members.mapNotNull { member ->
            val logicalMemberKey = member.logicalBindingKey ?: return@mapNotNull null
            val memberOverrideRoots = overrideRoots(member).sorted()
            DotNetGenericOwnerPhysicalMemberFamilyRecord(
                logicalMemberKey = logicalMemberKey,
                overrideRootLogicalMemberKeys = memberOverrideRoots,
                policy = member.policy,
                roles = member.roles,
                semanticHookReasons = member.semanticHookReasons,
                slots = member.roles.map { role ->
                    val signature = checkNotNull(member.exactPathUnboundSignatures?.get(role)) {
                        "The OctoTree physical family lacks ${member.sourceName}/$role signature evidence"
                    }.bindProducerTypes(physicalOwnerPathsByLogicalKey)
                    val isCapability = role == DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER
                    val methodName = genericOwnerPrototypePhysicalMethodName(member, role, memberOverrideRoots)
                    DotNetGenericOwnerPhysicalMemberSlotRecord(
                        role = role,
                        visibility = when (role) {
                            DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY -> member.physicalVisibility
                            DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK ->
                                DotNetGenericOwnerPhysicalMemberVisibility.FAMILY
                            DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER ->
                                DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE
                        },
                        physicalOwnerPath = ownerPath,
                        physicalMethodName = if (isCapability) {
                            "${checkNotNull(capabilityOwnerPath).joinToString(".")}.$methodName"
                        } else {
                            methodName
                        },
                        dispatch = when {
                            isCapability -> DotNetGenericOwnerPhysicalMemberDispatch.FINAL
                            member.isAbstract -> DotNetGenericOwnerPhysicalMemberDispatch.ABSTRACT
                            member.isOverridable -> DotNetGenericOwnerPhysicalMemberDispatch.OVERRIDABLE
                            else -> DotNetGenericOwnerPhysicalMemberDispatch.FINAL
                        },
                        signature = signature,
                        capabilitySlot = if (isCapability) {
                            DotNetGenericOwnerPhysicalMethodIdentityRecord(
                                physicalOwnerPath = checkNotNull(capabilityOwnerPath),
                                physicalMethodName = methodName,
                                signature = signature,
                            )
                        } else {
                            null
                        },
                    )
                },
                directSuperTargets = member.directSuperCalls.flatMap { call ->
                    val logicalTargetKey = checkNotNull(call.logicalMemberKey) {
                        "The OctoTree direct-super call lacks a logical member binding"
                    }
                    val target = checkNotNull(membersByLogicalKey[logicalTargetKey]) {
                        "The OctoTree direct-super call targets an unrecorded member"
                    }
                    val targetPrototype = target.first
                    val targetMember = target.second
                    member.roles.filter { role ->
                        role != DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER
                    }.map { role ->
                        DotNetGenericOwnerPhysicalDirectSuperTargetRecord(
                            role = role,
                            logicalTargetMemberKey = logicalTargetKey,
                            physicalOwnerPath = physicalOwnerPathsByLogicalKey.getValue(
                                checkNotNull(targetPrototype.logicalBindingKey),
                            ),
                            physicalMethodName = genericOwnerPrototypePhysicalMethodName(
                                targetMember,
                                role,
                                overrideRoots(targetMember).sorted(),
                            ),
                            signature = checkNotNull(targetMember.exactPathUnboundSignatures?.get(role)) {
                                "The OctoTree direct-super target lacks its exact role signature"
                            }.bindProducerTypes(physicalOwnerPathsByLogicalKey),
                        )
                    }
                },
                defaultDispatcher = member.exactMaskedDefaultDispatcher?.let { dispatcher ->
                    DotNetGenericOwnerPhysicalDefaultDispatcherRecord(
                        physicalOwnerPath = ownerPath,
                        physicalMethodName = dotNetGenericOwnerPhysicalDefaultDispatcherName(
                            genericOwnerPrototypePhysicalMethodName(
                                member,
                                DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
                                memberOverrideRoots,
                            ),
                            logicalMemberKey,
                        ),
                        signature = dispatcher.physicalSignature(
                            ownerPath,
                            prototype.genericArity,
                            physicalOwnerPathsByLogicalKey,
                        ),
                    )
                },
            )
        }
        val properties = genericOwnerPhysicalProperties(prototype, members, "The OctoTree")
        val implementationMethods = prototype.members.mapNotNull { member ->
            if (member.logicalBindingKey != null ||
                    member.physicalVisibility != DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE ||
                    member.isPropertyAccessor || member.isFakeOverride
            ) {
                return@mapNotNull null
            }
            check(member.physicalVisibility == DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE &&
                    !member.isAbstract && !member.isOverridable && !member.isFakeOverride &&
                    member.roles == setOf(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY) &&
                    member.overrideBindings.isEmpty() && member.directSuperCalls.isEmpty() &&
                    member.exactMaskedDefaultDispatcher == null) {
                "The OctoTree physical family cannot retain unsupported non-KLIB member '${member.sourceName}'"
            }
            val signature = checkNotNull(member.exactPathUnboundSignatures)
                .getValue(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY)
                .bindProducerTypes(physicalOwnerPathsByLogicalKey)
            DotNetGenericOwnerPhysicalImplementationMethodRecord(
                physicalMethod = DotNetGenericOwnerPhysicalMethodIdentityRecord(
                    physicalOwnerPath = ownerPath,
                    physicalMethodName = member.physicalBaseName,
                    signature = signature,
                ),
                visibility = DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE,
                dispatch = DotNetGenericOwnerPhysicalMemberDispatch.FINAL,
            )
        }
        check(members.map { member -> member.logicalMemberKey }.toSet() ==
                prototype.members.mapNotNull { member -> member.logicalBindingKey }.toSet()) {
            "The OctoTree physical family omitted a bindable logical member"
        }
        val baseConstructorKeys = constructors.filter { constructor ->
            constructor.delegation.kind == DotNetGenericOwnerConstructorDelegationKind.BASE
        }.map { constructor -> constructor.logicalConstructorKey }.sorted()
        val states = prototype.states.mapIndexed { stateIndex, state ->
            val physicalType = when (state.requirement) {
                DotNetGenericOwnerStateCarrierRequirement.DECLARATION_INDEPENDENT_STORAGE ->
                    checkNotNull(state.exactTypedCarrierType) {
                        "The OctoTree declaration-independent state lacks an exact compiler-derived carrier"
                    }.bindProducerTypes(physicalOwnerPathsByLogicalKey)
                DotNetGenericOwnerStateCarrierRequirement.SEMANTIC_OBJECT_REQUIRED ->
                    DotNetGenericOwnerPhysicalTypeExpressionRecord.objectType()
                DotNetGenericOwnerStateCarrierRequirement.VOLATILE_OBJECT_STORAGE_REQUIRED ->
                    error("The OctoTree fixture does not admit volatile owner state")
                DotNetGenericOwnerStateCarrierRequirement.TYPED_STORAGE_PRODUCER_GRAPH_PROVEN ->
                    checkNotNull(state.exactTypedCarrierType) {
                        "The OctoTree typed state lacks an exact compiler-derived carrier"
                    }.bindProducerTypes(physicalOwnerPathsByLogicalKey)
                DotNetGenericOwnerStateCarrierRequirement.COMPLETE_ACCESS_GRAPH_REQUIRED,
                DotNetGenericOwnerStateCarrierRequirement.TYPED_WRITE_VALUE_PROVENANCE_REQUIRED,
                -> error("The OctoTree physical family cannot publish unresolved state storage")
            }
            val stateNullableReferenceFlags = checkNotNull(state.physicalCarrierNullableReferenceFlags) {
                "The OctoTree state '${state.fieldName}' lacks a detached nullable contract"
            }
            val initializers = state.initializers.mapNotNull { initializer ->
                when (initializer.kind) {
                    DotNetGenericOwnerPrototypeStateInitializerKind.DEFAULT_ZERO_VALUE -> {
                        check(state.exactTypedCarrierType?.referencesOwnerParameter() == false) {
                            "The OctoTree default-zero initializer targets owner-dependent state: $state"
                        }
                        // CLR fields already contain their zero value before constructor execution.
                        null
                    }
                    DotNetGenericOwnerPrototypeStateInitializerKind.FIXED_ZEROED_SZ_ARRAY ->
                        DotNetGenericOwnerPhysicalStateInitializerRecord(
                            kind = DotNetGenericOwnerPhysicalStateInitializerKind.FIXED_ZEROED_SZ_ARRAY,
                            conversion = DotNetGenericOwnerPhysicalStateAccessConversion.IDENTITY,
                            fixedElementCount = checkNotNull(initializer.fixedElementCount),
                            constructorParameterIndex = null,
                            logicalConstructorKeys = baseConstructorKeys,
                        )
                    DotNetGenericOwnerPrototypeStateInitializerKind.DEFAULT_NULL_REFERENCE -> {
                        check(physicalType.kind == DotNetGenericOwnerPhysicalTypeKind.NAMED &&
                                physicalType.namedTypeCategory ==
                                DotNetGenericOwnerPhysicalNamedTypeCategory.CLASS) {
                            "The OctoTree default-null initializer does not target proven reference storage: $state"
                        }
                        // CLR reference fields are already null before any constructor body executes.
                        null
                    }
                    DotNetGenericOwnerPrototypeStateInitializerKind.POSITIONAL_CONSTRUCTOR_PARAMETER ->
                        DotNetGenericOwnerPhysicalStateInitializerRecord(
                            kind = DotNetGenericOwnerPhysicalStateInitializerKind.POSITIONAL_CONSTRUCTOR_PARAMETER,
                            conversion = DotNetGenericOwnerPhysicalStateAccessConversion.IDENTITY,
                            fixedElementCount = null,
                            constructorParameterIndex = checkNotNull(initializer.constructorParameterIndex),
                            logicalConstructorKeys = listOf(checkNotNull(initializer.constructorLogicalBindingKey)),
                        )
                    DotNetGenericOwnerPrototypeStateInitializerKind.UNSUPPORTED -> error(
                        "The OctoTree physical family has an unsupported state initializer: $initializer"
                    )
                }
            }
            fun logicalAccessOrNull(
                operation: DotNetGenericOwnerPhysicalStateAccessOperation,
            ): DotNetGenericOwnerPhysicalStateAccessRecord? {
                val candidates = prototype.members.mapNotNull { source ->
                    val logicalMemberKey = source.logicalBindingKey ?: return@mapNotNull null
                    val reachesState = when (operation) {
                        DotNetGenericOwnerPhysicalStateAccessOperation.READ ->
                            state.fieldName in source.directStateReadNames
                        DotNetGenericOwnerPhysicalStateAccessOperation.WRITE ->
                            state.fieldName in source.directStateWriteNames
                    }
                    if (!reachesState || DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY !in source.roles) {
                        return@mapNotNull null
                    }
                    val signature = source.exactPathUnboundSignatures
                        ?.get(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY)
                        ?.bindProducerTypes(physicalOwnerPathsByLogicalKey)
                        ?: return@mapNotNull null
                    val matchesCarrier = when (operation) {
                        DotNetGenericOwnerPhysicalStateAccessOperation.READ ->
                            signature.parameterSlots.isEmpty() && signature.returnSlot.type == physicalType &&
                                    signature.returnSlot.nullableReferenceFlags == stateNullableReferenceFlags
                        DotNetGenericOwnerPhysicalStateAccessOperation.WRITE ->
                            signature.parameterSlots.singleOrNull()?.type == physicalType &&
                                    signature.parameterSlots.single().nullableReferenceFlags ==
                                    stateNullableReferenceFlags &&
                                    signature.returnSlot.type.kind == DotNetGenericOwnerPhysicalTypeKind.VOID
                    }
                    if (!matchesCarrier) return@mapNotNull null
                    val slot = members.single { member -> member.logicalMemberKey == logicalMemberKey }
                        .slots.single { slot -> slot.role == DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY }
                    DotNetGenericOwnerPhysicalStateAccessRecord(
                        domain = DotNetGenericOwnerPhysicalStateAccessDomain.TYPED,
                        operation = operation,
                        conversion = DotNetGenericOwnerPhysicalStateAccessConversion.IDENTITY,
                        bindingKind = DotNetGenericOwnerPhysicalStateAccessBindingKind.LOGICAL_MEMBER_FAMILY,
                        logicalMemberKey = logicalMemberKey,
                        role = DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
                        physicalVisibility = null,
                        physicalMethod = DotNetGenericOwnerPhysicalMethodIdentityRecord(
                            slot.physicalOwnerPath,
                            slot.physicalMethodName,
                            slot.signature,
                        ),
                    )
                }
                check(candidates.size <= 1) {
                    "The OctoTree state '${state.fieldName}' has ambiguous exact $operation access: $candidates"
                }
                return candidates.singleOrNull()
            }
            fun privateTypedAccessOrNull(
                operation: DotNetGenericOwnerPhysicalStateAccessOperation,
            ): DotNetGenericOwnerPhysicalStateAccessRecord? {
                val candidates = prototype.members.filter { source ->
                    val reachesState = when (operation) {
                        DotNetGenericOwnerPhysicalStateAccessOperation.READ ->
                            state.fieldName in source.directStateReadNames
                        DotNetGenericOwnerPhysicalStateAccessOperation.WRITE ->
                            state.fieldName in source.directStateWriteNames
                    }
                    reachesState && source.logicalBindingKey == null && source.isPropertyAccessor &&
                            source.physicalVisibility == DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE &&
                            source.roles == setOf(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY) &&
                            source.exactPathUnboundSignatures
                                ?.get(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY)
                                ?.bindProducerTypes(physicalOwnerPathsByLogicalKey)
                                ?.let { signature ->
                                    when (operation) {
                                        DotNetGenericOwnerPhysicalStateAccessOperation.READ ->
                                            signature.parameterSlots.isEmpty() &&
                                                    signature.returnSlot.type == physicalType &&
                                                    signature.returnSlot.nullableReferenceFlags ==
                                                    stateNullableReferenceFlags
                                        DotNetGenericOwnerPhysicalStateAccessOperation.WRITE ->
                                            signature.parameterSlots.singleOrNull()?.type == physicalType &&
                                                    signature.parameterSlots.single().nullableReferenceFlags ==
                                                    stateNullableReferenceFlags &&
                                                    signature.returnSlot.type.kind ==
                                                    DotNetGenericOwnerPhysicalTypeKind.VOID
                                    }
                                } == true
                }
                check(candidates.size <= 1) {
                    "The OctoTree state '${state.fieldName}' has ambiguous private typed $operation access: $candidates"
                }
                if (candidates.isEmpty()) return null
                val signature = DotNetGenericOwnerPhysicalMethodSignatureRecord(
                    isInstance = true,
                    genericArity = 0,
                    returnSlot = DotNetGenericOwnerPhysicalValueSlotRecord(
                        if (operation == DotNetGenericOwnerPhysicalStateAccessOperation.READ) {
                            DotNetGenericOwnerPhysicalSlotDomain.STRICT_OWNER_OUTPUT
                        } else {
                            DotNetGenericOwnerPhysicalSlotDomain.DECLARATION_INDEPENDENT
                        },
                        if (operation == DotNetGenericOwnerPhysicalStateAccessOperation.READ) {
                            physicalType
                        } else {
                            DotNetGenericOwnerPhysicalTypeExpressionRecord.voidType()
                        },
                        if (operation == DotNetGenericOwnerPhysicalStateAccessOperation.READ) {
                            stateNullableReferenceFlags
                        } else {
                            emptyList()
                        },
                    ),
                    parameterSlots = if (operation == DotNetGenericOwnerPhysicalStateAccessOperation.WRITE) {
                        listOf(DotNetGenericOwnerPhysicalValueSlotRecord(
                            DotNetGenericOwnerPhysicalSlotDomain.STRICT_OWNER_INPUT,
                            physicalType,
                            stateNullableReferenceFlags,
                        ))
                    } else {
                        emptyList()
                    },
                )
                return DotNetGenericOwnerPhysicalStateAccessRecord(
                    domain = DotNetGenericOwnerPhysicalStateAccessDomain.TYPED,
                    operation = operation,
                    conversion = DotNetGenericOwnerPhysicalStateAccessConversion.IDENTITY,
                    bindingKind = DotNetGenericOwnerPhysicalStateAccessBindingKind.PRODUCER_PRIVATE_METHOD,
                    logicalMemberKey = null,
                    role = null,
                    physicalVisibility = DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE,
                    physicalMethod = DotNetGenericOwnerPhysicalMethodIdentityRecord(
                        physicalOwnerPath = ownerPath,
                        physicalMethodName = "__kotlin_state_${stateIndex}_${operation.name.lowercase()}",
                        signature = signature,
                    ),
                )
            }
            val accessPaths = when (state.requirement) {
                DotNetGenericOwnerStateCarrierRequirement.DECLARATION_INDEPENDENT_STORAGE -> buildList {
                    logicalAccessOrNull(DotNetGenericOwnerPhysicalStateAccessOperation.READ)?.let(::add)
                    logicalAccessOrNull(DotNetGenericOwnerPhysicalStateAccessOperation.WRITE)?.let(::add)
                }
                DotNetGenericOwnerStateCarrierRequirement.SEMANTIC_OBJECT_REQUIRED -> {
                    check(initializers.isEmpty() && prototype.members.any { member ->
                        state.fieldName in member.transitiveStateReadNames
                    } && prototype.members.any { member ->
                        state.fieldName in member.transitiveStateWriteNames
                    }) {
                        "The OctoTree semantic state lacks its complete producer access graph"
                    }
                    fun privateAccess(
                        operation: DotNetGenericOwnerPhysicalStateAccessOperation,
                    ): DotNetGenericOwnerPhysicalStateAccessRecord {
                        val signature = DotNetGenericOwnerPhysicalMethodSignatureRecord(
                            isInstance = true,
                            genericArity = 0,
                            returnSlot = DotNetGenericOwnerPhysicalValueSlotRecord(
                                if (operation == DotNetGenericOwnerPhysicalStateAccessOperation.READ) {
                                    DotNetGenericOwnerPhysicalSlotDomain.STRICT_OWNER_OUTPUT
                                } else {
                                    DotNetGenericOwnerPhysicalSlotDomain.DECLARATION_INDEPENDENT
                                },
                                if (operation == DotNetGenericOwnerPhysicalStateAccessOperation.READ) {
                                    physicalType
                                } else {
                                    DotNetGenericOwnerPhysicalTypeExpressionRecord.voidType()
                                },
                                if (operation == DotNetGenericOwnerPhysicalStateAccessOperation.READ) {
                                    stateNullableReferenceFlags
                                } else {
                                    emptyList()
                                },
                            ),
                            parameterSlots = if (operation == DotNetGenericOwnerPhysicalStateAccessOperation.WRITE) {
                                listOf(DotNetGenericOwnerPhysicalValueSlotRecord(
                                    DotNetGenericOwnerPhysicalSlotDomain.STRICT_OWNER_INPUT,
                                    physicalType,
                                    stateNullableReferenceFlags,
                                ))
                            } else {
                                emptyList()
                            },
                        )
                        return DotNetGenericOwnerPhysicalStateAccessRecord(
                            domain = DotNetGenericOwnerPhysicalStateAccessDomain.TYPED,
                            operation = operation,
                            conversion = DotNetGenericOwnerPhysicalStateAccessConversion.IDENTITY,
                            bindingKind = DotNetGenericOwnerPhysicalStateAccessBindingKind.PRODUCER_PRIVATE_METHOD,
                            logicalMemberKey = null,
                            role = null,
                            physicalVisibility = DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE,
                            physicalMethod = DotNetGenericOwnerPhysicalMethodIdentityRecord(
                                physicalOwnerPath = ownerPath,
                                physicalMethodName = "__kotlin_state_${stateIndex}_${operation.name.lowercase()}",
                                signature = signature,
                            ),
                        )
                    }
                    DotNetGenericOwnerPhysicalStateAccessOperation.entries.map(::privateAccess)
                }
                DotNetGenericOwnerStateCarrierRequirement.VOLATILE_OBJECT_STORAGE_REQUIRED ->
                    error("The OctoTree fixture does not admit volatile owner state")
                DotNetGenericOwnerStateCarrierRequirement.TYPED_STORAGE_PRODUCER_GRAPH_PROVEN -> buildList {
                    add(checkNotNull(
                        logicalAccessOrNull(DotNetGenericOwnerPhysicalStateAccessOperation.READ)
                            ?: privateTypedAccessOrNull(DotNetGenericOwnerPhysicalStateAccessOperation.READ)
                    ) {
                        "The OctoTree typed state '${state.fieldName}' lacks one exact logical read"
                    })
                    (logicalAccessOrNull(DotNetGenericOwnerPhysicalStateAccessOperation.WRITE)
                        ?: privateTypedAccessOrNull(DotNetGenericOwnerPhysicalStateAccessOperation.WRITE))?.let(::add)
                    check(initializers.isNotEmpty() || any { access ->
                        access.operation == DotNetGenericOwnerPhysicalStateAccessOperation.WRITE
                    }) {
                        "The OctoTree typed state '${state.fieldName}' lacks a physical write or initializer"
                    }
                }
                DotNetGenericOwnerStateCarrierRequirement.COMPLETE_ACCESS_GRAPH_REQUIRED,
                DotNetGenericOwnerStateCarrierRequirement.TYPED_WRITE_VALUE_PROVENANCE_REQUIRED,
                -> error("The OctoTree physical family cannot publish unresolved state access")
            }
            DotNetGenericOwnerPhysicalStateRecord(
                logicalFieldName = state.fieldName,
                physicalFieldName = "__kotlin_state_${stateIndex}_${state.fieldName}",
                physicalVisibility = DotNetGenericOwnerPhysicalStateVisibility.PRIVATE,
                requirement = state.requirement,
                memorySemantics = state.memorySemantics,
                physicalType = physicalType,
                nullableReferenceFlags = stateNullableReferenceFlags,
                initializers = initializers,
                accessPaths = accessPaths,
                isInitOnly = state.isFinal,
            )
        }
        val directSupertypes = prototype.directSupertypes.mapNotNull { supertype ->
            if (supertype.disposition != DotNetGenericOwnerPrototypeSupertypeDisposition.EXACT_PHYSICAL_EDGE) {
                return@mapNotNull null
            }
            val prototypeType = checkNotNull(supertype.exactPhysicalType)
            DotNetGenericOwnerPhysicalDirectSupertypeRecord(
                kind = supertype.kind,
                logicalClassifierKey = supertype.logicalClassifierKey,
                isSemanticCapability = false,
                physicalType = if (prototypeType.kind == DotNetGenericOwnerPrototypeTypeKind.OBJECT) {
                    DotNetGenericOwnerPhysicalTypeExpressionRecord.coreType(
                        typePath = listOf("System", "Object"),
                        category = DotNetGenericOwnerPhysicalNamedTypeCategory.CLASS,
                    )
                } else {
                    prototypeType.bindProducerTypes(physicalOwnerPathsByLogicalKey)
                },
                nullableReferenceFlags = checkNotNull(supertype.nullableReferenceFlags).toMutableList().apply {
                    this[0] = DotNetNullableReferenceFlag.OBLIVIOUS
                },
            )
        } + if (members.flatMap { member -> member.slots }.any { slot ->
            slot.role == DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER &&
                    slot.physicalOwnerPath == ownerPath
        }) {
            listOf(
                DotNetGenericOwnerPhysicalDirectSupertypeRecord(
                    kind = DotNetGenericOwnerDirectSupertypeKind.INTERFACE,
                    logicalClassifierKey = null,
                    isSemanticCapability = true,
                    physicalType = DotNetGenericOwnerPhysicalTypeExpressionRecord.producerType(
                        typePath = checkNotNull(capabilityOwnerPath),
                        category = DotNetGenericOwnerPhysicalNamedTypeCategory.INTERFACE,
                    ),
                    nullableReferenceFlags = listOf(DotNetNullableReferenceFlag.OBLIVIOUS),
                )
            )
        } else {
            emptyList()
        }
        DotNetGenericOwnerPhysicalFamilyRecord(
            logicalOwnerKey = logicalOwnerKey,
            physicalOwnerPath = ownerPath,
            physicalCapabilityOwnerPath = capabilityOwnerPath,
            physicalVisibility = prototype.physicalVisibility,
            physicalDispatch = prototype.physicalDispatch,
            genericArity = prototype.genericArity,
            physicalGenericParameters = checkNotNull(prototype.physicalGenericParameters) {
                "The OctoTree physical family requires exact GenericParam constraints"
            },
            directSupertypes = directSupertypes,
            disposition = prototype.disposition,
            runtimeClassificationMode = DotNetGenericOwnerRuntimeClassificationMode.OPEN_TYPEDEF_ANCESTRY,
            constructionModes = setOf(DotNetGenericOwnerConstructionMode.STATIC_EXACT),
            constructors = constructors,
            reflection = DotNetGenericOwnerPhysicalReflectionRecord(
                logicalClassifierKey = logicalOwnerKey,
                physicalOpenTypeDefinition = DotNetGenericOwnerPhysicalOpenTypeDefinitionRecord(
                    physicalTypePath = ownerPath,
                    genericArity = prototype.genericArity,
                ),
                classifierNormalizationMode =
                    DotNetGenericOwnerReflectionClassifierNormalizationMode.EXACT_OPEN_TYPEDEF,
                instanceClassificationMode = DotNetGenericOwnerRuntimeClassificationMode.OPEN_TYPEDEF_ANCESTRY,
                typeArgumentAuthority = DotNetGenericOwnerReflectionTypeArgumentAuthority.KLIB_LOGICAL_GRAPH,
                capabilityExposure = DotNetGenericOwnerReflectionCapabilityExposure.HIDDEN_COMPILER_ABI,
                callables = genericOwnerPhysicalReflectionCallables(members),
            ),
            members = members,
            properties = properties,
            states = states,
            implementationMethods = implementationMethods,
        )
    }
    check(owners.map { owner -> owner.logicalOwnerKey }.toSet() == prototypesByLogicalKey.keys) {
        "The OctoTree physical artifact did not select exactly its four logical owners"
    }
    return DotNetGenericOwnerPhysicalFamilyArtifact(
        producerFingerprint = producerFingerprint,
        targetProfile = when (target) {
            DotNetTarget.NET48 -> DotNetGenericOwnerPhysicalTargetProfile.NET48
            DotNetTarget.NET10_0 -> DotNetGenericOwnerPhysicalTargetProfile.NET10_0
            DotNetTarget.NETSTANDARD_2_0 -> error("The OctoTree physical family has no netstandard profile")
        },
        classifications = classifications,
        owners = owners,
    )
}

private fun validateGenericOwnerPhysicalFamilyCodec(
    artifact: DotNetGenericOwnerPhysicalFamilyArtifact,
    encoded: String,
) {
    fun expectRejected(label: String, operation: () -> Unit) {
        check(runCatching(operation).isFailure) {
            "The generic-owner family codec accepted $label"
        }
    }

    val decoded = DotNetGenericOwnerPhysicalFamilyCodec.decode(encoded, artifact.producerFingerprint)
    check(DotNetGenericOwnerPhysicalFamilyCodec.encode(decoded) == encoded &&
            DotNetGenericOwnerPhysicalFamilyCodec.encode(artifact) == encoded) {
        "The generic-owner physical family artifact has nondeterministic serialization"
    }
    val metadataFixedExclusion = decoded.classifications.single { classification ->
        classification.disposition ==
                DotNetGenericOwnerCandidateDisposition.BLOCKED_METADATA_FIXED_CONDITIONAL_SUPERTYPE
    }
    check(metadataFixedExclusion.logicalConstructorKeys.isNotEmpty() &&
            metadataFixedExclusion.logicalMemberKeys.isNotEmpty() &&
            decoded.owners.none { owner -> owner.logicalOwnerKey == metadataFixedExclusion.logicalOwnerKey }) {
        "The producer catalog did not retain its metadata-fixed erased-only classification"
    }
    val conditionalBase = metadataFixedExclusion.conditionalSupertypes.singleOrNull()
    check(conditionalBase?.kind == DotNetGenericOwnerDirectSupertypeKind.BASE_CLASS &&
            conditionalBase.logicalClassifierKey.isNotEmpty() &&
            conditionalBase.conditionalOwnerParameterIndices == listOf(0)) {
        "The metadata-fixed exclusion lost its exact bare-T? base blocker: $metadataFixedExclusion"
    }
    expectRejected("a metadata-fixed disposition without its conditional-supertype authority") {
        metadataFixedExclusion.copy(conditionalSupertypes = emptyList())
    }
    expectRejected("an out-of-range conditional-supertype owner parameter") {
        metadataFixedExclusion.copy(conditionalSupertypes = listOf(
            checkNotNull(conditionalBase).copy(
                conditionalOwnerParameterIndices = listOf(metadataFixedExclusion.genericArity),
            ),
        ))
    }
    val metadataFixedFailure = runCatching {
        decoded.requirePhysicalFamily(metadataFixedExclusion.logicalOwnerKey)
    }.exceptionOrNull()
    check(metadataFixedFailure?.message?.contains(
        DotNetGenericOwnerCandidateDisposition.BLOCKED_METADATA_FIXED_CONDITIONAL_SUPERTYPE.name
    ) == true) {
        "The producer catalog did not fail with the recorded metadata-fixed disposition: $metadataFixedFailure"
    }
    decoded.owners.forEach { owner ->
        check(decoded.requirePhysicalFamily(owner.logicalOwnerKey) == owner) {
            "The producer catalog did not resolve its exact published physical family"
        }
    }
    check(decoded.owners.all { owner ->
        owner.runtimeClassificationMode == DotNetGenericOwnerRuntimeClassificationMode.OPEN_TYPEDEF_ANCESTRY &&
                owner.physicalGenericParameters == List(owner.genericArity) { index ->
                    DotNetGenericOwnerPhysicalGenericParameterRecord(index, emptySet(), emptyList())
                } &&
                owner.constructionModes == setOf(DotNetGenericOwnerConstructionMode.STATIC_EXACT) &&
                owner.constructors.isNotEmpty() && owner.constructors.all { constructor ->
                    constructor.visibility == DotNetGenericOwnerPhysicalConstructorVisibility.PUBLIC &&
                            constructor.constructedOwnerType.typePath == owner.physicalOwnerPath
                } && owner.reflection.let { reflection ->
                    reflection.logicalClassifierKey == owner.logicalOwnerKey &&
                            reflection.physicalOpenTypeDefinition.physicalTypePath == owner.physicalOwnerPath &&
                            reflection.classifierNormalizationMode ==
                            DotNetGenericOwnerReflectionClassifierNormalizationMode.EXACT_OPEN_TYPEDEF &&
                            reflection.instanceClassificationMode == owner.runtimeClassificationMode &&
                            reflection.typeArgumentAuthority ==
                            DotNetGenericOwnerReflectionTypeArgumentAuthority.KLIB_LOGICAL_GRAPH &&
                            reflection.capabilityExposure ==
                            DotNetGenericOwnerReflectionCapabilityExposure.HIDDEN_COMPILER_ABI &&
                            reflection.callables.map { callable -> callable.logicalMemberKey }.toSet() ==
                            owner.members.map { candidate -> candidate.logicalMemberKey }.toSet()
                }
    }) {
        "The generic-owner artifact lacks its exact construction/profile/reflection record"
    }
    val nullableBaseOwner = decoded.owners.single { owner ->
        owner.physicalOwnerPath.last() == "HostileNullableReferenceBase"
    }
    val nullableDerivedOwner = decoded.owners.single { owner ->
        owner.physicalOwnerPath.last() == "HostileNullableReferenceDerived"
    }
    val typedStoreOwner = decoded.owners.single { owner ->
        owner.physicalOwnerPath.last() == "HostileTypedStore"
    }
    val abstractStorageSupertypeOwner = decoded.owners.single { owner ->
        owner.physicalOwnerPath.last() == "HostileAbstractPropertyStorage"
    }
    val nullableMarkerInterface = decoded.interfaceTypes.single { type ->
        type.physicalTypePath.last() == "HostileNullableMarker"
    }
    val expectedNestedNullableFlags = listOf(
        DotNetNullableReferenceFlag.OBLIVIOUS,
        DotNetNullableReferenceFlag.NULLABLE,
        DotNetNullableReferenceFlag.NON_NULL,
    )
    val expectedNullableBaseType = DotNetGenericOwnerPhysicalTypeExpressionRecord.producerType(
        typePath = nullableBaseOwner.physicalOwnerPath,
        category = DotNetGenericOwnerPhysicalNamedTypeCategory.CLASS,
        arguments = listOf(DotNetGenericOwnerPhysicalTypeExpressionRecord.producerType(
            typePath = typedStoreOwner.physicalOwnerPath,
            category = DotNetGenericOwnerPhysicalNamedTypeCategory.CLASS,
            arguments = listOf(DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(0)),
        )),
    )
    val expectedNullableInterfaceType = DotNetGenericOwnerPhysicalTypeExpressionRecord.producerType(
        typePath = nullableMarkerInterface.physicalTypePath,
        category = DotNetGenericOwnerPhysicalNamedTypeCategory.INTERFACE,
        arguments = listOf(DotNetGenericOwnerPhysicalTypeExpressionRecord.producerType(
            typePath = abstractStorageSupertypeOwner.physicalOwnerPath,
            category = DotNetGenericOwnerPhysicalNamedTypeCategory.CLASS,
            arguments = listOf(DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(0)),
        )),
    )
    val nullableDerivedBaseEdge = nullableDerivedOwner.directSupertypes.single { supertype ->
        supertype.kind == DotNetGenericOwnerDirectSupertypeKind.BASE_CLASS
    }
    val nullableDerivedInterfaceEdge = nullableDerivedOwner.directSupertypes.single { supertype ->
        supertype.kind == DotNetGenericOwnerDirectSupertypeKind.INTERFACE
    }
    check(nullableMarkerInterface.genericArity == 1 &&
            nullableMarkerInterface.physicalGenericParameters == listOf(
                DotNetGenericOwnerPhysicalGenericParameterRecord(0, emptySet(), emptyList()),
            ) && nullableDerivedBaseEdge.logicalClassifierKey == nullableBaseOwner.logicalOwnerKey &&
            nullableDerivedBaseEdge.physicalType == expectedNullableBaseType &&
            nullableDerivedInterfaceEdge.logicalClassifierKey == nullableMarkerInterface.logicalInterfaceKey &&
            nullableDerivedInterfaceEdge.physicalType == expectedNullableInterfaceType &&
            !nullableDerivedInterfaceEdge.isSemanticCapability &&
            nullableDerivedBaseEdge.nullableReferenceFlags == expectedNestedNullableFlags &&
            nullableDerivedInterfaceEdge.nullableReferenceFlags == expectedNestedNullableFlags &&
            nullableDerivedOwner.constructors.filter { constructor ->
                constructor.delegation.kind == DotNetGenericOwnerConstructorDelegationKind.BASE
            }.all { constructor ->
                constructor.delegation.physicalOwnerType == nullableDerivedBaseEdge.physicalType
            }) {
        "The ordinary nullable owner lost its exact BaseType/InterfaceImpl graph: $nullableDerivedOwner"
    }
    check(listOf(nullableBaseOwner, nullableDerivedOwner).all { owner ->
        owner.physicalCapabilityOwnerPath == null &&
                owner.directSupertypes.none { supertype -> supertype.isSemanticCapability }
    }) {
        "A method-free nullable owner acquired a synthetic semantic capability interface"
    }
    expectRejected("an owner without a physical BaseType row") {
        nullableDerivedOwner.copy(directSupertypes = nullableDerivedOwner.directSupertypes.filterNot { supertype ->
            supertype.kind == DotNetGenericOwnerDirectSupertypeKind.BASE_CLASS
        })
    }
    expectRejected("a constructor delegation which differs from its physical BaseType row") {
        nullableDerivedOwner.copy(constructors = nullableDerivedOwner.constructors.map { constructor ->
            if (constructor.delegation.kind != DotNetGenericOwnerConstructorDelegationKind.BASE) {
                constructor
            } else {
                constructor.copy(delegation = constructor.delegation.copy(
                    physicalOwnerType = DotNetGenericOwnerPhysicalTypeExpressionRecord.objectType(),
                ))
            }
        })
    }
    expectRejected("an ancestry root marked non-null instead of using the CLR metadata sentinel") {
        nullableDerivedBaseEdge.copy(nullableReferenceFlags = listOf(
            DotNetNullableReferenceFlag.NON_NULL,
            DotNetNullableReferenceFlag.NULLABLE,
            DotNetNullableReferenceFlag.NON_NULL,
        ))
    }
    expectRejected("a generic interface TypeDef omitted from the producer catalog") {
        artifact.copy(interfaceTypes = artifact.interfaceTypes - nullableMarkerInterface)
    }
    expectRejected("a generic interface TypeDef colliding with a class TypeDef") {
        artifact.copy(interfaceTypes = artifact.interfaceTypes.map { type ->
            if (type != nullableMarkerInterface) type else type.copy(
                physicalTypePath = nullableBaseOwner.physicalOwnerPath,
            )
        })
    }
    val directCapabilityOwners = decoded.owners.filter { owner ->
        owner.members.flatMap { member -> member.slots }.any { slot ->
            slot.role == DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER &&
                    slot.physicalOwnerPath == owner.physicalOwnerPath
        }
    }
    check(directCapabilityOwners.isNotEmpty() && decoded.owners.all { owner ->
        owner.directSupertypes.count { supertype -> supertype.isSemanticCapability } ==
                if (owner in directCapabilityOwners) 1 else 0
    }) {
        "The producer duplicated or omitted a direct semantic capability InterfaceImpl"
    }
    val directCapabilityOwner = directCapabilityOwners.single { owner ->
        owner.physicalOwnerPath.last() == "HostileUnsafeStore"
    }
    val directCapabilityEdge = directCapabilityOwner.directSupertypes.single { supertype ->
        supertype.isSemanticCapability
    }
    expectRejected("a dispatcher-owning TypeDef without its direct capability InterfaceImpl") {
        directCapabilityOwner.copy(
            directSupertypes = directCapabilityOwner.directSupertypes - directCapabilityEdge,
        )
    }
    val inheritedCapabilityOwner = decoded.owners.single { owner ->
        owner.physicalOwnerPath.last() == "HostileUnsafeMid"
    }
    check(inheritedCapabilityOwner.physicalCapabilityOwnerPath == directCapabilityEdge.physicalType.typePath &&
            inheritedCapabilityOwner.directSupertypes.none { supertype -> supertype.isSemanticCapability }) {
        "The hostile inherited owner did not retain capability ancestry without a duplicate InterfaceImpl"
    }
    expectRejected("a duplicate direct capability InterfaceImpl on an inherited owner") {
        inheritedCapabilityOwner.copy(
            directSupertypes = inheritedCapabilityOwner.directSupertypes + directCapabilityEdge,
        )
    }
    expectRejected("a method parameter in a TypeDef GenericParam constraint") {
        DotNetGenericOwnerPhysicalGenericParameterRecord(
            index = 0,
            specialConstraints = emptySet(),
