    expectRejected("a dispatcher without an exact capability slot") {
        dispatcher.copy(capabilitySlot = null)
    }
    expectRejected("a capability slot with a different physical signature") {
        dispatcher.copy(
            capabilitySlot = checkNotNull(dispatcher.capabilitySlot).copy(
                signature = dispatcher.signature.copy(parameterSlots = emptyList()),
            )
        )
    }
    val directSuperMember = artifact.owners.flatMap { owner -> owner.members }
        .first { candidate -> candidate.directSuperTargets.isNotEmpty() }
    expectRejected("a direct-super target with a different physical signature") {
        directSuperMember.copy(
            directSuperTargets = directSuperMember.directSuperTargets.mapIndexed { index, target ->
                if (index != 0) target else target.copy(
                    signature = target.signature.copy(parameterSlots = emptyList()),
                )
            }
        )
    }
    expectRejected("two logical members with one colliding physical MethodDef") {
        val collisionOwner = artifact.owners.first { owner ->
            owner.members.count { candidate ->
                candidate.roles == setOf(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY) &&
                        candidate.directSuperTargets.isEmpty()
            } >= 2
        }
        val candidates = collisionOwner.members.filter { candidate ->
            candidate.roles == setOf(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY) &&
                    candidate.directSuperTargets.isEmpty()
        }.take(2)
        val first = candidates.first().slots.single()
        val second = candidates.last()
        collisionOwner.copy(members = collisionOwner.members.map { candidate ->
            if (candidate != second) candidate else candidate.copy(
                slots = listOf(second.slots.single().copy(
                    physicalOwnerPath = first.physicalOwnerPath,
                    physicalMethodName = first.physicalMethodName,
                    signature = first.signature,
                ))
            )
        })
    }
    expectRejected("an out-of-range owner type parameter") {
        val relayOwner = artifact.owners.first { owner -> owner.members.any { candidate ->
            candidate.slots.any { slot -> slot.signature.genericArity == 1 }
        } }
        val relay = relayOwner.members.single { candidate ->
            candidate.slots.any { slot -> slot.signature.genericArity == 1 }
        }
        relayOwner.copy(
            members = relayOwner.members.map { candidate ->
                if (candidate != relay) candidate else candidate.copy(
                    slots = candidate.slots.map { slot ->
                        if (slot.role != DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY) slot else slot.copy(
                            signature = slot.signature.copy(
                                parameterSlots = listOf(
                                    DotNetGenericOwnerPhysicalValueSlotRecord(
                                        DotNetGenericOwnerPhysicalSlotDomain.STRICT_OWNER_INPUT,
                                        DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(
                                            relayOwner.genericArity
                                        ),
                                    )
                                )
                            )
                        )
                    }
                )
            }
        )
    }
    expectRejected("void as a named generic argument") {
        DotNetGenericOwnerPhysicalTypeExpressionRecord.coreType(
            typePath = listOf("System", "Collections", "Generic", "List"),
            category = DotNetGenericOwnerPhysicalNamedTypeCategory.CLASS,
            arguments = listOf(DotNetGenericOwnerPhysicalTypeExpressionRecord.voidType()),
        )
    }
    val stateOwner = artifact.owners.first { owner -> owner.states.isNotEmpty() }
    val state = stateOwner.states.single()
    val typedWriteAccess = state.accessPaths.single { access ->
        access.domain == DotNetGenericOwnerPhysicalStateAccessDomain.TYPED &&
                access.operation == DotNetGenericOwnerPhysicalStateAccessOperation.WRITE
    }
    expectRejected("an unpaired semantic-object state access") {
        state.copy(accessPaths = state.accessPaths - typedWriteAccess)
    }
    expectRejected("an identity conversion between typed input and semantic storage") {
        state.copy(accessPaths = state.accessPaths.map { access ->
            if (access != typedWriteAccess) access else access.copy(
                conversion = DotNetGenericOwnerPhysicalStateAccessConversion.IDENTITY,
            )
        })
    }
    expectRejected("a state access bound to an unrecorded MethodDef") {
        stateOwner.copy(states = listOf(state.copy(accessPaths = state.accessPaths.map { access ->
            if (access != typedWriteAccess) access else access.copy(
                physicalMethod = access.physicalMethod.copy(physicalMethodName = "WrongWrite"),
            )
        })))
    }
    val semanticReadAccess = state.accessPaths.single { access ->
        access.domain == DotNetGenericOwnerPhysicalStateAccessDomain.SEMANTIC &&
                access.operation == DotNetGenericOwnerPhysicalStateAccessOperation.READ
    }
    val semanticWriteAccess = state.accessPaths.single { access ->
        access.domain == DotNetGenericOwnerPhysicalStateAccessDomain.SEMANTIC &&
                access.operation == DotNetGenericOwnerPhysicalStateAccessOperation.WRITE
    }
    fun producerPrivateAccess(
        source: DotNetGenericOwnerPhysicalStateAccessRecord,
        physicalMethodName: String,
    ): DotNetGenericOwnerPhysicalStateAccessRecord = source.copy(
        domain = DotNetGenericOwnerPhysicalStateAccessDomain.TYPED,
        conversion = DotNetGenericOwnerPhysicalStateAccessConversion.IDENTITY,
        bindingKind = DotNetGenericOwnerPhysicalStateAccessBindingKind.PRODUCER_PRIVATE_METHOD,
        logicalMemberKey = null,
        role = null,
        physicalVisibility = DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE,
        physicalMethod = source.physicalMethod.copy(
            physicalOwnerPath = stateOwner.physicalOwnerPath,
            physicalMethodName = physicalMethodName,
        ),
    )
    val privateReadAccess = producerPrivateAccess(semanticReadAccess, "__kotlin_private_state_read")
    val privateWriteAccess = producerPrivateAccess(semanticWriteAccess, "__kotlin_private_state_write")
    val producerPrivateState = state.copy(accessPaths = listOf(privateReadAccess, privateWriteAccess))
    val producerPrivateOwner = stateOwner.copy(states = listOf(producerPrivateState))
    val producerPrivateArtifact = artifact.copy(
        owners = artifact.owners.map { owner -> if (owner == stateOwner) producerPrivateOwner else owner },
    )
    val encodedProducerPrivateArtifact = DotNetGenericOwnerPhysicalFamilyCodec.encode(producerPrivateArtifact)
    val decodedProducerPrivateArtifact = DotNetGenericOwnerPhysicalFamilyCodec.decode(
        encodedProducerPrivateArtifact,
        expectedProducerFingerprint = artifact.producerFingerprint,
        expectedTargetProfile = artifact.targetProfile,
    )
    val decodedProducerPrivateOwner = decodedProducerPrivateArtifact.requirePhysicalFamily(
        producerPrivateOwner.logicalOwnerKey,
    )
    check(DotNetGenericOwnerPhysicalFamilyCodec.encode(decodedProducerPrivateArtifact) ==
            encodedProducerPrivateArtifact &&
            decodedProducerPrivateOwner.states.single().accessPaths.toSet() ==
            producerPrivateState.accessPaths.toSet() &&
            decodedProducerPrivateOwner.reflection.callables.none { callable ->
                callable.physicalMethods.any { method ->
                    method == privateReadAccess.physicalMethod || method == privateWriteAccess.physicalMethod
                }
            }) {
        "The generic-owner family codec did not preserve hidden producer-private state access"
    }
    expectRejected("a producer-private access carrying a logical ABI key") {
        privateReadAccess.copy(logicalMemberKey = semanticReadAccess.logicalMemberKey)
    }
    expectRejected("a non-private producer-owned state accessor") {
        privateReadAccess.copy(physicalVisibility = DotNetGenericOwnerPhysicalMemberVisibility.ASSEMBLY)
    }
    expectRejected("a semantic producer-private state accessor") {
        privateReadAccess.copy(domain = DotNetGenericOwnerPhysicalStateAccessDomain.SEMANTIC)
    }
    expectRejected("a producer-private state accessor on another TypeDef") {
        producerPrivateOwner.copy(states = listOf(producerPrivateState.copy(
            accessPaths = producerPrivateState.accessPaths.map { access ->
                if (access != privateReadAccess) access else access.copy(
                    physicalMethod = access.physicalMethod.copy(
                        physicalOwnerPath = access.physicalMethod.physicalOwnerPath + "Foreign",
                    ),
                )
            },
        )))
    }
    expectRejected("a producer-private accessor colliding with a logical member MethodDef") {
        producerPrivateOwner.copy(states = listOf(producerPrivateState.copy(
            accessPaths = producerPrivateState.accessPaths.map { access ->
                if (access != privateWriteAccess) access else access.copy(
                    physicalMethod = semanticWriteAccess.physicalMethod,
                )
            },
        )))
    }
    expectRejected("an out-of-range owner type parameter in state storage") {
        stateOwner.copy(
            states = stateOwner.states.mapIndexed { index, state ->
                if (index != 0) state else state.copy(
                    physicalType = DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(stateOwner.genericArity),
                )
            }
        )
    }
    val typedStateOwner = artifact.owners.single { owner ->
        owner.states.any { state ->
            state.requirement ==
                    DotNetGenericOwnerStateCarrierRequirement.TYPED_STORAGE_PRODUCER_GRAPH_PROVEN
        }
    }
    val typedState = typedStateOwner.states.single { state ->
        state.requirement == DotNetGenericOwnerStateCarrierRequirement.TYPED_STORAGE_PRODUCER_GRAPH_PROVEN
    }
    val volatileState = typedStateOwner.states.single { state ->
        state.requirement == DotNetGenericOwnerStateCarrierRequirement.VOLATILE_OBJECT_STORAGE_REQUIRED
    }
    check(typedStateOwner.physicalOwnerPath.last() == "HostileTypedStore" &&
            typedStateOwner.physicalCapabilityOwnerPath?.last() == "IHostileTypedStoreSemantic" &&
            typedState.physicalType == DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(0) &&
            typedState.accessPaths.map { access -> access.domain }.toSet() ==
            setOf(DotNetGenericOwnerPhysicalStateAccessDomain.TYPED) &&
            typedState.accessPaths.map { access -> access.operation }.toSet() ==
            DotNetGenericOwnerPhysicalStateAccessOperation.entries.toSet() &&
            typedState.accessPaths.all { access ->
                access.conversion == DotNetGenericOwnerPhysicalStateAccessConversion.IDENTITY
            } && typedState.initializers.singleOrNull()?.conversion ==
            DotNetGenericOwnerPhysicalStateAccessConversion.IDENTITY) {
        "The generic-owner artifact did not retain its compiler-proven !T state family: $typedStateOwner"
    }
    check(volatileState.memorySemantics == DotNetGenericOwnerStateMemorySemantics.VOLATILE &&
            volatileState.physicalType == DotNetGenericOwnerPhysicalTypeExpressionRecord.objectType() &&
            volatileState.accessPaths.map { access -> access.operation }.toSet() ==
            DotNetGenericOwnerPhysicalStateAccessOperation.entries.toSet() &&
            volatileState.accessPaths.all { access ->
                access.domain == DotNetGenericOwnerPhysicalStateAccessDomain.TYPED &&
                        access.conversion == when (access.operation) {
                    DotNetGenericOwnerPhysicalStateAccessOperation.READ ->
                        DotNetGenericOwnerPhysicalStateAccessConversion.STATE_TO_OUTPUT_CHECKED_CAST_OR_UNBOX
                    DotNetGenericOwnerPhysicalStateAccessOperation.WRITE ->
                        DotNetGenericOwnerPhysicalStateAccessConversion.INPUT_TO_STATE_BOX_OR_REFERENCE_WIDEN
                }
            } && volatileState.initializers.singleOrNull()?.conversion ==
            DotNetGenericOwnerPhysicalStateAccessConversion.INPUT_TO_STATE_BOX_OR_REFERENCE_WIDEN) {
        "The generic-owner artifact lost its bounded volatile object-state family: $volatileState"
    }
    expectRejected("typed storage for owner-dependent volatile state") {
        volatileState.copy(
            requirement = DotNetGenericOwnerStateCarrierRequirement.TYPED_STORAGE_PRODUCER_GRAPH_PROVEN,
            physicalType = DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(0),
        )
    }
    expectRejected("plain access semantics for volatile object state") {
        volatileState.copy(memorySemantics = DotNetGenericOwnerStateMemorySemantics.PLAIN)
    }
    expectRejected("identity constructor input for volatile object state") {
        volatileState.copy(initializers = volatileState.initializers.map { initializer ->
            initializer.copy(conversion = DotNetGenericOwnerPhysicalStateAccessConversion.IDENTITY)
        })
    }
    expectRejected("widening constructor input for typed state") {
        typedState.copy(initializers = typedState.initializers.map { initializer ->
            initializer.copy(
                conversion = DotNetGenericOwnerPhysicalStateAccessConversion.INPUT_TO_STATE_BOX_OR_REFERENCE_WIDEN,
            )
        })
    }
    expectRejected("object storage for compiler-proven typed state") {
        typedState.copy(physicalType = DotNetGenericOwnerPhysicalTypeExpressionRecord.objectType())
    }
    expectRejected("an incomplete nullable-reference transform for typed state") {
        typedState.copy(nullableReferenceFlags = emptyList())
    }
    val typedStateReadAccess = typedState.accessPaths.single { access ->
        access.operation == DotNetGenericOwnerPhysicalStateAccessOperation.READ
    }
    val typedVectorType = DotNetGenericOwnerPhysicalTypeExpressionRecord.szArray(
        DotNetGenericOwnerPhysicalTypeExpressionRecord.ownerParameter(0),
    )
    val typedVectorReadMethod = typedStateReadAccess.physicalMethod.copy(
        signature = typedStateReadAccess.physicalMethod.signature.copy(
            returnSlot = typedStateReadAccess.physicalMethod.signature.returnSlot.copy(
                type = typedVectorType,
                nullableReferenceFlags = listOf(
                    DotNetNullableReferenceFlag.NON_NULL,
                    DotNetNullableReferenceFlag.NON_NULL,
                ),
            ),
        ),
    )
    val typedVectorInitializer = DotNetGenericOwnerPhysicalStateInitializerRecord(
        kind = DotNetGenericOwnerPhysicalStateInitializerKind.FIXED_ZEROED_SZ_ARRAY,
        conversion = DotNetGenericOwnerPhysicalStateAccessConversion.IDENTITY,
        logicalConstructorKeys = listOf(typedStateOwner.constructors.single().logicalConstructorKey),
        fixedElementCount = 8,
        constructorParameterIndex = null,
    )
    val initializedTypedVectorState = typedState.copy(
        physicalType = typedVectorType,
        nullableReferenceFlags = listOf(
            DotNetNullableReferenceFlag.NON_NULL,
            DotNetNullableReferenceFlag.NON_NULL,
        ),
        initializers = listOf(typedVectorInitializer),
        accessPaths = listOf(typedStateReadAccess.copy(physicalMethod = typedVectorReadMethod)),
    )
    val initializedTypedVectorOwner = typedStateOwner.copy(
        members = typedStateOwner.members.map { member ->
            if (member.logicalMemberKey != typedStateReadAccess.logicalMemberKey) member else member.copy(
                slots = member.slots.map { slot ->
                    if (slot.role != typedStateReadAccess.role) slot else slot.copy(
                        signature = typedVectorReadMethod.signature,
                    )
                },
            )
        },
        reflection = typedStateOwner.reflection.copy(
            callables = typedStateOwner.reflection.callables.map { callable ->
                if (callable.logicalMemberKey != typedStateReadAccess.logicalMemberKey) callable else callable.copy(
                    invocationMethod = typedVectorReadMethod,
                    physicalMethods = callable.physicalMethods.map { method ->
                        if (method != typedStateReadAccess.physicalMethod) method else typedVectorReadMethod
                    },
                )
            },
        ),
        states = listOf(initializedTypedVectorState, volatileState),
    )
    val initializedTypedVectorArtifact = artifact.copy(
        owners = artifact.owners.map { owner ->
            if (owner != typedStateOwner) owner else initializedTypedVectorOwner
        },
    )
    val initializedTypedVectorEncoded = DotNetGenericOwnerPhysicalFamilyCodec.encode(
        initializedTypedVectorArtifact,
    )
    val initializedTypedVectorDecoded = DotNetGenericOwnerPhysicalFamilyCodec.decode(
        initializedTypedVectorEncoded,
        artifact.producerFingerprint,
        artifact.targetProfile,
    )
    check(DotNetGenericOwnerPhysicalFamilyCodec.encode(initializedTypedVectorDecoded) ==
            initializedTypedVectorEncoded &&
            initializedTypedVectorDecoded.requirePhysicalFamily(typedStateOwner.logicalOwnerKey)
                .states.single { state -> state.logicalFieldName == initializedTypedVectorState.logicalFieldName }
                .initializers.single() == typedVectorInitializer) {
        "The schema-20 physical family lost its constructor-rooted typed vector initializer"
    }
    expectRejected("a typed vector initializer without an exact read path") {
        initializedTypedVectorState.copy(accessPaths = emptyList())
    }
    expectRejected("two physical initializer recipes for one state") {
        initializedTypedVectorState.copy(initializers = listOf(typedVectorInitializer, typedVectorInitializer))
    }
    expectRejected("a typed initializer on non-vector storage") {
        typedState.copy(initializers = listOf(typedVectorInitializer))
    }
    expectRejected("a physical initializer with a missing constructor root") {
        initializedTypedVectorOwner.copy(
            states = listOf(initializedTypedVectorState.copy(
                initializers = listOf(typedVectorInitializer.copy(
                    logicalConstructorKeys = listOf("missing-constructor-root"),
                )),
            )),
        )
    }
    expectRejected("a negative fixed vector initializer length") {
        typedVectorInitializer.copy(fixedElementCount = -1)
    }
    expectRejected("a fixed vector initializer carrying a constructor parameter") {
        typedVectorInitializer.copy(constructorParameterIndex = 0)
    }
    val echo = artifact.owners.first().members.single { candidate ->
        candidate.roles == setOf(
            DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
            DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK,
            DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
        ) && candidate.slots.all { slot ->
            slot.signature.returnSlot.domain == DotNetGenericOwnerPhysicalSlotDomain.STRICT_OWNER_OUTPUT &&
                    slot.signature.parameterSlots.singleOrNull()?.domain ==
                    DotNetGenericOwnerPhysicalSlotDomain.BROAD_CANDIDATE_INPUT
        }
    }
    check(echo.slots.all { slot ->
        slot.signature.returnSlot.type.scope == DotNetGenericOwnerPhysicalTypeScope.CORE_LIBRARY &&
                slot.signature.returnSlot.type.typePath == listOf("System", "Array") &&
                slot.signature.parameterSlots.single().type.scope ==
                DotNetGenericOwnerPhysicalTypeScope.CORE_LIBRARY &&
                slot.signature.parameterSlots.single().type.typePath == listOf("System", "Array")
    }) {
        "The generic-owner artifact did not retain its projected System.Array carriers"
    }
    val relayFamily = artifact.owners.first().members.single { candidate ->
        candidate.slots.any { slot -> slot.signature.genericArity == 1 }
    }
    val relay = relayFamily.slots.single { slot ->
        slot.role == DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY
    }
    val relayCapability = relayFamily.slots.single { slot ->
        slot.role == DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER
    }
    check(relay.signature.genericArity == 1 &&
            relayCapability.signature == relay.signature &&
            relay.signature.returnSlot.type.arguments.single().kind ==
            DotNetGenericOwnerPhysicalTypeKind.METHOD_TYPE_PARAMETER &&
            relay.signature.returnSlot.type.arguments.single().parameterIndex == 0) {
        "The generic-owner artifact did not retain its nested method-generic array carrier"
    }
    check(artifact.owners.flatMap { owner -> owner.members }.mapNotNull { candidate ->
        candidate.defaultDispatcher
    }.singleOrNull()?.let { dispatcherRecord ->
        dispatcherRecord.signature.parameterSlots.first().type.arguments.singleOrNull()?.kind ==
                DotNetGenericOwnerPhysicalTypeKind.OWNER_TYPE_PARAMETER
    } == true) {
        "The generic-owner artifact lacks the selected physical default dispatcher"
    }
}

/**
 * Test-owned physicalization of the compiler snapshot. This deliberately does not reuse the
 * production emitter: it turns the recorded role/state decisions into a temporary CLR-generic
 * producer, then proves that a separately compiled C# subclass observes those decisions.
 */
private fun copyGenericOwnerErasedArtifact(source: File, destination: File) {
    check(source.isFile) { "The generic-owner application corpus lacks erased output: ${source.path}" }
    check(!destination.exists()) {
        "The generic-owner application corpus attempted to overwrite erased output: ${destination.path}"
    }
    source.copyTo(destination)
}

private fun physicalizeGenericOwnerHardestModelPrototype(
    prototypes: List<DotNetGenericOwnerPrototypeSnapshot>,
    callRoutes: List<DotNetGenericOwnerCallRouteSnapshot>,
    target: DotNetTarget,
    erasedOutput: File,
    applicationSource: File,
    directory: File,
) {
    fun DotNetGenericOwnerPrototypeSnapshot.hasSimpleName(name: String): Boolean =
        ownerName == name || ownerName.endsWith(".$name")

    directory.mkdirs()
    prototypes.singleOrNull { prototype -> prototype.hasSimpleName("ConsumerUnsafeLeaf") }?.let { consumer ->
        copyGenericOwnerErasedArtifact(
            erasedOutput,
            directory.resolve(genericOwnerErasedConsumerFile(target)),
        )
        consumeGenericOwnerPhysicalFamilyArtifact(consumer, callRoutes, target, directory)
        return
    }
    if (prototypes.none { prototype -> prototype.hasSimpleName("HostileUnsafeProducer") }) return
    copyGenericOwnerErasedArtifact(
        applicationSource,
        directory.resolve(GENERIC_OWNER_APPLICATION_SOURCE_FILE),
    )
    copyGenericOwnerErasedArtifact(
        erasedOutput,
        directory.resolve(GENERIC_OWNER_ERASED_PRODUCER_FILE),
    )
    val membersByLogicalKey = prototypes.flatMap { prototype -> prototype.members }
        .mapNotNull { member -> member.logicalBindingKey?.let { logicalKey -> logicalKey to member } }
        .toMap()
    fun overrideRoots(
        member: DotNetGenericOwnerPrototypeMemberSnapshot,
        visiting: Set<String> = emptySet(),
    ): List<String> {
        val declaringPrototype = prototypes.single { prototype ->
            prototype.members.any { candidate -> candidate === member }
        }
        val memberKey = member.logicalBindingKey
            ?: "private:${declaringPrototype.ownerName}:${member.sourceIndex}:${member.physicalBaseName}"
        check(memberKey !in visiting) {
            "Generic-owner physicalizer override-family roots contain a cycle at '$memberKey'"
        }
        val overriddenMembers = member.overrideBindings.mapNotNull { binding ->
            binding.overriddenLogicalBindingKey?.let(membersByLogicalKey::get)
                ?: prototypes.singleOrNull { prototype ->
                    prototype.ownerName == binding.overriddenOwnerName
                }?.members?.singleOrNull { overridden ->
                    overridden.sourceName == binding.overriddenSourceName &&
                            overridden.propertyAccessorKind == member.propertyAccessorKind
                }
        }
        return if (overriddenMembers.isEmpty()) {
            listOf(memberKey)
        } else {
            overriddenMembers.flatMap { overridden ->
                overrideRoots(overridden, visiting + memberKey)
            }.distinct().sorted()
        }
    }
    val owner = prototypes.single { prototype -> prototype.hasSimpleName("HostileUnsafeStore") }
    val write = owner.members.single { member -> member.sourceName == "writeUnsafe" }
    val read = owner.members.single { member -> member.sourceName == "read" }
    val exposedGetter = owner.members.single { member ->
        member.physicalPropertyName == "exposed" &&
                member.propertyAccessorKind == DotNetGenericOwnerPropertyAccessorKind.GETTER
    }
    val exposedSetter = owner.members.single { member ->
        member.physicalPropertyName == "exposed" &&
                member.propertyAccessorKind == DotNetGenericOwnerPropertyAccessorKind.SETTER
    }
    val echo = owner.members.single { member -> member.sourceName == "echo" }
    val relay = owner.members.single { member -> member.sourceName == "relay" }
    val label = owner.members.single { member -> member.sourceName == "label" }
    val state = owner.states.single()
    val abstractPropertyOwner = prototypes.single { prototype ->
        prototype.hasSimpleName("HostileAbstractProperty")
    }
    val abstractPropertyGetter = abstractPropertyOwner.members.single { member ->
        member.physicalPropertyName == "exposed" &&
                member.propertyAccessorKind == DotNetGenericOwnerPropertyAccessorKind.GETTER
    }
    val abstractPropertySetter = abstractPropertyOwner.members.single { member ->
        member.physicalPropertyName == "exposed" &&
                member.propertyAccessorKind == DotNetGenericOwnerPropertyAccessorKind.SETTER
    }
    val abstractPropertyStorageOwner = prototypes.single { prototype ->
        prototype.hasSimpleName("HostileAbstractPropertyStorage")
    }
    val abstractPropertyStorageState = abstractPropertyStorageOwner.states.single()
    val abstractStorageGetter = abstractPropertyStorageOwner.members.single { member ->
        member.physicalPropertyName == "exposed" &&
                member.propertyAccessorKind == DotNetGenericOwnerPropertyAccessorKind.GETTER
    }
    val abstractStorageSetter = abstractPropertyStorageOwner.members.single { member ->
        member.physicalPropertyName == "exposed" &&
                member.propertyAccessorKind == DotNetGenericOwnerPropertyAccessorKind.SETTER
    }
    val typedStorageOwner = prototypes.single { prototype -> prototype.hasSimpleName("HostileTypedStore") }
    val typedStorageState = typedStorageOwner.states.single { state -> state.fieldName == "stored" }
    val volatileStorageState = typedStorageOwner.states.single { state -> state.fieldName == "published" }
    val typedStorageWrite = typedStorageOwner.members.single { member -> member.sourceName == "write" }
    val typedStorageRead = typedStorageOwner.members.single { member -> member.sourceName == "read" }
    val volatileStorageWrite = typedStorageOwner.members.single { member -> member.sourceName == "publish" }
    val volatileStorageRead = typedStorageOwner.members.single { member -> member.sourceName == "observe" }
    val collisionMembers = owner.members.filter { member -> member.sourceName == "collide" }
    fun collisionParameterClassifierKey(
        member: DotNetGenericOwnerPrototypeMemberSnapshot,
    ): String? = member.exactPathUnboundSignatures
        ?.get(DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY)
        ?.parameterSlots
        ?.singleOrNull()
        ?.type
        ?.logicalClassifierKey
    val orderedCollisionMembers = collisionMembers.sortedBy { member -> member.sourceIndex }
    val typedStoreCollision = collisionMembers.singleOrNull { member ->
        collisionParameterClassifierKey(member) == typedStorageOwner.logicalBindingKey
    } ?: orderedCollisionMembers.first()
    val abstractStorageCollision = collisionMembers.singleOrNull { member ->
        collisionParameterClassifierKey(member) == abstractPropertyStorageOwner.logicalBindingKey
    } ?: orderedCollisionMembers.last()
    check(orderedCollisionMembers.size == 2 && typedStoreCollision != abstractStorageCollision) {
        "The hostile overload physicalizer could not distinguish both source families: $collisionMembers"
    }
    fun hasRole(
        member: DotNetGenericOwnerPrototypeMemberSnapshot,
        role: DotNetGenericOwnerMemberFamilyRole,
    ): Boolean = role in member.roles
    fun physicalName(
        member: DotNetGenericOwnerPrototypeMemberSnapshot,
        role: DotNetGenericOwnerMemberFamilyRole,
    ): String = genericOwnerPrototypePhysicalMethodName(member, role, overrideRoots(member))
    val writeTypedName = physicalName(write, DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY)
    val writeSemanticName = physicalName(write, DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK)
    val writeCapabilityName = physicalName(write, DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER)
    val readTypedName = physicalName(read, DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY)
    val readSemanticName = physicalName(read, DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK)
    val readCapabilityName = physicalName(read, DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER)
    val exposedPropertyName = checkNotNull(exposedGetter.physicalPropertyName)
    val exposedGetterTypedName = physicalName(
        exposedGetter,
        DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
    )
    val exposedSetterTypedName = physicalName(
        exposedSetter,
        DotNetGenericOwnerMemberFamilyRole.TYPED_ENTRY,
    )
    val exposedGetterSemanticName = physicalName(
        exposedGetter,
        DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK,
    )
    val exposedGetterCapabilityName = physicalName(
        exposedGetter,
        DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
    )
    val exposedSetterSemanticName = physicalName(
        exposedSetter,
        DotNetGenericOwnerMemberFamilyRole.SEMANTIC_HOOK,
    )
    val exposedSetterCapabilityName = physicalName(
        exposedSetter,
        DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
    )
    val abstractPropertyName = checkNotNull(abstractPropertyGetter.physicalPropertyName)
    val abstractGetterTypedName = physicalName(
        abstractPropertyGetter,
