                [System.Runtime.CompilerServices.MethodImpl(
                    System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
                private static int ExecuteExactValueConstruction(int iterations)
                {
                    int checksum = 17;
                    for (int index = 0; index < iterations; index++)
                    {
                        int next = index & 1023;
                        ErasedStore owner = new ErasedStore(null);
                        owner.writeUnsafe(next);
                        int observed = (int)owner.read();
                        if (observed != next)
                            throw new InvalidOperationException("exact value construction");
                        checksum = MixRouteChecksum(checksum, observed);
                    }
                    return checksum;
                }

                [System.Runtime.CompilerServices.MethodImpl(
                    System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
                private static int ExecuteTypedArray(int iterations)
                {
                    int checksum = 17;
                    ErasedStore owner = new ErasedStore(0);
                    int[] values = new int[] { 0, 2, 3 };
                    for (int index = 0; index < iterations; index++)
                    {
                        values[0] = index & 1023;
                        int[] observed = (int[])owner.echo(values);
                        if (!object.ReferenceEquals(observed, values))
                            throw new InvalidOperationException("typed array identity");
                        checksum = MixRouteChecksum(checksum, observed[0]);
                    }
                    return checksum;
                }

                [System.Runtime.CompilerServices.MethodImpl(
                    System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
                private static int ExecuteSemanticArray(int iterations)
                {
                    int checksum = 17;
                    ErasedStore owner = new ErasedStore(0);
                    string[] values = new string[] { "a", "array" };
                    for (int index = 0; index < iterations; index++)
                    {
                        values[0] = (index & 1) == 0 ? "a" : "bb";
                        Array observed = owner.echo(values);
                        if (!object.ReferenceEquals(observed, values))
                            throw new InvalidOperationException("semantic array identity");
                        checksum = MixRouteChecksum(checksum, ((string[])observed)[0].Length);
                    }
                    return checksum;
                }

                [System.Runtime.CompilerServices.MethodImpl(
                    System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
                private static int ExecuteMethodGenericArray(int iterations)
                {
                    int checksum = 17;
                    ErasedStore owner = new ErasedStore(0);
                    ApplicationKnownStruct[] values =
                        new ApplicationKnownStruct[] { new ApplicationKnownStruct { Value = 0 } };
                    for (int index = 0; index < iterations; index++)
                    {
                        values[0].Value = index & 1023;
                        ApplicationKnownStruct[] observed =
                            owner.relay<ApplicationKnownStruct>(values);
                        if (!object.ReferenceEquals(observed, values))
                            throw new InvalidOperationException("method generic array identity");
                        checksum = MixRouteChecksum(checksum, observed[0].Value);
                    }
                    return checksum;
                }

                [System.Runtime.CompilerServices.MethodImpl(
                    System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
                private static int ExecuteCompatibleOverrideObjectState(int iterations)
                {
                    int checksum = 17;
                    ErasedRouteGrandchild owner = new ErasedRouteGrandchild(0);
                    for (int index = 0; index < iterations; index++)
                    {
                        int next = index & 1023;
                        owner.writeUnsafe(next);
                        int observed = (int)owner.read();
                        if (observed != next)
                            throw new InvalidOperationException("compatible override object state");
                        checksum = MixRouteChecksum(checksum, observed);
                    }
                    return checksum;
                }

                [System.Runtime.CompilerServices.MethodImpl(
                    System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
                private static int ExecuteHostileOverrideState(int iterations)
                {
                    int checksum = 17;
                    ErasedRouteGrandchild owner = new ErasedRouteGrandchild(0);
                    for (int index = 0; index < iterations; index++)
                    {
                        string next = (index & 1) == 0 ? "wrong" : "other";
                        owner.writeUnsafe(next);
                        string observed = (string)owner.read();
                        if (observed != "grandchild:" + next)
                            throw new InvalidOperationException("hostile semantic override state");
                        try
                        {
                            int invalid = (int)owner.read();
                            throw new InvalidOperationException(
                                "hostile typed read did not fail: " + invalid);
                        }
                        catch (InvalidCastException)
                        {
                            checksum = MixRouteChecksum(checksum, observed.Length + 7);
                        }
                    }
                    return checksum;
                }

                private static int ExecuteRouteMeasurementWorkload(string route, int iterations)
                {
                    switch (route)
                    {
                        case "typed-entry-typed-state": return ExecuteTypedEntryTypedState(iterations);
                        case "capability-value-typed-state": return ExecuteCapabilityValueTypedState(iterations);
                        case "typed-entry-struct-typed-state":
                            return ExecuteTypedEntryStructTypedState(iterations);
                        case "capability-struct-typed-state":
                            return ExecuteCapabilityStructTypedState(iterations);
                        case "typed-entry-nullable-typed-state":
                            return ExecuteTypedEntryNullableTypedState(iterations);
                        case "capability-nullable-typed-state":
                            return ExecuteCapabilityNullableTypedState(iterations);
                        case "typed-entry-object-state": return ExecuteTypedEntryObjectState(iterations);
                        case "capability-value-state": return ExecuteCapabilityValueState(iterations);
                        case "capability-reference-state": return ExecuteCapabilityReferenceState(iterations);
                        case "fallback-struct-state": return ExecuteFallbackStructState(iterations);
                        case "exact-value-construction": return ExecuteExactValueConstruction(iterations);
                        case "typed-array": return ExecuteTypedArray(iterations);
                        case "semantic-array": return ExecuteSemanticArray(iterations);
                        case "method-generic-array": return ExecuteMethodGenericArray(iterations);
                        case "compatible-override-object-state":
                            return ExecuteCompatibleOverrideObjectState(iterations);
                        case "hostile-override-state": return ExecuteHostileOverrideState(iterations);
                        default: throw new ArgumentOutOfRangeException("route", route, "unknown route");
                    }
                }

                public static int Main(string[] arguments)
                {
                    VerifyVolatileOneState();
                    bool holdForPeakWorkingSet = arguments.Length == 4 &&
                        arguments[3] == "--hold-for-peak-working-set";
                    if ((arguments.Length != 3 && !holdForPeakWorkingSet) ||
                            arguments[0] != "--route-measurement" ||
                            !int.TryParse(arguments[2], out int iterations) || iterations < 0)
                    {
                        Console.Error.WriteLine(
                            "usage: --route-measurement <route> <non-negative iterations> " +
                            "[--hold-for-peak-working-set]");
                        return 64;
                    }
                    string route = arguments[1];
                    try
                    {
                        if (iterations > 0)
                            ExecuteRouteMeasurementWorkload(route, Math.Min(iterations, 256));
                        GC.Collect();
                        GC.WaitForPendingFinalizers();
                        GC.Collect();
                        long allocatedBefore = GC.GetAllocatedBytesForCurrentThread();
                        long started = System.Diagnostics.Stopwatch.GetTimestamp();
                        int checksum = ExecuteRouteMeasurementWorkload(route, iterations);
                        long elapsedTicks = System.Diagnostics.Stopwatch.GetTimestamp() - started;
                        long allocatedBytes =
                            GC.GetAllocatedBytesForCurrentThread() - allocatedBefore;
                        long erasedVirtualCalls = 0;
                        long ownerConstructions = route == "exact-value-construction" ? iterations : 1L;
                        long loopValueBoxOrUnboxOperations = 0;
                        long expectedFailures = 0;
                        switch (route)
                        {
                            case "typed-entry-typed-state":
                            case "capability-value-typed-state":
                            case "typed-entry-struct-typed-state":
                            case "capability-struct-typed-state":
                            case "typed-entry-nullable-typed-state":
                            case "capability-nullable-typed-state":
                            case "typed-entry-object-state":
                            case "capability-value-state":
                            case "fallback-struct-state":
                            case "exact-value-construction":
                            case "compatible-override-object-state":
                                erasedVirtualCalls = iterations * 2L;
                                loopValueBoxOrUnboxOperations = iterations * 2L;
                                break;
                            case "capability-reference-state":
                                erasedVirtualCalls = iterations * 2L;
                                break;
                            case "typed-array":
                            case "semantic-array":
                            case "method-generic-array":
                                erasedVirtualCalls = iterations;
                                break;
                            case "hostile-override-state":
                                erasedVirtualCalls = iterations * 3L;
                                loopValueBoxOrUnboxOperations = iterations;
                                expectedFailures = iterations;
                                break;
                            default: throw new ArgumentOutOfRangeException("route", route, "unknown route");
                        }
                        Console.WriteLine(
                            "GENERIC_OWNER_APPLICATION_ROUTE_MEASUREMENT|workloadVersion=1" +
                            "|representation=erased" +
                            "|route=" + route +
                            "|iterations=" + iterations +
                            "|checksum=" + checksum +
                            "|elapsedTicks=" + elapsedTicks +
                            "|frequency=" + System.Diagnostics.Stopwatch.Frequency +
                            "|allocatedBytes=" + allocatedBytes +
                            "|typedEntryCalls=0" +
                            "|semanticCapabilityCalls=0" +
                            "|erasedVirtualCalls=" + erasedVirtualCalls +
                            "|ownerStateCarrierRequirement=ERASED_OBJECT" +
                            "|ownerConstructions=" + ownerConstructions +
                            "|loopValueBoxOrUnboxOperations=" + loopValueBoxOrUnboxOperations +
                            "|runtimeCompatibilityChecks=0" +
                            "|expectedFailures=" + expectedFailures);
                    }
                    catch (ArgumentOutOfRangeException exception)
                    {
                        Console.Error.WriteLine(exception.Message);
                        return 64;
                    }
                    if (holdForPeakWorkingSet)
                    {
                        Console.Out.Flush();
                        if (Console.In.ReadLine() != "release")
                        {
                            Console.Error.WriteLine("peak-working-set hold was not released");
                            return 65;
                        }
                    }
                    return 0;
                }
                #elif GENERIC_OWNER_APPLICATION_MEASUREMENT
                private static int ExecuteApplicationMeasurementWorkload(int iterations)
                {
                    int checksum = 17;
                    int[] typedArray = new int[] { 1, 2, 3 };
                    string[] semanticArray = new string[] { "semantic", "array" };
                    ApplicationKnownStruct[] knownArray =
                        new ApplicationKnownStruct[] { new ApplicationKnownStruct { Value = 3 } };
                    Guid guid = new Guid("00112233-4455-6677-8899-aabbccddeeff");
                    DateTime date = new DateTime(638900000000000000L, DateTimeKind.Utc);
                    decimal amount = 1234567.8901m;
                    ValueTuple<int, string> tuple = new ValueTuple<int, string>(7, "tuple");
                    ErasedStore mixed = new ErasedStore(0);
                    ErasedCSharpGrandchild hostile = new ErasedCSharpGrandchild(0);

                    for (int index = 0; index < iterations; index++)
                    {
                        int next = index & 1023;
                        ErasedStore exactValue = new ErasedStore(null);
                        exactValue.writeUnsafe(next);
                        int exactRead = (int)exactValue.read();
                        if (exactRead != next) throw new InvalidOperationException("exact value route");

                        ErasedStore exactNullable = new ErasedStore(null);
                        exactNullable.writeUnsafe(next);
                        if ((int)exactNullable.read() != next)
                            throw new InvalidOperationException("already-nullable route");

                        ErasedStore exactReference = new ErasedStore(null);
                        exactReference.writeUnsafe("reference");
                        if (!object.Equals(exactReference.read(), "reference"))
                            throw new InvalidOperationException("exact reference route");

                        ApplicationKnownStruct known =
                            new ApplicationKnownStruct { Value = next };
                        ErasedStore exactKnown = new ErasedStore(null);
                        exactKnown.writeUnsafe(known);
                        if (((ApplicationKnownStruct)exactKnown.read()).Value != next)
                            throw new InvalidOperationException("exact known struct route");

                        ErasedStore fallbackGuid = new ErasedStore(guid);
                        fallbackGuid.writeUnsafe(guid);
                        if (!object.Equals(fallbackGuid.read(), guid))
                            throw new InvalidOperationException("Guid fallback route");

                        ErasedStore fallbackDate = new ErasedStore(date);
                        fallbackDate.writeUnsafe(date);
                        if (!object.Equals(fallbackDate.read(), date))
                            throw new InvalidOperationException("DateTime fallback route");

                        ErasedStore fallbackDecimal = new ErasedStore(amount);
                        fallbackDecimal.writeUnsafe(amount);
                        if (!object.Equals(fallbackDecimal.read(), amount))
                            throw new InvalidOperationException("decimal fallback route");

                        ErasedStore fallbackEnum = new ErasedStore(ApplicationEnum.Second);
                        fallbackEnum.writeUnsafe(ApplicationEnum.Second);
                        if (!object.Equals(fallbackEnum.read(), ApplicationEnum.Second))
                            throw new InvalidOperationException("enum fallback route");

                        ErasedStore fallbackTuple = new ErasedStore(tuple);
                        fallbackTuple.writeUnsafe(tuple);
                        if (!object.Equals(fallbackTuple.read(), tuple))
                            throw new InvalidOperationException("tuple fallback route");

                        ApplicationStruct user = new ApplicationStruct { Count = next + 1, Id = guid };
                        ErasedStore fallbackUser = new ErasedStore(user);
                        fallbackUser.writeUnsafe(user);
                        if (((ApplicationStruct)fallbackUser.read()).Count != next + 1)
                            throw new InvalidOperationException("user struct fallback route");

                        ApplicationUnknownReference unknownReference =
                            new ApplicationUnknownReference { Value = "fallback" };
                        ErasedStore fallbackReference = new ErasedStore(unknownReference);
                        fallbackReference.writeUnsafe(unknownReference);
                        if (!object.ReferenceEquals(fallbackReference.read(), unknownReference))
                            throw new InvalidOperationException("reference fallback route");

                        mixed.writeUnsafe(next);
                        int typedRead = (int)mixed.read();
                        if (typedRead != next) throw new InvalidOperationException("typed dispatch");
                        if (!object.ReferenceEquals(mixed.echo(typedArray), typedArray) ||
                                !object.ReferenceEquals(mixed.echo(semanticArray), semanticArray) ||
                                !object.ReferenceEquals(
                                    mixed.relay<ApplicationKnownStruct>(knownArray), knownArray))
                            throw new InvalidOperationException("array dispatch");

                        if ((index & 63) == 0)
                        {
                            hostile.writeUnsafe("wrong");
                            if (!object.Equals(hostile.read(), "csharp:grandchild:wrong"))
                                throw new InvalidOperationException("semantic hostile dispatch");
                            try
                            {
                                int invalid = (int)hostile.read();
                                throw new InvalidOperationException(
                                    "delayed typed read did not fail: " + invalid);
                            }
                            catch (InvalidCastException)
                            {
                                checksum = unchecked(checksum * 31 + 7);
                            }
                        }
                        checksum = unchecked(
                            checksum * 31 + exactRead + typedRead + known.Value + user.Count +
                            (int)ApplicationEnum.Second + tuple.Item1);
                    }
                    return checksum;
                }

                public static int Main(string[] arguments)
                {
                    VerifyVolatileOneState();
                    bool holdForPeakWorkingSet = arguments.Length == 3 &&
                        arguments[2] == "--hold-for-peak-working-set";
                    if ((arguments.Length != 2 && !holdForPeakWorkingSet) ||
                            arguments[0] != "--measurement" ||
                            !int.TryParse(arguments[1], out int iterations) || iterations < 0)
                    {
                        Console.Error.WriteLine(
                            "usage: --measurement <non-negative iterations> " +
                            "[--hold-for-peak-working-set]");
                        return 64;
                    }
                    if (iterations > 0)
                        ExecuteApplicationMeasurementWorkload(Math.Min(iterations, 256));
                    GC.Collect();
                    GC.WaitForPendingFinalizers();
                    GC.Collect();
                    long allocatedBefore = GC.GetAllocatedBytesForCurrentThread();
                    long started = System.Diagnostics.Stopwatch.GetTimestamp();
                    int checksum = ExecuteApplicationMeasurementWorkload(iterations);
                    long elapsedTicks = System.Diagnostics.Stopwatch.GetTimestamp() - started;
                    long allocatedBytes = GC.GetAllocatedBytesForCurrentThread() - allocatedBefore;
                    long periodicRoutes = (iterations + 63L) / 64L;
                    Console.WriteLine(
                        "GENERIC_OWNER_APPLICATION_MEASUREMENT|workloadVersion=1" +
                        "|representation=erased" +
                        "|iterations=" + iterations +
                        "|checksum=" + checksum +
                        "|elapsedTicks=" + elapsedTicks +
                        "|frequency=" + System.Diagnostics.Stopwatch.Frequency +
                        "|allocatedBytes=" + allocatedBytes +
                        "|typedEntryCalls=0" +
                        "|semanticCapabilityCalls=0" +
                        "|erasedVirtualCalls=" + (iterations * 27L + periodicRoutes * 2L));
                    if (holdForPeakWorkingSet)
                    {
                        Console.Out.Flush();
                        if (Console.In.ReadLine() != "release")
                        {
                            Console.Error.WriteLine("peak-working-set hold was not released");
                            return 65;
                        }
                    }
                    return 0;
                }
                #else
                private static bool RoundTrips(object value)
                {
                    ErasedStore owner = new ErasedStore(value);
                    if (!object.Equals(owner.read(), value)) return false;
                    owner.writeUnsafe(value);
                    return object.Equals(owner.read(), value);
                }

                public static int Main()
                {
                    VerifyVolatileOneState();
                    Guid guid = new Guid("00112233-4455-6677-8899-aabbccddeeff");
                    DateTime date = new DateTime(638900000000000000L, DateTimeKind.Utc);
                    decimal amount = 1234567.8901m;
                    ValueTuple<int, string> tuple = new ValueTuple<int, string>(7, "tuple");
                    ApplicationStruct user = new ApplicationStruct { Count = 11, Id = guid };
                    if (!RoundTrips(guid) || !RoundTrips(date) || !RoundTrips(amount) ||
                            !RoundTrips(ApplicationEnum.Second) || !RoundTrips(tuple) ||
                            !RoundTrips(user) || !RoundTrips(null)) return 1;

                    ErasedStore mixed = new ErasedStore(guid);
                    mixed.writeUnsafe(date);
                    if (!object.Equals(mixed.read(), date)) return 2;
                    mixed.writeUnsafe(amount);
                    if (!object.Equals(mixed.read(), amount)) return 3;
                    mixed.writeUnsafe(user);
                    if (!object.Equals(mixed.read(), user)) return 4;

                    Guid?[] nullableGuids = new Guid?[] { guid, null };
                    string[] strings = new string[] { "array" };
                    if (!object.ReferenceEquals(mixed.echo(nullableGuids), nullableGuids) ||
                            !object.ReferenceEquals(mixed.echo(strings), strings)) return 5;
                    ApplicationStruct[] users = new ApplicationStruct[] { user };
                    if (!object.ReferenceEquals(mixed.relay<ApplicationStruct>(users), users)) return 6;

                    ErasedCSharpGrandchild child = new ErasedCSharpGrandchild("initial");
                    child.writeUnsafe("value");
                    if (!object.Equals(child.read(), "csharp:grandchild:value")) return 7;
                    if (!object.ReferenceEquals(child.echo(strings), strings)) return 8;

                    Type ownerType = typeof(ErasedStore);
                    System.Reflection.MethodInfo read = ownerType.GetMethod("read");
                    System.Reflection.MethodInfo write = ownerType.GetMethod("writeUnsafe");
                    System.Reflection.MethodInfo echo = ownerType.GetMethod("echo");
                    System.Reflection.MethodInfo relay = ownerType.GetMethod("relay");
                    if (ownerType.IsGenericType || ownerType.GetGenericArguments().Length != 0 ||
                            ownerType.GetConstructor(new Type[] { typeof(object) }) == null ||
                            read == null || read.ReturnType != typeof(object) ||
                            write == null || write.GetParameters()[0].ParameterType != typeof(object) ||
                            echo == null || echo.ReturnType != typeof(Array) ||
                            echo.GetParameters()[0].ParameterType != typeof(Array) ||
                            relay == null || !relay.IsGenericMethodDefinition ||
                            relay.GetGenericArguments().Length != 1) return 9;
                    return 0;
                }
                #endif
            }
            """.trimIndent()
        )
    }
    val erasedCSharpAssembly = directory.resolve(genericOwnerErasedCSharpAssemblyFile(target))
    val erasedCSharpCompilation = when (target) {
        DotNetTarget.NET48 -> compileFrameworkSnapshotCSharp(
            checkNotNull(DotNetIlAssembler.findFrameworkCSharpCompiler()) {
                "Framework C# compiler is required for the erased generic-owner application corpus"
            },
            erasedCSharpSource,
            erasedCSharpAssembly,
            references = listOf(erasedProducer, stagedRuntime, stagedStdlib),
            executable = true,
        )
        DotNetTarget.NET10_0 -> compileModernSnapshotCSharp(
            checkNotNull(DotNetIlAssembler.findModernCSharpCompiler()) {
                "Modern C# compiler is required for the erased generic-owner application corpus"
            },
            erasedCSharpSource,
            erasedCSharpAssembly,
            references = listOf(erasedProducer, stagedRuntime, stagedStdlib),
            executable = true,
        )
        DotNetTarget.NETSTANDARD_2_0 -> error("netstandard2.0 has no executable application corpus")
    }
    check(erasedCSharpCompilation.exitCode == 0) { erasedCSharpCompilation.output }
    executeSnapshotConsumer(target, erasedCSharpAssembly, directory)
    val erasedCSharpRuntimeConfig = if (target == DotNetTarget.NET10_0) {
        directory.resolve("${erasedCSharpAssembly.nameWithoutExtension}.runtimeconfig.json")
    } else {
        null
    }
    check(erasedCSharpRuntimeConfig?.isFile != false) {
        "The erased generic-owner C# application lacks its runtime config"
    }
    val globalJson = if (target == DotNetTarget.NET10_0) {
        directory.resolve("global.json").apply {
            writeText(
            """
            {
              "sdk": {
                "version": "10.0.100",
                "rollForward": "disable",
                "allowPrerelease": false
              }
            }
            """.trimIndent()
            )
        }
    } else {
        null
    }
    val manifest = directory.resolve(GENERIC_OWNER_APPLICATION_MANIFEST_FILE).apply {
        writeText(buildString {
            appendLine("schema=2")
            appendLine("sdkVersion=${if (target == DotNetTarget.NET10_0) "10.0.100" else "framework-clr"}")
            appendLine("targetProfile=${target.name}")
            appendLine("applicationSourceSha256=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(applicationSource.readBytes())}")
            appendLine("candidateProducerSha256=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(candidateProducer.readBytes())}")
            appendLine("candidateConsumerSha256=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(candidateConsumer.readBytes())}")
            candidateRuntimeConfig?.let { file ->
                appendLine("candidateRuntimeConfigSha256=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(file.readBytes())}")
            }
            appendLine("candidateSourceSha256=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(source.readBytes())}")
            appendLine("physicalFamilyArtifactSha256=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(physicalFamilyArtifact.readBytes())}")
            appendLine("callRouteManifestSha256=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(callRouteManifest.readBytes())}")
            appendLine("erasedProducerSha256=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(erasedProducer.readBytes())}")
            appendLine("erasedConsumerSha256=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(erasedConsumer.readBytes())}")
            erasedConsumerRuntimeConfig?.let { file ->
                appendLine("erasedConsumerRuntimeConfigSha256=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(file.readBytes())}")
            }
            appendLine("erasedCSharpSourceSha256=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(erasedCSharpSource.readBytes())}")
            appendLine("erasedCSharpAssemblySha256=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(erasedCSharpAssembly.readBytes())}")
            erasedCSharpRuntimeConfig?.let { file ->
                appendLine("erasedCSharpRuntimeConfigSha256=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(file.readBytes())}")
            }
            appendLine("runtimeSha256=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(runtime.readBytes())}")
            appendLine("stdlibSha256=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(stdlib.readBytes())}")
            globalJson?.let { file ->
                append("globalJsonSha256=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(file.readBytes())}")
            }
        })
    }
    val bundleFiles = listOf(
        source,
        candidateProducer,
        candidateConsumer,
        physicalFamilyArtifact,
        callRouteManifest,
        applicationSource,
        erasedProducer,
        erasedConsumer,
        erasedCSharpSource,
        erasedCSharpAssembly,
        stagedRuntime,
        stagedStdlib,
        manifest,
    ) + listOfNotNull(
        candidateRuntimeConfig,
        erasedConsumerRuntimeConfig,
        erasedCSharpRuntimeConfig,
        globalJson,
    )
    check(bundleFiles.map(File::getName).toSet().size == bundleFiles.size && bundleFiles.all(File::isFile)) {
        "The generic-owner application bundle is incomplete or has colliding file names"
    }
    check(!exportDirectory.exists() || exportDirectory.isDirectory) {
        "Generic-owner application export path is not a directory: $exportDirectory"
    }
    check(exportDirectory.mkdirs() || exportDirectory.isDirectory) {
        "Cannot create generic-owner application export directory: $exportDirectory"
    }
    check(exportDirectory.list()?.isEmpty() == true) {
        "Generic-owner application export directory must be empty: $exportDirectory"
    }
    bundleFiles.forEach { file -> file.copyTo(exportDirectory.resolve(file.name), overwrite = false) }
}

private fun DotNetGenericOwnerPhysicalTypeExpressionRecord.renderSnapshotCSharpType(
    ownerArguments: List<String>,
    methodArguments: List<String> = emptyList(),
): String = when (kind) {
    DotNetGenericOwnerPhysicalTypeKind.VOID -> "void"
    DotNetGenericOwnerPhysicalTypeKind.BOOLEAN -> "bool"
    DotNetGenericOwnerPhysicalTypeKind.INT32 -> "int"
    DotNetGenericOwnerPhysicalTypeKind.STRING -> "string"
    DotNetGenericOwnerPhysicalTypeKind.OBJECT -> "object"
    DotNetGenericOwnerPhysicalTypeKind.OWNER_TYPE_PARAMETER ->
        ownerArguments.getOrElse(checkNotNull(parameterIndex)) {
            error("The recorded physical type references a missing owner argument: $this")
        }
    DotNetGenericOwnerPhysicalTypeKind.METHOD_TYPE_PARAMETER ->
        methodArguments.getOrElse(checkNotNull(parameterIndex)) {
            error("The recorded physical type references a missing method argument: $this")
        }
    DotNetGenericOwnerPhysicalTypeKind.NAMED -> buildString {
        check(scope != null && typePath.isNotEmpty()) { "The recorded named physical type is incomplete: $this" }
        append(typePath.joinToString("."))
        if (arguments.isNotEmpty()) {
            append('<')
            append(arguments.joinToString(", ") { argument ->
                argument.renderSnapshotCSharpType(ownerArguments, methodArguments)
            })
            append('>')
        }
    }
    DotNetGenericOwnerPhysicalTypeKind.SZ_ARRAY ->
        "${arguments.single().renderSnapshotCSharpType(ownerArguments, methodArguments)}[]"
}

/** Renders one C# type use from the artifact's explicit Roslyn preorder transforms. */
private fun DotNetGenericOwnerPhysicalTypeExpressionRecord.renderSnapshotCSharpType(
    ownerArguments: List<String>,
    methodArguments: List<String> = emptyList(),
    nullableFlags: List<DotNetNullableReferenceFlag>,
): String {
    var flagIndex = 0

    fun nextFlag(): DotNetNullableReferenceFlag = nullableFlags.getOrElse(flagIndex++) {
        error("The recorded physical type has an incomplete nullable transform: $this")
    }

    fun annotated(typeName: String, flag: DotNetNullableReferenceFlag): String = when (flag) {
        DotNetNullableReferenceFlag.OBLIVIOUS,
        DotNetNullableReferenceFlag.NON_NULL,
            -> typeName
        DotNetNullableReferenceFlag.NULLABLE -> "$typeName?"
    }

    fun render(type: DotNetGenericOwnerPhysicalTypeExpressionRecord): String = when (type.kind) {
        DotNetGenericOwnerPhysicalTypeKind.VOID -> "void"
        DotNetGenericOwnerPhysicalTypeKind.BOOLEAN -> "bool"
        DotNetGenericOwnerPhysicalTypeKind.INT32 -> "int"
        DotNetGenericOwnerPhysicalTypeKind.STRING -> annotated("string", nextFlag())
        DotNetGenericOwnerPhysicalTypeKind.OBJECT -> annotated("object", nextFlag())
        DotNetGenericOwnerPhysicalTypeKind.OWNER_TYPE_PARAMETER -> annotated(
            ownerArguments.getOrElse(checkNotNull(type.parameterIndex)) {
                error("The recorded physical type references a missing owner argument: $type")
            },
            nextFlag(),
        )
        DotNetGenericOwnerPhysicalTypeKind.METHOD_TYPE_PARAMETER -> annotated(
            methodArguments.getOrElse(checkNotNull(type.parameterIndex)) {
                error("The recorded physical type references a missing method argument: $type")
            },
            nextFlag(),
        )
        DotNetGenericOwnerPhysicalTypeKind.NAMED -> {
            check(type.scope != null && type.typePath.isNotEmpty()) {
                "The recorded named physical type is incomplete: $type"
            }
            val rootFlag = nextFlag()
            val typeName = buildString {
                append(type.typePath.joinToString("."))
                if (type.arguments.isNotEmpty()) {
                    append('<')
                    append(type.arguments.joinToString(", ") { argument -> render(argument) })
                    append('>')
                }
            }
            if (type.namedTypeCategory == DotNetGenericOwnerPhysicalNamedTypeCategory.VALUE_TYPE) {
                check(rootFlag != DotNetNullableReferenceFlag.NULLABLE) {
                    "The bounded C# renderer cannot project a nullable named value type: $type"
                }
                typeName
            } else {
                annotated(typeName, rootFlag)
            }
        }
        DotNetGenericOwnerPhysicalTypeKind.SZ_ARRAY -> {
            val rootFlag = nextFlag()
            annotated("${render(type.arguments.single())}[]", rootFlag)
        }
    }

    val rendered = render(this)
    check(flagIndex == nullableFlags.size) {
        "The recorded physical type has ${nullableFlags.size - flagIndex} surplus nullable transforms: $this"
    }
    return rendered
}

private fun DotNetGenericOwnerPhysicalTypeExpressionRecord.renderMetadataSignatureType(): String = when (kind) {
    DotNetGenericOwnerPhysicalTypeKind.VOID -> "System.Void"
    DotNetGenericOwnerPhysicalTypeKind.BOOLEAN -> "System.Boolean"
    DotNetGenericOwnerPhysicalTypeKind.INT32 -> "System.Int32"
    DotNetGenericOwnerPhysicalTypeKind.STRING -> "System.String"
    DotNetGenericOwnerPhysicalTypeKind.OBJECT -> "System.Object"
    DotNetGenericOwnerPhysicalTypeKind.OWNER_TYPE_PARAMETER -> "!${checkNotNull(parameterIndex)}"
    DotNetGenericOwnerPhysicalTypeKind.METHOD_TYPE_PARAMETER -> "!!${checkNotNull(parameterIndex)}"
    DotNetGenericOwnerPhysicalTypeKind.NAMED -> buildString {
        append(typePath.joinToString("."))
        if (genericArity > 0) append("`").append(genericArity)
        if (arguments.isNotEmpty()) {
            append('<')
            append(arguments.joinToString(",") { argument -> argument.renderMetadataSignatureType() })
            append('>')
        }
    }
    DotNetGenericOwnerPhysicalTypeKind.SZ_ARRAY ->
        "${arguments.single().renderMetadataSignatureType()}[]"
}

private fun genericOwnerHostileSupertypeMetadataInspectorSource(
    artifact: DotNetGenericOwnerPhysicalFamilyArtifact,
    producer: File,
): String {
    fun String.csharpLiteral(): String = "\"" +
            replace("\\", "\\\\").replace("\"", "\\\"").replace("\r", "\\r").replace("\n", "\\n") + "\""
    fun nullableFlags(values: List<DotNetNullableReferenceFlag>): String =
        "new byte[] { ${values.joinToString(", ") { value -> value.metadataValue.toString() }} }"

    val derived = artifact.owners.single { owner ->
        owner.physicalOwnerPath.last() == "HostileNullableReferenceDerived"
    }
    val base = artifact.owners.single { owner ->
        owner.physicalOwnerPath.last() == "HostileNullableReferenceBase"
    }
    val marker = artifact.interfaceTypes.single { type ->
        type.physicalTypePath.last() == "HostileNullableMarker"
    }
    val baseEdge = derived.directSupertypes.single { supertype ->
        supertype.kind == DotNetGenericOwnerDirectSupertypeKind.BASE_CLASS
    }
    val interfaceEdge = derived.directSupertypes.single { supertype ->
        supertype.kind == DotNetGenericOwnerDirectSupertypeKind.INTERFACE
    }
    check(!interfaceEdge.isSemanticCapability && interfaceEdge.logicalClassifierKey == marker.logicalInterfaceKey &&
            baseEdge.logicalClassifierKey == base.logicalOwnerKey &&
            baseEdge.nullableReferenceFlags == listOf(
                DotNetNullableReferenceFlag.OBLIVIOUS,
                DotNetNullableReferenceFlag.NULLABLE,
                DotNetNullableReferenceFlag.NON_NULL,
            ) && interfaceEdge.nullableReferenceFlags == baseEdge.nullableReferenceFlags) {
        "The hostile metadata inspector requires the exact nested-nullable base/interface graph"
    }

    return """
        using System;
        using System.Collections.Immutable;
        using System.IO;
        using System.Linq;
        using System.Reflection;
        using System.Reflection.Metadata;
        using System.Reflection.PortableExecutable;

        public static class Program
        {
            private sealed class SignatureTypeProvider : ISignatureTypeProvider<string, object>
            {
                public string GetArrayType(string elementType, ArrayShape shape) => elementType + "[array]";
                public string GetByReferenceType(string elementType) => elementType + "&";
                public string GetFunctionPointerType(MethodSignature<string> signature) => "fnptr";
                public string GetGenericInstantiation(string genericType, ImmutableArray<string> arguments) =>
                    genericType + "<" + string.Join(",", arguments) + ">";
                public string GetGenericMethodParameter(object context, int index) => "!!" + index;
                public string GetGenericTypeParameter(object context, int index) => "!" + index;
                public string GetModifiedType(string modifier, string unmodifiedType, bool required) => unmodifiedType;
                public string GetPinnedType(string elementType) => elementType;
                public string GetPointerType(string elementType) => elementType + "*";
                public string GetPrimitiveType(PrimitiveTypeCode code)
                {
                    if (code == PrimitiveTypeCode.Object) return "System.Object";
                    if (code == PrimitiveTypeCode.Void) return "System.Void";
                    return "primitive:" + code;
                }
                public string GetSZArrayType(string elementType) => elementType + "[]";
                public string GetTypeFromDefinition(
                    MetadataReader reader, TypeDefinitionHandle handle, byte rawTypeKind) => TypeName(reader, handle);
                public string GetTypeFromReference(
                    MetadataReader reader, TypeReferenceHandle handle, byte rawTypeKind) => TypeName(reader, handle);
                public string GetTypeFromSpecification(
                    MetadataReader reader, object context, TypeSpecificationHandle handle, byte rawTypeKind) =>
                    reader.GetTypeSpecification(handle).DecodeSignature(this, context);
            }

            private static readonly SignatureTypeProvider Provider = new SignatureTypeProvider();
            private static string JoinName(string ns, string name) =>
                string.IsNullOrEmpty(ns) ? name : ns + "." + name;
            private static string TypeName(MetadataReader reader, TypeDefinitionHandle handle)
            {
                TypeDefinition type = reader.GetTypeDefinition(handle);
                return JoinName(reader.GetString(type.Namespace), reader.GetString(type.Name));
            }
            private static string TypeName(MetadataReader reader, TypeReferenceHandle handle)
            {
                TypeReference type = reader.GetTypeReference(handle);
                return JoinName(reader.GetString(type.Namespace), reader.GetString(type.Name));
            }
            private static string TypeName(MetadataReader reader, EntityHandle handle)
            {
                if (handle.Kind == HandleKind.TypeDefinition) return TypeName(reader, (TypeDefinitionHandle)handle);
                if (handle.Kind == HandleKind.TypeReference) return TypeName(reader, (TypeReferenceHandle)handle);
                if (handle.Kind == HandleKind.TypeSpecification)
                    return reader.GetTypeSpecification((TypeSpecificationHandle)handle).DecodeSignature(Provider, null);
                throw new InvalidOperationException("Unsupported type handle " + handle.Kind);
            }
            private static TypeDefinitionHandle FindType(MetadataReader reader, string ns, string name)
            {
                TypeDefinitionHandle[] matches = reader.TypeDefinitions.Where(handle =>
                {
                    TypeDefinition type = reader.GetTypeDefinition(handle);
                    return reader.GetString(type.Namespace) == ns && reader.GetString(type.Name) == name;
                }).ToArray();
                if (matches.Length != 1) throw new InvalidOperationException("Expected one TypeDef " + name);
                return matches[0];
            }
            private static TypeDefinitionHandle DeclaringType(
                MetadataReader reader, MethodDefinitionHandle methodHandle)
            {
                return reader.TypeDefinitions.Single(typeHandle =>
                    reader.GetTypeDefinition(typeHandle).GetMethods().Contains(methodHandle));
            }
            private static string AttributeTypeName(MetadataReader reader, CustomAttribute attribute)
            {
                if (attribute.Constructor.Kind == HandleKind.MemberReference)
                    return TypeName(reader, reader.GetMemberReference(
                        (MemberReferenceHandle)attribute.Constructor).Parent);
                if (attribute.Constructor.Kind == HandleKind.MethodDefinition)
                    return TypeName(reader, DeclaringType(reader, (MethodDefinitionHandle)attribute.Constructor));
                throw new InvalidOperationException("Unsupported attribute constructor");
            }
            private static byte[] DecodeNullableTransform(MetadataReader reader, CustomAttribute attribute)
            {
                BlobReader blob = reader.GetBlobReader(attribute.Value);
                if (blob.ReadUInt16() != 1) throw new InvalidOperationException("Invalid attribute prolog");
                if (blob.RemainingBytes == 3)
                {
                    byte scalar = blob.ReadByte();
                    if (blob.ReadUInt16() != 0 || blob.RemainingBytes != 0)
                        throw new InvalidOperationException("Invalid scalar nullable transform");
                    return new byte[] { scalar };
                }
                int count = blob.ReadInt32();
                if (count < 0 || blob.RemainingBytes != count + 2)
                    throw new InvalidOperationException("Invalid nullable transform vector");
                byte[] result = blob.ReadBytes(count);
                if (blob.ReadUInt16() != 0 || blob.RemainingBytes != 0)
                    throw new InvalidOperationException("Invalid nullable transform suffix");
                return result;
            }
            private static byte[] LocalNullableTransform(
                MetadataReader reader, EntityHandle handle, string attributeName)
            {
                CustomAttribute[] matches = reader.GetCustomAttributes(handle).Select(reader.GetCustomAttribute)
                    .Where(attribute => AttributeTypeName(reader, attribute) == attributeName).ToArray();
                if (matches.Length > 1) throw new InvalidOperationException("Duplicate " + attributeName);
                return matches.Length == 0 ? null : DecodeNullableTransform(reader, matches[0]);
            }
            private static void CheckNullableTransform(
                MetadataReader reader,
                EntityHandle position,
                TypeDefinitionHandle typeHandle,
                byte[] expected,
                string description)
            {
                byte[] actual = LocalNullableTransform(
                    reader, position, "System.Runtime.CompilerServices.NullableAttribute");
                if (actual != null && actual.Length == 1)
                    actual = Enumerable.Repeat(actual[0], expected.Length).ToArray();
                if (actual == null)
                {
                    byte[] context = LocalNullableTransform(
                        reader, typeHandle, "System.Runtime.CompilerServices.NullableContextAttribute");
                    byte fallback = context == null ? (byte)0 : context.Single();
                    actual = Enumerable.Repeat(fallback, expected.Length).ToArray();
                }
                if (!actual.SequenceEqual(expected))
                    throw new InvalidOperationException(
                        description + " nullable transform differs: expected " + string.Join(",", expected) +
                        ", actual " + string.Join(",", actual));
            }

            public static int Main()
            {
                using (FileStream stream = File.OpenRead(${producer.absolutePath.csharpLiteral()}))
                using (var pe = new PEReader(stream))
                {
                    MetadataReader reader = pe.GetMetadataReader();
                    string ns = ${derived.physicalOwnerPath.dropLast(1).joinToString(".").csharpLiteral()};
                    TypeDefinitionHandle derivedHandle = FindType(
                        reader, ns, ${(derived.physicalOwnerPath.last() + "`" + derived.genericArity).csharpLiteral()});
                    TypeDefinition definition = reader.GetTypeDefinition(derivedHandle);
                    if (TypeName(reader, definition.BaseType) !=
                            ${baseEdge.physicalType.renderMetadataSignatureType().csharpLiteral()})
                        throw new InvalidOperationException("BaseType row differs");
                    InterfaceImplementationHandle[] interfaces = definition.GetInterfaceImplementations().ToArray();
                    if (interfaces.Length != 1 || TypeName(
                            reader, reader.GetInterfaceImplementation(interfaces[0]).Interface) !=
                            ${interfaceEdge.physicalType.renderMetadataSignatureType().csharpLiteral()})
                        throw new InvalidOperationException("InterfaceImpl row differs");
                    CheckNullableTransform(
                        reader, derivedHandle, derivedHandle, ${nullableFlags(baseEdge.nullableReferenceFlags)},
                        "BaseType");
                    CheckNullableTransform(
                        reader, interfaces[0], derivedHandle,
                        ${nullableFlags(interfaceEdge.nullableReferenceFlags)}, "InterfaceImpl");

                    TypeDefinition markerDefinition = reader.GetTypeDefinition(FindType(
                        reader,
                        ${marker.physicalTypePath.dropLast(1).joinToString(".").csharpLiteral()},
                        ${(marker.physicalTypePath.last() + "`" + marker.genericArity).csharpLiteral()}));
                    if ((markerDefinition.Attributes & TypeAttributes.Interface) == 0 ||
                            markerDefinition.GetGenericParameters().Count != ${marker.genericArity} ||
                            markerDefinition.GetInterfaceImplementations().Count != 0)
                        throw new InvalidOperationException("Marker interface TypeDef differs");
                }
                return 0;
            }
        }
    """.trimIndent()
}

private fun genericOwnerMetadataInspectorSource(
    artifact: DotNetGenericOwnerPhysicalFamilyArtifact,
    producer: File,
    scenarioTreeLogicalOwnerKey: String,
): String {
    fun String.csharpLiteral(): String = "\"" +
            replace("\\", "\\\\").replace("\"", "\\\"").replace("\r", "\\r").replace("\n", "\\n") + "\""
    fun strings(values: List<String>): String =
        "new string[] { ${values.joinToString(", ") { value -> value.csharpLiteral() }} }"
    fun nullableFlags(values: List<DotNetNullableReferenceFlag>): String =
        "new byte[] { ${values.joinToString(", ") { value -> value.metadataValue.toString() }} }"
    fun nullableFlagLists(values: List<List<DotNetNullableReferenceFlag>>): String =
        "new byte[][] { ${values.joinToString(", ") { value -> nullableFlags(value) }} }"
    fun DotNetGenericOwnerPhysicalMemberVisibility.metadataAttribute(): String = when (this) {
        DotNetGenericOwnerPhysicalMemberVisibility.PUBLIC -> "MethodAttributes.Public"
        DotNetGenericOwnerPhysicalMemberVisibility.FAMILY -> "MethodAttributes.Family"
        DotNetGenericOwnerPhysicalMemberVisibility.ASSEMBLY -> "MethodAttributes.Assembly"
        DotNetGenericOwnerPhysicalMemberVisibility.FAMILY_OR_ASSEMBLY -> "MethodAttributes.FamORAssem"
        DotNetGenericOwnerPhysicalMemberVisibility.PRIVATE -> "MethodAttributes.Private"
    }
    fun DotNetGenericOwnerPhysicalConstructorVisibility.metadataAttribute(): String = when (this) {
        DotNetGenericOwnerPhysicalConstructorVisibility.PUBLIC -> "MethodAttributes.Public"
        DotNetGenericOwnerPhysicalConstructorVisibility.FAMILY -> "MethodAttributes.Family"
        DotNetGenericOwnerPhysicalConstructorVisibility.ASSEMBLY -> "MethodAttributes.Assembly"
        DotNetGenericOwnerPhysicalConstructorVisibility.FAMILY_AND_ASSEMBLY -> "MethodAttributes.FamANDAssem"
        DotNetGenericOwnerPhysicalConstructorVisibility.FAMILY_OR_ASSEMBLY -> "MethodAttributes.FamORAssem"
        DotNetGenericOwnerPhysicalConstructorVisibility.PRIVATE -> "MethodAttributes.Private"
    }
    fun methodExpectation(
        identity: DotNetGenericOwnerPhysicalMethodIdentityRecord,
        visibility: String,
        isAbstract: Boolean,
        isVirtual: Boolean,
        isFinal: Boolean,
    ): String = "new ExpectedMethod(" + listOf(
        identity.physicalMethodName.csharpLiteral(),
        identity.signature.returnSlot.type.renderMetadataSignatureType().csharpLiteral(),
        nullableFlags(identity.signature.returnSlot.nullableReferenceFlags),
        strings(identity.signature.parameterSlots.map { parameter ->
            parameter.type.renderMetadataSignatureType()
        }),
        nullableFlagLists(identity.signature.parameterSlots.map { parameter ->
            parameter.nullableReferenceFlags
        }),
        visibility,
        (!identity.signature.isInstance).toString(),
        isAbstract.toString(),
        isVirtual.toString(),
        isFinal.toString(),
    ).joinToString(", ") + ")"
    fun propertyExpectation(property: DotNetGenericOwnerPhysicalPropertyRecord): String =
        "new ExpectedProperty(" + listOf(
            property.physicalPropertyName.csharpLiteral(),
            property.physicalType.renderMetadataSignatureType().csharpLiteral(),
            nullableFlags(property.nullableReferenceFlags),
            property.getterPhysicalMethod?.physicalMethodName?.csharpLiteral() ?: "null",
            property.setterPhysicalMethod?.physicalMethodName?.csharpLiteral() ?: "null",
        ).joinToString(", ") + ")"

    val ownerChecks = artifact.owners.joinToString("\n") { owner ->
        check(owner.members.all { member -> member.defaultDispatcher == null }) {
            "The OctoTree metadata inspector requires every default helper to be explicitly modeled"
        }
        val baseEdge = owner.directSupertypes.single { supertype ->
            supertype.kind == DotNetGenericOwnerDirectSupertypeKind.BASE_CLASS
        }
        val baseType = baseEdge.physicalType.renderMetadataSignatureType()
        val directInterfaceEdges = owner.directSupertypes
            .filter { supertype -> supertype.kind == DotNetGenericOwnerDirectSupertypeKind.INTERFACE }
            .sortedBy { supertype -> supertype.physicalType.renderMetadataSignatureType() }
        val methods = buildList {
            owner.constructors.forEach { constructor ->
                add(methodExpectation(
                    constructor.physicalConstructor,
                    constructor.visibility.metadataAttribute(),
                    isAbstract = false,
                    isVirtual = false,
                    isFinal = false,
                ))
            }
            owner.members.forEach { member ->
                member.slots.forEach { slot ->
                    add(methodExpectation(
                        DotNetGenericOwnerPhysicalMethodIdentityRecord(
                            slot.physicalOwnerPath,
                            slot.physicalMethodName,
                            slot.signature,
                        ),
                        slot.visibility.metadataAttribute(),
                        isAbstract = slot.dispatch == DotNetGenericOwnerPhysicalMemberDispatch.ABSTRACT,
                        isVirtual = slot.dispatch != DotNetGenericOwnerPhysicalMemberDispatch.FINAL ||
                                slot.role == DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
                        isFinal = slot.role == DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER,
                    ))
                }
            }
            owner.implementationMethods.forEach { method ->
                add(methodExpectation(
                    method.physicalMethod,
                    method.visibility.metadataAttribute(),
                    isAbstract = false,
                    isVirtual = false,
                    isFinal = false,
                ))
            }
            owner.states.flatMap { state -> state.accessPaths }.filter { access ->
                access.bindingKind == DotNetGenericOwnerPhysicalStateAccessBindingKind.PRODUCER_PRIVATE_METHOD
            }.forEach { access ->
                add(methodExpectation(
                    access.physicalMethod,
                    checkNotNull(access.physicalVisibility).metadataAttribute(),
                    isAbstract = false,
                    isVirtual = false,
                    isFinal = false,
                ))
            }
            if (owner.logicalOwnerKey == scenarioTreeLogicalOwnerKey) {
                add(
                    "new ExpectedMethod(\"__kotlin_number\", \"System.Int32\", " +
                            "new byte[] { }, " +
                            "new string[] { \"System.Int32\", \"System.Int32\", \"System.Int32\", " +
                            "\"System.Int32\" }, new byte[][] { new byte[] { }, new byte[] { }, " +
                            "new byte[] { }, new byte[] { } }, " +
                            "MethodAttributes.Assembly, true, false, false, false)"
                )
            }
        }
        check(methods.size == methods.toSet().size) {
            "The OctoTree metadata inspector received duplicate expected methods for ${owner.logicalOwnerKey}"
        }
        val fields = buildList {
            owner.states.forEach { state ->
                add(
                    "new ExpectedField(${state.physicalFieldName.csharpLiteral()}, " +
                            "${state.physicalType.renderMetadataSignatureType().csharpLiteral()}, " +
                            "${nullableFlags(state.nullableReferenceFlags)}, " +
                            "${state.isInitOnly})"
                )
            }
        }
        val properties = owner.properties.map(::propertyExpectation)
        val methodImpls = owner.members.flatMap { member -> member.slots }
            .filter { slot -> slot.role == DotNetGenericOwnerMemberFamilyRole.CAPABILITY_DISPATCHER }
            .map { slot ->
                val declaration = checkNotNull(slot.capabilitySlot)
                "new ExpectedMethodImpl(${declaration.physicalMethodName.csharpLiteral()}, " +
                        "${slot.physicalMethodName.csharpLiteral()})"
            }
        val specialConstraints = owner.physicalGenericParameters.map { parameter ->
            parameter.specialConstraints.fold(0) { bits, constraint ->
                bits or when (constraint) {
                    DotNetGenericOwnerPhysicalGenericParameterSpecialConstraint.REFERENCE_TYPE -> 4
                    DotNetGenericOwnerPhysicalGenericParameterSpecialConstraint.NON_NULLABLE_VALUE_TYPE -> 8
                    DotNetGenericOwnerPhysicalGenericParameterSpecialConstraint.DEFAULT_CONSTRUCTOR -> 16
                }
            }
        }
        val constraints = owner.physicalGenericParameters.map { parameter ->
            strings(parameter.typeConstraints.map { constraint -> constraint.renderMetadataSignatureType() })
        }
        val isAbstract = owner.physicalDispatch == DotNetGenericOwnerPhysicalTypeDispatch.ABSTRACT ||
                owner.physicalDispatch == DotNetGenericOwnerPhysicalTypeDispatch.SEALED
        val isSealed = owner.physicalDispatch == DotNetGenericOwnerPhysicalTypeDispatch.FINAL
        """
        CheckOwner(
            reader,
            ${owner.physicalOwnerPath.dropLast(1).joinToString(".").csharpLiteral()},
            ${(owner.physicalOwnerPath.last() + "`" + owner.genericArity).csharpLiteral()},
            ${owner.physicalVisibility == DotNetGenericOwnerPhysicalTypeVisibility.PUBLIC},
            $isAbstract,
            $isSealed,
            ${baseType.csharpLiteral()},
            ${nullableFlags(baseEdge.nullableReferenceFlags)},
            ${strings(directInterfaceEdges.map { supertype ->
                supertype.physicalType.renderMetadataSignatureType()
            })},
            ${nullableFlagLists(directInterfaceEdges.map { supertype ->
                supertype.nullableReferenceFlags
            })},
            new int[] { ${owner.physicalGenericParameters.joinToString(", ") { parameter -> parameter.index.toString() }} },
            new int[] { ${specialConstraints.joinToString(", ")} },
            new string[][] { ${constraints.joinToString(", ")} },
            new ExpectedField[] { ${fields.joinToString(",\n")} },
            new ExpectedProperty[] { ${properties.joinToString(",\n")} },
            new ExpectedMethod[] { ${methods.joinToString(",\n")} },
            new ExpectedMethodImpl[] { ${methodImpls.joinToString(",\n")} }
        );
        """.trimIndent()
    }
    val capabilityChecks = artifact.owners.joinToString("\n") { owner ->
        val capabilityPath = checkNotNull(owner.physicalCapabilityOwnerPath)
        val methods = owner.members.flatMap { member -> member.slots }
            .mapNotNull { slot -> slot.capabilitySlot }
            .distinct()
            .map { identity ->
                methodExpectation(
                    identity,
                    "MethodAttributes.Public",
                    isAbstract = true,
                    isVirtual = true,
                    isFinal = false,
                )
            }
        "CheckCapability(reader, " +
                "${capabilityPath.dropLast(1).joinToString(".").csharpLiteral()}, " +
                "${capabilityPath.last().csharpLiteral()}, " +
                "new ExpectedMethod[] { ${methods.joinToString(",\n")} });"
    }
    val targetTypeNames = artifact.owners.flatMap { owner ->
        listOf(
            owner.physicalOwnerPath.dropLast(1).joinToString(".") + "." +
                    owner.physicalOwnerPath.last() + "`" + owner.genericArity,
            checkNotNull(owner.physicalCapabilityOwnerPath).joinToString("."),
        )
    }.sorted()
    val compilerSupportTypeNames = when (artifact.targetProfile) {
        DotNetGenericOwnerPhysicalTargetProfile.NET48 -> listOf(
            "Microsoft.CodeAnalysis.EmbeddedAttribute",
            "System.Runtime.CompilerServices.NullableAttribute",
            "System.Runtime.CompilerServices.NullableContextAttribute",
            "System.Runtime.CompilerServices.RefSafetyRulesAttribute",
        )
        DotNetGenericOwnerPhysicalTargetProfile.NET10_0 -> emptyList()
        DotNetGenericOwnerPhysicalTargetProfile.NETSTANDARD_2_0 ->
            error("The OctoTree metadata inspector has no netstandard product")
    }
    val expectedAssemblyTypeNames = (targetTypeNames + compilerSupportTypeNames).sorted()
    val targetNamespaces = artifact.owners.flatMap { owner ->
        listOf(
            owner.physicalOwnerPath.dropLast(1).joinToString("."),
            checkNotNull(owner.physicalCapabilityOwnerPath).dropLast(1).joinToString("."),
        )
    }.distinct()
    check(targetNamespaces.size == 1) {
        "The bounded OctoTree metadata inspector requires one physical namespace"
    }
    val targetNamespacePrefix = targetNamespaces.single() + "."

    return """
        using System;
        using System.Collections.Generic;
        using System.Collections.Immutable;
        using System.IO;
        using System.Linq;
        using System.Reflection;
        using System.Reflection.Metadata;
        using System.Reflection.PortableExecutable;

        public static class Program
        {
            private sealed class ExpectedField
            {
                internal readonly string Name;
                internal readonly string Type;
                internal readonly byte[] NullableFlags;
                internal readonly bool IsInitOnly;
                internal ExpectedField(string name, string type, byte[] nullableFlags, bool isInitOnly)
                {
                    Name = name; Type = type; NullableFlags = nullableFlags; IsInitOnly = isInitOnly;
                }
            }

            private sealed class ExpectedMethod
            {
                internal readonly string Name;
                internal readonly string ReturnType;
                internal readonly byte[] ReturnNullableFlags;
                internal readonly string[] ParameterTypes;
                internal readonly byte[][] ParameterNullableFlags;
                internal readonly MethodAttributes Visibility;
                internal readonly bool IsStatic;
                internal readonly bool IsAbstract;
                internal readonly bool IsVirtual;
                internal readonly bool IsFinal;
                internal ExpectedMethod(
                    string name,
                    string returnType,
                    byte[] returnNullableFlags,
                    string[] parameterTypes,
                    byte[][] parameterNullableFlags,
                    MethodAttributes visibility,
                    bool isStatic,
                    bool isAbstract,
                    bool isVirtual,
                    bool isFinal)
                {
                    Name = name;
                    ReturnType = returnType;
                    ReturnNullableFlags = returnNullableFlags;
                    ParameterTypes = parameterTypes;
                    ParameterNullableFlags = parameterNullableFlags;
                    Visibility = visibility;
                    IsStatic = isStatic;
                    IsAbstract = isAbstract;
                    IsVirtual = isVirtual;
                    IsFinal = isFinal;
                }
            }

            private sealed class ExpectedProperty
            {
                internal readonly string Name;
                internal readonly string Type;
                internal readonly byte[] NullableFlags;
                internal readonly string Getter;
                internal readonly string Setter;
                internal ExpectedProperty(
                    string name, string type, byte[] nullableFlags, string getter, string setter)
                {
                    Name = name; Type = type; NullableFlags = nullableFlags; Getter = getter; Setter = setter;
                }
            }

            private sealed class ExpectedMethodImpl
            {
                internal readonly string Declaration;
                internal readonly string Body;
                internal ExpectedMethodImpl(string declaration, string body)
                {
                    Declaration = declaration; Body = body;
                }
            }

            private sealed class SignatureTypeProvider : ISignatureTypeProvider<string, object>
            {
                public string GetArrayType(string elementType, ArrayShape shape) => elementType + "[array]";
                public string GetByReferenceType(string elementType) => elementType + "&";
                public string GetFunctionPointerType(MethodSignature<string> signature) => "fnptr";
                public string GetGenericInstantiation(string genericType, ImmutableArray<string> typeArguments) =>
                    genericType + "<" + string.Join(",", typeArguments) + ">";
                public string GetGenericMethodParameter(object context, int index) => "!!" + index;
                public string GetGenericTypeParameter(object context, int index) => "!" + index;
                public string GetModifiedType(string modifier, string unmodifiedType, bool isRequired) => unmodifiedType;
                public string GetPinnedType(string elementType) => elementType;
                public string GetPointerType(string elementType) => elementType + "*";
                public string GetPrimitiveType(PrimitiveTypeCode typeCode)
                {
                    switch (typeCode)
                    {
                        case PrimitiveTypeCode.Boolean: return "System.Boolean";
                        case PrimitiveTypeCode.Int32: return "System.Int32";
                        case PrimitiveTypeCode.Object: return "System.Object";
                        case PrimitiveTypeCode.String: return "System.String";
                        case PrimitiveTypeCode.Void: return "System.Void";
                        default: return "primitive:" + typeCode;
                    }
                }
                public string GetSZArrayType(string elementType) => elementType + "[]";
                public string GetTypeFromDefinition(
                    MetadataReader reader, TypeDefinitionHandle handle, byte rawTypeKind) => TypeName(reader, handle);
                public string GetTypeFromReference(
                    MetadataReader reader, TypeReferenceHandle handle, byte rawTypeKind) => TypeName(reader, handle);
                public string GetTypeFromSpecification(
                    MetadataReader reader, object context, TypeSpecificationHandle handle, byte rawTypeKind) =>
                    reader.GetTypeSpecification(handle).DecodeSignature(this, context);
            }

            private static readonly SignatureTypeProvider TypeProvider = new SignatureTypeProvider();

            private static string JoinName(string ns, string name) =>
                string.IsNullOrEmpty(ns) ? name : ns + "." + name;

            private static string TypeName(MetadataReader reader, TypeDefinitionHandle handle)
            {
                TypeDefinition definition = reader.GetTypeDefinition(handle);
                return JoinName(reader.GetString(definition.Namespace), reader.GetString(definition.Name));
            }

            private static string TypeName(MetadataReader reader, TypeReferenceHandle handle)
            {
                TypeReference reference = reader.GetTypeReference(handle);
                return JoinName(reader.GetString(reference.Namespace), reader.GetString(reference.Name));
            }

            private static string TypeName(MetadataReader reader, EntityHandle handle)
            {
                if (handle.Kind == HandleKind.TypeDefinition)
                    return TypeName(reader, (TypeDefinitionHandle)handle);
                if (handle.Kind == HandleKind.TypeReference)
                    return TypeName(reader, (TypeReferenceHandle)handle);
                if (handle.Kind == HandleKind.TypeSpecification)
                    return reader.GetTypeSpecification((TypeSpecificationHandle)handle)
                        .DecodeSignature(TypeProvider, null);
                throw new InvalidOperationException("Unsupported type handle " + handle.Kind);
            }

            private static TypeDefinitionHandle FindType(MetadataReader reader, string ns, string name)
            {
                TypeDefinitionHandle[] matches = reader.TypeDefinitions.Where(handle =>
                {
                    TypeDefinition definition = reader.GetTypeDefinition(handle);
                    return reader.GetString(definition.Namespace) == ns && reader.GetString(definition.Name) == name;
                }).ToArray();
                if (matches.Length != 1)
                    throw new InvalidOperationException("Expected one TypeDef " + JoinName(ns, name));
                return matches[0];
            }

            private static string MethodName(MetadataReader reader, EntityHandle handle)
            {
                if (handle.Kind == HandleKind.MethodDefinition)
                    return reader.GetString(reader.GetMethodDefinition((MethodDefinitionHandle)handle).Name);
                if (handle.Kind == HandleKind.MemberReference)
                    return reader.GetString(reader.GetMemberReference((MemberReferenceHandle)handle).Name);
                throw new InvalidOperationException("Unsupported method handle " + handle.Kind);
            }

            private static TypeDefinitionHandle DeclaringType(
                MetadataReader reader, MethodDefinitionHandle methodHandle)
            {
                foreach (TypeDefinitionHandle typeHandle in reader.TypeDefinitions)
                {
                    if (reader.GetTypeDefinition(typeHandle).GetMethods().Contains(methodHandle)) return typeHandle;
                }
                throw new InvalidOperationException("MethodDef has no declaring TypeDef");
            }

            private static string AttributeTypeName(MetadataReader reader, CustomAttribute attribute)
            {
                if (attribute.Constructor.Kind == HandleKind.MemberReference)
                {
                    MemberReference constructor = reader.GetMemberReference(
                        (MemberReferenceHandle)attribute.Constructor);
                    return TypeName(reader, constructor.Parent);
                }
                if (attribute.Constructor.Kind == HandleKind.MethodDefinition)
                {
                    return TypeName(reader, DeclaringType(
                        reader, (MethodDefinitionHandle)attribute.Constructor));
                }
                throw new InvalidOperationException(
                    "Unsupported custom-attribute constructor " + attribute.Constructor.Kind);
            }

            private static byte[] DecodeNullableTransform(
                MetadataReader reader, CustomAttribute attribute)
            {
                BlobReader blob = reader.GetBlobReader(attribute.Value);
                if (blob.ReadUInt16() != 1) throw new InvalidOperationException("Invalid custom-attribute prolog");
                if (blob.RemainingBytes == 3)
                {
                    byte scalar = blob.ReadByte();
                    if (blob.ReadUInt16() != 0 || blob.RemainingBytes != 0)
                        throw new InvalidOperationException("Invalid scalar nullable transform");
                    return new byte[] { scalar };
                }
                int count = blob.ReadInt32();
                if (count < 0 || blob.RemainingBytes != count + 2)
                    throw new InvalidOperationException("Invalid nullable transform vector");
                byte[] values = blob.ReadBytes(count);
                if (blob.ReadUInt16() != 0 || blob.RemainingBytes != 0)
                    throw new InvalidOperationException("Invalid nullable transform suffix");
                return values;
            }

            private static byte[] LocalNullableTransform(
                MetadataReader reader, EntityHandle handle, string attributeType)
            {
                if (handle.IsNil) return null;
                CustomAttribute[] matches = reader.GetCustomAttributes(handle)
                    .Select(reader.GetCustomAttribute)
                    .Where(attribute => AttributeTypeName(reader, attribute) == attributeType)
                    .ToArray();
                if (matches.Length > 1)
                    throw new InvalidOperationException("Duplicate " + attributeType + " on " + handle.Kind);
                return matches.Length == 0 ? null : DecodeNullableTransform(reader, matches[0]);
            }

            private static byte[] EffectiveNullableTransform(
                MetadataReader reader,
                EntityHandle position,
                int transformCount,
                MethodDefinitionHandle methodHandle,
                TypeDefinitionHandle typeHandle)
            {
                if (transformCount == 0) return new byte[0];
                byte[] local = LocalNullableTransform(
                    reader, position, "System.Runtime.CompilerServices.NullableAttribute");
                if (local != null)
                {
                    if (local.Length == 1) return Enumerable.Repeat(local[0], transformCount).ToArray();
                    if (local.Length == transformCount) return local;
                    throw new InvalidOperationException("Nullable transform has the wrong structural length");
                }
                byte[] context = methodHandle.IsNil ? null : LocalNullableTransform(
                    reader, methodHandle, "System.Runtime.CompilerServices.NullableContextAttribute");
                if (context == null)
                {
                    context = LocalNullableTransform(
                        reader, typeHandle, "System.Runtime.CompilerServices.NullableContextAttribute");
                }
                byte fallback = context == null ? (byte)0 : context.Single();
                return Enumerable.Repeat(fallback, transformCount).ToArray();
            }

            private static void CheckNullableTransform(
                MetadataReader reader,
                EntityHandle position,
                byte[] expected,
                MethodDefinitionHandle methodHandle,
                TypeDefinitionHandle typeHandle,
                string description)
            {
                byte[] actual = EffectiveNullableTransform(
                    reader, position, expected.Length, methodHandle, typeHandle);
                if (!actual.SequenceEqual(expected))
                    throw new InvalidOperationException(
                        "Nullable transform differs for " + description + ": expected " +
                        string.Join(",", expected) + ", actual " + string.Join(",", actual));
            }

            private static void CheckMethods(
                MetadataReader reader,
                TypeDefinitionHandle typeHandle,
                TypeDefinition definition,
                ExpectedMethod[] expected)
            {
                MethodDefinitionHandle[] actual = definition.GetMethods().ToArray();
                if (actual.Length != expected.Length)
                    throw new InvalidOperationException(
                        "MethodDef count differs: expected " + expected.Length + ", actual " + actual.Length +
                        "; expected rows " + string.Join(",", expected.Select(item => item.Name)) +
                        "; actual rows " + string.Join(",", actual.Select(handle =>
                            reader.GetString(reader.GetMethodDefinition(handle).Name))));
                var remaining = new List<MethodDefinitionHandle>(actual);
                foreach (ExpectedMethod item in expected)
                {
                    MethodDefinitionHandle[] matches = remaining.Where(handle =>
                    {
                        MethodDefinition method = reader.GetMethodDefinition(handle);
                        if (reader.GetString(method.Name) != item.Name) return false;
                        MethodSignature<string> signature = method.DecodeSignature(TypeProvider, null);
                        return signature.ReturnType == item.ReturnType &&
                            signature.ParameterTypes.SequenceEqual(item.ParameterTypes);
                    }).ToArray();
                    if (matches.Length != 1)
                        throw new InvalidOperationException("Expected one exact MethodDef " + item.Name);
                    MethodDefinitionHandle selectedHandle = matches[0];
                    MethodDefinition selected = reader.GetMethodDefinition(selectedHandle);
                    MethodAttributes attributes = selected.Attributes;
                    if ((attributes & MethodAttributes.MemberAccessMask) != item.Visibility ||
                        ((attributes & MethodAttributes.Static) != 0) != item.IsStatic ||
                        ((attributes & MethodAttributes.Abstract) != 0) != item.IsAbstract ||
                        ((attributes & MethodAttributes.Virtual) != 0) != item.IsVirtual ||
                        ((attributes & MethodAttributes.Final) != 0) != item.IsFinal)
                        throw new InvalidOperationException("MethodDef flags differ for " + item.Name + ": " + attributes);
                    ParameterHandle[] parameterHandles = selected.GetParameters().ToArray();
                    ParameterHandle returnHandle = parameterHandles.SingleOrDefault(handle =>
                        reader.GetParameter(handle).SequenceNumber == 0);
                    CheckNullableTransform(
                        reader,
                        returnHandle,
                        item.ReturnNullableFlags,
                        selectedHandle,
                        typeHandle,
                        item.Name + " return");
                    if (item.ParameterNullableFlags.Length != item.ParameterTypes.Length)
                        throw new InvalidOperationException("Expected parameter nullable shape is incomplete");
                    for (int parameterIndex = 0; parameterIndex < item.ParameterNullableFlags.Length; parameterIndex++)
                    {
                        int sequence = parameterIndex + 1;
                        ParameterHandle parameterHandle = parameterHandles.SingleOrDefault(handle =>
                            reader.GetParameter(handle).SequenceNumber == sequence);
                        CheckNullableTransform(
                            reader,
                            parameterHandle,
                            item.ParameterNullableFlags[parameterIndex],
                            selectedHandle,
                            typeHandle,
                            item.Name + " parameter " + sequence);
                    }
                    remaining.Remove(selectedHandle);
                }
                if (remaining.Count != 0)
                    throw new InvalidOperationException("Unexpected MethodDef rows remain");
            }

            private static void CheckOwner(
                MetadataReader reader,
                string ns,
                string name,
                bool isPublic,
                bool isAbstract,
                bool isSealed,
                string baseType,
                byte[] baseNullableFlags,
                string[] directInterfaces,
                byte[][] directInterfaceNullableFlags,
                int[] genericParameterIndices,
                int[] genericParameterAttributes,
                string[][] genericParameterConstraints,
                ExpectedField[] expectedFields,
                ExpectedProperty[] expectedProperties,
                ExpectedMethod[] expectedMethods,
                ExpectedMethodImpl[] expectedMethodImpls)
            {
                TypeDefinitionHandle handle = FindType(reader, ns, name);
                TypeDefinition definition = reader.GetTypeDefinition(handle);
                TypeAttributes attributes = definition.Attributes;
                if (((attributes & TypeAttributes.VisibilityMask) == TypeAttributes.Public) != isPublic ||
                    ((attributes & TypeAttributes.Abstract) != 0) != isAbstract ||
                    ((attributes & TypeAttributes.Sealed) != 0) != isSealed ||
                    (attributes & TypeAttributes.Interface) != 0 || TypeName(reader, definition.BaseType) != baseType)
                    throw new InvalidOperationException("TypeDef row differs for " + JoinName(ns, name));
                CheckNullableTransform(
                    reader,
                    handle,
                    baseNullableFlags,
                    default(MethodDefinitionHandle),
                    handle,
                    JoinName(ns, name) + " BaseType");

                GenericParameterHandle[] parameters = definition.GetGenericParameters().ToArray();
                if (parameters.Length != genericParameterIndices.Length ||
                    parameters.Length != genericParameterAttributes.Length ||
                    parameters.Length != genericParameterConstraints.Length)
                    throw new InvalidOperationException("GenericParam count differs for " + JoinName(ns, name));
                for (int index = 0; index < parameters.Length; index++)
                {
                    GenericParameter parameter = reader.GetGenericParameter(parameters[index]);
                    string[] constraints = parameter.GetConstraints().Select(constraint =>
                        TypeName(reader, reader.GetGenericParameterConstraint(constraint).Type)).ToArray();
                    if (parameter.Index != genericParameterIndices[index] ||
                        (int)parameter.Attributes != genericParameterAttributes[index] ||
                        !constraints.SequenceEqual(genericParameterConstraints[index]))
                        throw new InvalidOperationException("GenericParam row differs for " + JoinName(ns, name));
                }

                InterfaceImplementationHandle[] interfaces = definition.GetInterfaceImplementations().ToArray();
                if (interfaces.Length != directInterfaces.Length ||
                    directInterfaces.Length != directInterfaceNullableFlags.Length)
                    throw new InvalidOperationException("InterfaceImpl row differs for " + JoinName(ns, name));
                for (int interfaceIndex = 0; interfaceIndex < directInterfaces.Length; interfaceIndex++)
                {
                    InterfaceImplementationHandle[] matches = interfaces.Where(interfaceHandle =>
                        TypeName(reader, reader.GetInterfaceImplementation(interfaceHandle).Interface) ==
                            directInterfaces[interfaceIndex]).ToArray();
                    if (matches.Length != 1)
                        throw new InvalidOperationException(
                            "Expected one exact InterfaceImpl " + directInterfaces[interfaceIndex]);
                    CheckNullableTransform(
                        reader,
                        matches[0],
                        directInterfaceNullableFlags[interfaceIndex],
                        default(MethodDefinitionHandle),
                        handle,
                        JoinName(ns, name) + " InterfaceImpl " + directInterfaces[interfaceIndex]);
                }

                FieldDefinitionHandle[] fields = definition.GetFields().ToArray();
                if (fields.Length != expectedFields.Length)
                    throw new InvalidOperationException("Field row count differs for " + JoinName(ns, name));
                foreach (ExpectedField item in expectedFields)
                {
                    FieldDefinitionHandle[] matches = fields.Where(fieldHandle =>
                    {
                        FieldDefinition field = reader.GetFieldDefinition(fieldHandle);
                        return reader.GetString(field.Name) == item.Name &&
                            field.DecodeSignature(TypeProvider, null) == item.Type &&
                            (field.Attributes & FieldAttributes.FieldAccessMask) == FieldAttributes.Private &&
                            ((field.Attributes & FieldAttributes.InitOnly) != 0) == item.IsInitOnly;
                    }).ToArray();
                    if (matches.Length != 1)
                        throw new InvalidOperationException("Field row differs for " + item.Name);
                    CheckNullableTransform(
                        reader,
                        matches[0],
                        item.NullableFlags,
                        default(MethodDefinitionHandle),
                        handle,
                        item.Name + " field");
                }

                PropertyDefinitionHandle[] properties = definition.GetProperties().ToArray();
                if (properties.Length != expectedProperties.Length)
                    throw new InvalidOperationException(
                        "Property row count differs for " + JoinName(ns, name) +
                        ": expected " + expectedProperties.Length + ", actual " + properties.Length);
                foreach (ExpectedProperty item in expectedProperties)
                {
                    PropertyDefinitionHandle[] matches = properties.Where(propertyHandle =>
                    {
                        PropertyDefinition property = reader.GetPropertyDefinition(propertyHandle);
                        MethodSignature<string> signature = property.DecodeSignature(TypeProvider, null);
                        PropertyAccessors accessors = property.GetAccessors();
                        string getter = accessors.Getter.IsNil ? null :
                            reader.GetString(reader.GetMethodDefinition(accessors.Getter).Name);
                        string setter = accessors.Setter.IsNil ? null :
                            reader.GetString(reader.GetMethodDefinition(accessors.Setter).Name);
                        return reader.GetString(property.Name) == item.Name &&
                            property.Attributes == PropertyAttributes.None &&
                            signature.ReturnType == item.Type && signature.ParameterTypes.Length == 0 &&
                            getter == item.Getter && setter == item.Setter && accessors.Others.Length == 0;
                    }).ToArray();
                    if (matches.Length != 1)
                        throw new InvalidOperationException("Property/MethodSemantics rows differ for " + item.Name);
                    CheckNullableTransform(
                        reader,
                        matches[0],
                        item.NullableFlags,
                        default(MethodDefinitionHandle),
                        handle,
                        item.Name + " property");
                }

                CheckMethods(reader, handle, definition, expectedMethods);
                MethodImplementationHandle[] implementations = definition.GetMethodImplementations().ToArray();
                if (implementations.Length != expectedMethodImpls.Length)
                    throw new InvalidOperationException("MethodImpl count differs for " + JoinName(ns, name));
                var pairs = implementations.Select(implementationHandle =>
                {
                    MethodImplementation implementation = reader.GetMethodImplementation(implementationHandle);
                    return MethodName(reader, implementation.MethodDeclaration) + "|" +
                        MethodName(reader, implementation.MethodBody);
                }).OrderBy(value => value).ToArray();
                string[] expectedPairs = expectedMethodImpls.Select(item => item.Declaration + "|" + item.Body)
                    .OrderBy(value => value).ToArray();
                if (!pairs.SequenceEqual(expectedPairs))
                    throw new InvalidOperationException("MethodImpl rows differ for " + JoinName(ns, name));
            }

            private static void CheckCapability(
                MetadataReader reader,
                string ns,
                string name,
                ExpectedMethod[] expectedMethods)
            {
                TypeDefinitionHandle handle = FindType(reader, ns, name);
                TypeDefinition definition = reader.GetTypeDefinition(handle);
                TypeAttributes attributes = definition.Attributes;
                if ((attributes & TypeAttributes.VisibilityMask) != TypeAttributes.Public ||
                    (attributes & TypeAttributes.Interface) == 0 ||
                    (attributes & TypeAttributes.Abstract) == 0 ||
                    definition.GetGenericParameters().Count != 0 ||
                    definition.GetFields().Count != 0 ||
                    definition.GetInterfaceImplementations().Count != 0 ||
                    definition.GetMethodImplementations().Count != 0)
                    throw new InvalidOperationException("Capability TypeDef row differs for " + JoinName(ns, name));
                CheckMethods(reader, handle, definition, expectedMethods);
            }

            public static int Main()
            {
                using (FileStream stream = File.OpenRead(${producer.absolutePath.csharpLiteral()}))
                using (var peReader = new PEReader(stream))
                {
                    if (!peReader.HasMetadata) throw new InvalidOperationException("Candidate has no CLR metadata");
                    MetadataReader reader = peReader.GetMetadataReader();
                    string[] expectedTypes = ${strings(targetTypeNames)};
                    string[] expectedAssemblyTypes = ${strings(expectedAssemblyTypeNames)};
                    string[] actualAssemblyTypes = reader.TypeDefinitions
                        .Select(handle => TypeName(reader, handle))
                        .Where(name => name != "<Module>")
                        .OrderBy(name => name, StringComparer.Ordinal).ToArray();
                    if (!actualAssemblyTypes.SequenceEqual(expectedAssemblyTypes))
                        throw new InvalidOperationException(
                            "The candidate contains an unexpected TypeDef outside the physical family: " +
                            string.Join(",", actualAssemblyTypes));
                    string[] actualTypes = reader.TypeDefinitions.Select(handle => TypeName(reader, handle))
                        .Where(name => name.StartsWith(
                            ${targetNamespacePrefix.csharpLiteral()}, StringComparison.Ordinal))
                        .OrderBy(name => name, StringComparer.Ordinal).ToArray();
                    if (!actualTypes.SequenceEqual(expectedTypes))
                        throw new InvalidOperationException(
                            "The physical family TypeDef set differs: expected " +
                            string.Join(",", expectedTypes) + "; actual " + string.Join(",", actualTypes));

                    $ownerChecks
                    $capabilityChecks
                }
                return 0;
            }
        }
    """.trimIndent()
}

private data class SnapshotCSharpCompilation(
    val exitCode: Int,
    val output: String,
)

private fun compileFrameworkSnapshotCSharp(
    frameworkCompiler: File,
    source: File,
    output: File,
    references: List<File>,
    executable: Boolean,
    warningsAsErrors: Boolean = false,
    analyzers: List<File> = emptyList(),
    generatedFilesDirectory: File? = null,
): SnapshotCSharpCompilation {
    output.delete()
    val toolchain = checkNotNull(DotNetIlAssembler.findModernCSharpCompiler()) {
        "Modern Roslyn is required for deterministic Framework snapshot compilation"
    }
    val frameworkReferences = listOf("mscorlib.dll", "System.dll", "System.Core.dll").map { name ->
        frameworkCompiler.parentFile.resolve(name).also { reference ->
            check(reference.isFile) { "Framework reference assembly is missing: ${reference.path}" }
        }
    }
    return runSnapshotCompiler(buildList {
        add(toolchain.dotNetHost.path)
        add(toolchain.compiler.path)
        add("/nologo")
        add("/noconfig")
        add("/nostdlib+")
        add("/deterministic+")
        if (warningsAsErrors) add("/warnaserror+")
        add("/target:${if (executable) "exe" else "library"}")
        add("/out:${output.path}")
        frameworkReferences.forEach { reference -> add("/reference:${reference.path}") }
        references.forEach { reference -> add("/reference:${reference.path}") }
        analyzers.forEach { analyzer -> add("/analyzer:${analyzer.path}") }
        generatedFilesDirectory?.let { directory ->
            directory.mkdirs()
            add("/generatedfilesout:${directory.path}")
        }
        add(source.path)
    }, output.parentFile)
}

private fun compileModernSnapshotCSharp(
    toolchain: org.jetbrains.kotlin.backend.dotnet.DotNetModernCSharpToolchain,
    source: File,
    output: File,
    references: List<File>,
    executable: Boolean,
    warningsAsErrors: Boolean = false,
    analyzers: List<File> = emptyList(),
    generatedFilesDirectory: File? = null,
): SnapshotCSharpCompilation {
    output.delete()
    val frameworkReferences = toolchain.referenceDirectory.listFiles { file ->
        file.isFile && file.extension.equals("dll", ignoreCase = true)
    }?.sortedBy(File::getName) ?: error("Unreadable modern reference pack: ${toolchain.referenceDirectory}")
    return runSnapshotCompiler(buildList {
        add(toolchain.dotNetHost.path)
        add(toolchain.compiler.path)
        add("/nologo")
        add("/noconfig")
        add("/nostdlib+")
        add("/deterministic+")
        if (warningsAsErrors) add("/warnaserror+")
        add("/target:${if (executable) "exe" else "library"}")
        add("/out:${output.path}")
        frameworkReferences.forEach { reference -> add("/reference:${reference.path}") }
        references.forEach { reference -> add("/reference:${reference.path}") }
        analyzers.forEach { analyzer -> add("/analyzer:${analyzer.path}") }
        generatedFilesDirectory?.let { directory ->
            directory.mkdirs()
            add("/generatedfilesout:${directory.path}")
        }
        add(source.path)
    }, output.parentFile)
}

private fun runSnapshotCompiler(arguments: List<String>, directory: File): SnapshotCSharpCompilation {
    val process = ProcessBuilder(arguments)
        .directory(directory)
        .redirectErrorStream(true)
        .start()
    check(process.waitFor(3, TimeUnit.MINUTES)) {
        process.destroyForcibly()
        "C# snapshot physicalizer timed out"
    }
    val output = process.inputStream.bufferedReader().use { it.readText() }
    return SnapshotCSharpCompilation(process.exitValue(), output)
}

private fun executeSnapshotConsumer(target: DotNetTarget, assembly: File, directory: File) {
    val command = when (target) {
        DotNetTarget.NET48 -> {
            val host = checkNotNull(DotNetIlAssembler.findFrameworkPowerShellHost())
            val escapedAssembly = assembly.absolutePath.replace("'", "''")
            val script = """
                ${'$'}ErrorActionPreference = 'Stop'
                try {
                    ${'$'}assembly = [Reflection.Assembly]::LoadFrom('$escapedAssembly')
                    ${'$'}arguments = ${'$'}null
                    if (${'$'}assembly.EntryPoint.GetParameters().Length -ne 0) {
                        ${'$'}arguments = New-Object 'System.Object[]' 1
                        ${'$'}arguments[0] = [string[]]@()
                    }
                    ${'$'}result = ${'$'}assembly.EntryPoint.Invoke(${'$'}null, ${'$'}arguments)
                    if ([int]${'$'}result -ne 0) { exit [int]${'$'}result }
                } catch {
                    [Console]::Error.WriteLine(${'$'}_.Exception.ToString())
                    exit 1
                }
            """.trimIndent()
            listOf(host.path, "-NoLogo", "-NoProfile", "-NonInteractive", "-Command", script)
        }
        DotNetTarget.NET10_0 -> {
            assembly.resolveSibling("${assembly.nameWithoutExtension}.runtimeconfig.json").writeText(
                """
                {
                  "runtimeOptions": {
                    "tfm": "net10.0",
                    "framework": {
                      "name": "Microsoft.NETCore.App",
                      "version": "10.0.0"
                    },
                    "rollForward": "LatestMinor"
                  }
                }
                """.trimIndent()
            )
            val host = checkNotNull(DotNetIlAssembler.findModernDotNetHost())
            listOf(host.path, "exec", assembly.path)
        }
        DotNetTarget.NETSTANDARD_2_0 -> error("netstandard2.0 has no executable snapshot consumer")
    }
    val process = ProcessBuilder(command)
        .directory(directory)
        .redirectErrorStream(true)
        .start()
    check(process.waitFor(3, TimeUnit.MINUTES)) {
        process.destroyForcibly()
        "Generic-owner snapshot consumer timed out"
    }
    val output = process.inputStream.bufferedReader().use { it.readText() }
    check(process.exitValue() == 0) {
        "Generic-owner snapshot consumer failed with ${process.exitValue()}: $output"
    }
}

private class DotNetEnvironmentConfigurator(
    testServices: TestServices,
    private val outputExtension: String,
    private val target: DotNetTarget,
) : EnvironmentConfigurator(testServices) {
    /**
     * The injected fake stdlib sources declare `package kotlin.io` and `package kotlin`, and
     * besides permitting the package names, [AnalysisFlags.allowKotlinPackage] makes the default
     * star imports (`kotlin.*`, `kotlin.io.*`) look at source-declared symbols, so `println` and
     * `Char.code` resolve without an explicit import. Mirrors
     * `K2DotNetCompilerArgumentsConfigurator` on the CLI side.
     * The compiler-owned Common stdlib headers additionally opt in through the wrapped language
     * settings below, preserving any test-declared opt-ins rather than replacing their list.
     * (TODO: this also allows test code in `kotlin.*`.)
     */
    override fun provideAdditionalAnalysisFlags(
        directives: RegisteredDirectives,
        languageVersion: LanguageVersion,
    ): Map<AnalysisFlag<*>, Any?> {
        // Selected upstream tests receive narrow kotlin.test/kotlin.text helpers from the
        // additional-source provider. This permission is test-source policy and is independent
        // of whether the platform library is consumed as a DLL or produced from source.
        return mapOf(AnalysisFlags.allowKotlinPackage to true)
    }

    override fun configureCompilerConfiguration(configuration: CompilerConfiguration, module: TestModule) {
        if (!module.targetPlatform(testServices).isDotNet()) return

        val artifactName = getArtifactName(module)
        val producesStdlibFromSource = DotNetCodegenDirectives.DOTNET_STDLIB_FROM_SOURCE in module.directives
        configuration.put(CLIConfigurationKeys.ALLOW_KOTLIN_PACKAGE, true)
        configuration.put(CommonConfigurationKeys.MODULE_NAME, module.name)
        configuration.targetPlatform = DotNetPlatforms.defaultDotNetPlatform
        configuration.dotNetAssemblyName = artifactName
        configuration.dotNetProducesLibrary = isLibraryModule(module)
        configuration.dotNetMemberReflection =
            DotNetCodegenDirectives.DOTNET_MEMBER_REFLECTION in module.directives
        configuration.dotNetExports = module.directives[DotNetCodegenDirectives.DOTNET_EXPORT]
            .map(DotNetExport::parse)
        configuration.dotNetPropertyExports = module.directives[DotNetCodegenDirectives.DOTNET_EXPORT_PROPERTY]
            .map(DotNetPropertyExport::parse)
        configuration.dotNetOutput = getConfiguredOutput(module, artifactName)
        configuration.dotNetTarget = target
        // KLIB source identities must not retain the test framework's random temporary root.
        // Besides making embedded library metadata reproducible, this matches the public
        // -Xklib-relative-path-base contract used by the other KLIB-producing backends.
        configuration.klibRelativePathBases = listOf(
            testServices.sourceFileProvider.getKotlinSourceDirectoryForModule(module).canonicalPath,
        )
        // Match the KLIB test environments: a selected binary library's regular dependency
        // closure is part of the compiler classpath. Inline bodies may refer to declarations in
        // that closure even when the consuming source names only the immediate library.
        val binaryLibraries = buildList {
            addAll(module.transitiveRegularDependencies(reverseOrder = true) { it.kind == DependencyKind.Binary })
            addAll(module.transitiveFriendDependencies(reverseOrder = true) { it.kind == DependencyKind.Binary })
        }.distinct()
        for (dependencyModule in binaryLibraries) {
            val dependencyOutput = getProducedAssembly(dependencyModule, getArtifactName(dependencyModule))
            check(dependencyOutput.isFile) { "Missing compiled test dependency: ${dependencyOutput.path}" }
            configuration.addDotNetClasspathRoot(dependencyOutput)
        }
        configuration.dotNetFriendPaths = module.friendDependencies
            .filter { dependency -> dependency.kind == DependencyKind.Binary }
            .map { dependency ->
                val dependencyModule = dependency.dependencyModule
                getProducedAssembly(dependencyModule, getArtifactName(dependencyModule)).path
            }
        configuration.addSourcesForDependsOnClosure(module, testServices)
        if (producesStdlibFromSource) {
            configuration.languageVersionSettings =
                configuration.languageVersionSettings.withDotNetSourceProductSettings()
            for (stdlibSource in getOrCreateStdlibSources()) {
                configuration.addKotlinSourceRoot(
                    path = stdlibSource.canonicalPath,
                    isCommon = stdlibSource.name in DOTNET_STDLIB_COMMON_SOURCE_NAMES,
                )
            }
        } else {
            configuration.addDotNetClasspathRoot(getPrebuiltStdlib())
        }
    }

    private fun getArtifactName(module: TestModule): String {
        val testName = testServices.moduleStructure.originalTestDataFiles.first().nameWithoutExtension
        return module.name.takeUnless { it == "main" } ?: testName
    }

    private fun isLibraryModule(module: TestModule): Boolean =
        outputExtension != "il" &&
                module.files.none { file ->
                    MainFunctionForBlackBoxTestsSourceProvider.containsBoxMethod(file.originalContent)
                }

    private fun getConfiguredOutput(module: TestModule, artifactName: String): File {
        val outputDirectory = testServices.getOrCreateTempDirectory("dotnet")
        return if (isLibraryModule(module)) {
            outputDirectory.resolve("${module.name}-$artifactName-library")
        } else {
            outputDirectory.resolve("${module.name}-$artifactName.$outputExtension")
        }
    }

    private fun getProducedAssembly(module: TestModule, artifactName: String): File {
        val configuredOutput = getConfiguredOutput(module, artifactName)
        return if (isLibraryModule(module)) configuredOutput.resolve("$artifactName.dll") else configuredOutput
    }

    private fun getOrCreateStdlibSources(): List<File> =
        DOTNET_STDLIB_SOURCES.map { [fileName, source] ->
            testServices.getOrCreateTempDirectory("dotnet-stdlib")
                .resolve(DOTNET_STDLIB_SOURCE_PATHS.getValue(fileName))
                .also { file ->
                if (!file.isFile || file.readText() != source) {
                    file.parentFile.mkdirs()
                    file.writeText(source)
                }
            }
        }

    private fun getPrebuiltStdlib(): File {
        val propertyName = "kotlin.dotnet.test.platform.${target.description}.path"
        val directory = System.getProperty(propertyName)?.let(::File)
            ?: error("Missing reusable Kotlin/.NET test platform property '$propertyName'")
        val stdlib = directory.resolve(DotNetStdlibArtifact.ASSEMBLY_FILE_NAME)
        check(stdlib.isFile) { "Missing reusable Kotlin/.NET stdlib: ${stdlib.path}" }
        val runtime = directory.resolve(DotNetRuntimeArtifact.ASSEMBLY_FILE_NAME)
        check(runtime.isFile) { "Missing reusable Kotlin/.NET runtime: ${runtime.path}" }
        return stdlib
    }
}

private fun LanguageVersionSettings.withDotNetSourceProductSettings(): LanguageVersionSettings {
    val delegate = this
    return object : LanguageVersionSettings by delegate {
        override fun getFeatureSupport(feature: LanguageFeature): LanguageFeature.State =
            if (feature == LanguageFeature.MultiPlatformProjects) {
                LanguageFeature.State.ENABLED
            } else {
                delegate.getFeatureSupport(feature)
            }

        override fun supportsFeature(feature: LanguageFeature): Boolean =
            getFeatureSupport(feature) == LanguageFeature.State.ENABLED

        override fun getCustomizedLanguageFeatures(): Map<LanguageFeature, LanguageFeature.State> =
            delegate.getCustomizedLanguageFeatures() +
                    (LanguageFeature.MultiPlatformProjects to LanguageFeature.State.ENABLED)

        override fun <T> getFlag(flag: AnalysisFlag<T>): T {
            @Suppress("UNCHECKED_CAST")
            if (flag == AnalysisFlags.dontWarnOnErrorSuppression) return true as T
            @Suppress("UNCHECKED_CAST")
            if (flag == AnalysisFlags.optIn) {
                val productOptIns = listOf(
                    "kotlin.ExperimentalMultiplatform",
                    "kotlin.contracts.ExperimentalContracts",
                )
                return (delegate.getFlag(AnalysisFlags.optIn) + productOptIns).distinct() as T
            }
            return delegate.getFlag(flag)
        }
    }
}

private object DotNetCodegenDirectives : SimpleDirectivesContainer() {
    val DOTNET_MEMBER_REFLECTION by directive(
        "Emit the pre-ABI executable producer metadata consumed by Kotlin.Reflection.dll"
    )
    val DOTNET_STDLIB_FROM_SOURCE by directive(
        "Compile the compiler-owned Kotlin/.NET stdlib source product in this test instead of consuming the reusable fixture"
    )
    val DOTNET_EXPORT by stringDirective(
        "Explicit CLR function export in <kotlin-selector>=<clr-method-name> form"
    )
    val DOTNET_EXPORT_PROPERTY by stringDirective(
        "Provisional CLR property export in <kotlin-fq-name>=<clr-property-name> form"
    )
}

private class DotNetIlTextHandler(testServices: TestServices) :
    AbstractDotNetIlTextHandler(testServices, validatesCrossAssemblerCompatibility = false)

private class DotNetCrossAssemblerIlTextHandler(testServices: TestServices) :
    AbstractDotNetIlTextHandler(testServices, validatesCrossAssemblerCompatibility = true)

private abstract class AbstractDotNetIlTextHandler(
    testServices: TestServices,
    private val validatesCrossAssemblerCompatibility: Boolean,
) : DotNetBinaryArtifactHandler(testServices) {
    private val multiModuleInfoDumper = MultiModuleInfoDumper()

    override fun processModule(module: TestModule, info: BinaryArtifacts.DotNet) {
        // The backend writes the .il file as UTF-8 with a BOM (required by ilasm); the BOM is an
        // encoding artifact, not part of the IL text under test.
        val ilText = info.outputFile.readText().removePrefix("\uFEFF")
        multiModuleInfoDumper.builderForModule(module).append(ilText)

        val hasEntryPoint = Regex("(?m)^\\s*\\.entrypoint\\s*$").containsMatchIn(ilText)
        val validationDirectory =
            testServices.getOrCreateTempDirectory("dotnet-ilasm-validation")
        val validations = buildList {
            if (DotNetIlAssembler.findFrameworkIlasm() != null) {
                add(DotNetIlasmValidation("Framework", DotNetTarget.NET48))
            }
            if (validatesCrossAssemblerCompatibility && DotNetIlAssembler.findModernIlasm() != null) {
                add(DotNetIlasmValidation("modern", DotNetTarget.NET10_0))
            }
        }
        val requiredValidations = if (validatesCrossAssemblerCompatibility) 2 else 1
        if (dotNetToolchainIsRequired() && validations.size != requiredValidations) {
            val available = validations.joinToString { it.name }.ifEmpty { "none" }
            assertions.fail {
                val requirement = if (validatesCrossAssemblerCompatibility) {
                    "Both .NET Framework and modern ILAsm are required for the cross-assembler compatibility suite"
                } else {
                    ".NET Framework ILAsm is required to validate accepted net48 IL text"
                }
                "$requirement because KOTLIN_DOTNET_REQUIRE_TOOLCHAIN is enabled; available: $available"
            }
        }
        validations.forEach { validation ->
            validateAssembly(
                module,
                info,
                hasEntryPoint,
                validationDirectory,
                validation,
            )
        }
    }

    private fun validateAssembly(
        module: TestModule,
        info: BinaryArtifacts.DotNet,
        hasEntryPoint: Boolean,
        validationDirectory: File,
        validation: DotNetIlasmValidation,
    ) {
        // Modern .NET applications are dlls with an entry point and runtime config. Framework
        // applications remain exe files. The IL itself stays the net48 golden in both cases: the
        // modern pass is an assembler-compatibility oracle, not a net10 profile validation.
        val outputExtension = if (hasEntryPoint && validation.target == DotNetTarget.NET48) "exe" else "dll"
        val assembly = validationDirectory.resolve(
            "${info.outputFile.nameWithoutExtension}-${module.name}-${validation.name.lowercase()}.$outputExtension"
        )
        val assemblyMessages = DotNetIlasmMessageCollector()
        val assembled = if (hasEntryPoint) {
            DotNetIlAssembler.assembleExecutable(
                info.outputFile,
                assembly,
                validation.target,
                assemblyMessages,
            )
        } else {
            DotNetIlAssembler.assembleLibrary(
                info.outputFile,
                assembly,
                validation.target,
                assemblyMessages,
            )
        }
        if (!assembled) {
            assertions.fail {
                "Accepted net48 IL did not assemble with ${validation.name} ILAsm as a $outputExtension: " +
                        "${info.outputFile.path}\n${assemblyMessages.render()}"
            }
        }
    }

    override fun processAfterAllModules(someAssertionWasFailed: Boolean) {
        val expectedFile = testServices.moduleStructure.originalTestDataFiles.first().withExtension(".txt")
        val actual = multiModuleInfoDumper.generateResultingDump()
        if (System.getProperty("kotlin.test.update.test.data") == "true") {
            expectedFile.writeText(actual)
        }
        assertions.assertEqualsToFile(expectedFile, actual)
    }
}

private data class DotNetIlasmValidation(
    val name: String,
    val target: DotNetTarget,
)

private class DotNetIlasmMessageCollector : MessageCollector {
    private val messages = mutableListOf<String>()
    private var errorsReported = false

    override fun clear() {
        messages.clear()
        errorsReported = false
    }

    override fun report(
        severity: CompilerMessageSeverity,
        message: String,
        location: CompilerMessageSourceLocation?,
    ) {
        messages += "${severity.name}: $message"
        errorsReported = errorsReported || severity.isError
    }

    override fun hasErrors(): Boolean = errorsReported

    fun render(): String = messages.joinToString("\n").ifEmpty { "ILAsm reported no diagnostic text." }
}

private const val DOT_NET_REPRESENTATIVE_SOURCE_MARKER = "// DOTNET_REPRESENTATIVE_SOURCE:"

private data class DotNetRepresentativeSource(
    val id: String,
    val repositoryPath: String,
    val outputFileName: String,
    val requiresBenchmarkStubs: Boolean,
)

private val dotNetRepresentativeSources = listOf(
    DotNetRepresentativeSource(
        id = "array-copy",
        repositoryPath =
            "kotlin-native/performance/ring/src/commonMain/kotlin/org/jetbrains/ring/ArrayCopyBenchmark.kt",
        outputFileName = "ArrayCopyBenchmark.kt",
        requiresBenchmarkStubs = true,
    ),
    DotNetRepresentativeSource(
        id = "octo-tree",
        repositoryPath =
            "kotlin-native/performance/ring/src/commonMain/kotlin/org/jetbrains/ring/OctoTest/ocTree.kt",
        outputFileName = "ocTree.kt",
        requiresBenchmarkStubs = false,
    ),
).associateBy(DotNetRepresentativeSource::id)

private class DotNetBoxMainSourceProvider(testServices: TestServices) : AdditionalSourceProvider(testServices) {
    override fun produceAdditionalFiles(
        globalDirectives: RegisteredDirectives,
        module: TestModule,
        testModuleStructure: TestModuleStructure
    ): List<TestFile> {
        val fileWithBox = module.files.firstOrNull {
            MainFunctionForBlackBoxTestsSourceProvider.containsBoxMethod(it.originalContent)
        }
        val tracesGenericOwnerCallRoutes =
            System.getProperty(GENERIC_OWNER_CALL_ROUTE_TRACE_EXPORT_PROPERTY) != null
        val representativeSourceIds = module.files.flatMap { file ->
            file.originalContent.lineSequence().mapNotNull { line ->
                line.removePrefix(DOT_NET_REPRESENTATIVE_SOURCE_MARKER)
                    .takeIf { remainder -> remainder != line }
                    ?.trim()
            }.toList()
        }
        check(representativeSourceIds.toSet().size == representativeSourceIds.size) {
            "A .NET representative source was requested more than once: $representativeSourceIds"
        }
        val representativeSources = representativeSourceIds.map { id ->
            checkNotNull(dotNetRepresentativeSources[id]) {
                "Unknown closed .NET representative source '$id'"
            }
        }

        if (fileWithBox == null && representativeSources.isEmpty()) return emptyList()

        val sourceDirectory = testServices.temporaryDirectoryManager.getOrCreateTempDirectory("src")

        return buildList {
            fileWithBox?.let { boxFile ->
                val code = buildString {
                    MainFunctionForBlackBoxTestsSourceProvider.detectPackage(boxFile)?.let {
                        appendLine("package $it")
                        appendLine()
                    }
                    appendLine("import kotlin.io.println")
                    appendLine()
                    if (tracesGenericOwnerCallRoutes) {
                        appendLine("private fun $GENERIC_OWNER_CALL_ROUTE_TRACE_RECORDER_NAME(callSiteIndex: Int) {")
                        appendLine("    // Replaced by the test-only backend counter hook.")
                        appendLine("}")
                        appendLine()
                        appendLine("private fun $GENERIC_OWNER_CALL_ROUTE_TRACE_FLUSHER_NAME() {")
                        appendLine("    // Replaced by the test-only backend counter hook.")
                        appendLine("}")
                        appendLine()
                    }
                    appendLine("fun main() {")
                    if (tracesGenericOwnerCallRoutes) {
                        appendLine("    val result = box()")
                        appendLine("    $GENERIC_OWNER_CALL_ROUTE_TRACE_FLUSHER_NAME()")
                        appendLine("    println(result)")
                    } else {
                        appendLine("    println(box())")
                    }
                    appendLine("}")
                }
                val mainFile = sourceDirectory
                    .resolve(MainFunctionForBlackBoxTestsSourceProvider.BOX_MAIN_FILE_NAME)
                mainFile.writeText(code)
                add(mainFile.toTestFile())
            }
            if (representativeSources.isNotEmpty()) {
                val originalTestData = testModuleStructure.originalTestDataFiles.single()
                val repositoryRoot = generateSequence(originalTestData.canonicalFile.parentFile, File::getParentFile)
                    .firstOrNull { candidate ->
                        candidate.resolve("kotlin-native").isDirectory && candidate.resolve("compiler").isDirectory
                    }
                    ?: error("Cannot locate the repository root from ${originalTestData.path}")
                representativeSources.forEach { representativeSource ->
                    val source = repositoryRoot.resolve(representativeSource.repositoryPath).canonicalFile
                    check(source.isFile && source.path.startsWith(repositoryRoot.canonicalPath + File.separator)) {
                        "The closed .NET representative source is missing or escaped the repository: $source"
                    }
                    val stagedSource = sourceDirectory.resolve(representativeSource.outputFileName)
                    check(!stagedSource.exists()) {
                        "Two .NET representative sources selected the same staged file: $stagedSource"
                    }
                    source.copyTo(stagedSource)
                    add(stagedSource.toTestFile())
                }
                if (representativeSources.any(DotNetRepresentativeSource::requiresBenchmarkStubs)) {
                    val benchmarkStubs = sourceDirectory.resolve("DotNetRepresentativeBenchmarkStubs.kt")
                    benchmarkStubs.writeText(
                        """
                        package kotlinx.benchmark

                        public enum class Scope { Benchmark }

                        public enum class BenchmarkTimeUnit { SECONDS, MILLISECONDS }

                        public annotation class State(val scope: Scope)

                        public annotation class Measurement(
                            val time: Int,
                            val timeUnit: BenchmarkTimeUnit,
                        )

                        public annotation class Benchmark

                        public class Blackhole {
                            public fun consume(value: Any?) {
                                if (value === this) throw AssertionError("recursive blackhole value")
                            }
                        }
                        """.trimIndent()
                    )
                    add(benchmarkStubs.toTestFile())
                    val launcherStubs = sourceDirectory.resolve("DotNetRepresentativeLauncherStubs.kt")
                    launcherStubs.writeText(
                        """
                        package org.jetbrains.benchmarksLauncher

                        public annotation class SkipWhenBaseOnly
                        """.trimIndent()
                    )
                    add(launcherStubs.toTestFile())
                }
            }
            if (module.files.any { source -> "kotlin.test" in source.originalContent }) {
                val assertions = sourceDirectory.resolve("DotNetTestAssertions.kt")
                assertions.writeText(
                    """
                    package kotlin.test

                    public fun <T> assertEquals(expected: T, actual: T, message: String? = null) {
                        if (expected != actual) {
                            throw AssertionError(message ?: "Expected <${'$'}expected>, actual <${'$'}actual>.")
                        }
                    }

                    public fun <T> assertNotEquals(illegal: T, actual: T, message: String? = null) {
                        if (illegal == actual) {
                            throw AssertionError(message ?: "Illegal value: <${'$'}actual>.")
                        }
                    }

                    public fun assertTrue(actual: Boolean, message: String? = null) {
                        if (!actual) throw AssertionError(message ?: "Expected value to be true.")
                    }

                    public fun assertFalse(actual: Boolean, message: String? = null) {
                        if (actual) throw AssertionError(message ?: "Expected value to be false.")
                    }
                    """.trimIndent()
                )
                add(assertions.toTestFile())
            }
            if (module.files.any { source ->
                    "substringAfterLast(" in source.originalContent || ".endsWith(" in source.originalContent
                }
            ) {
                // Transitional test-only floor: these helpers let the unchanged upstream
                // reflection corpus assert names without making an unrelated String stdlib
                // expansion part of the KType feature. Product sources remain untouched.
                val textAssertions = sourceDirectory.resolve("DotNetTestTextAssertions.kt")
                textAssertions.writeText(
                    """
                    package kotlin.text

                    public fun String.substringAfterLast(
                        delimiter: Char,
                        missingDelimiterValue: String = this,
                    ): String {
                        var index = length - 1
                        while (index >= 0) {
                            if (this[index] == delimiter) {
                                val result = StringBuilder()
                                var resultIndex = index + 1
                                while (resultIndex < length) {
                                    result.append(this[resultIndex])
                                    resultIndex += 1
                                }
                                return result.toString()
                            }
                            index -= 1
                        }
                        return missingDelimiterValue
                    }

                    public fun String.endsWith(suffix: String, ignoreCase: Boolean = false): Boolean {
                        if (ignoreCase) throw UnsupportedOperationException("ignoreCase test helper is not implemented")
                        if (suffix.length > length) return false
                        val offset = length - suffix.length
                        var index = 0
                        while (index < suffix.length) {
                            if (this[offset + index] != suffix[index]) return false
                            index += 1
                        }
                        return true
                    }
                    """.trimIndent()
                )
                add(textAssertions.toTestFile())
            }
        }
    }
}

private class DotNetBoxRunner(testServices: TestServices) :
    AbstractDotNetBoxRunner(testServices, DotNetTarget.NET10_0)

private class DotNetFrameworkBoxRunner(testServices: TestServices) :
    AbstractDotNetBoxRunner(testServices, DotNetTarget.NET48)

private abstract class AbstractDotNetBoxRunner(
    private val dotNetTestServices: TestServices,
    private val target: DotNetTarget,
) : DotNetBinaryArtifactHandler(dotNetTestServices) {
    private var boxMethodFound = false

    override fun processModule(module: TestModule, info: BinaryArtifacts.DotNet) {
        if (module.files.none { MainFunctionForBlackBoxTestsSourceProvider.containsBoxMethod(it.originalContent) }) return

        boxMethodFound = true
        stageRuntimeDependencies(module, info.outputFile)
        val producesStdlibFromSource = DotNetCodegenDirectives.DOTNET_STDLIB_FROM_SOURCE in module.directives
        val executionOutput = runExecutable(info.outputFile, producesStdlibFromSource)
        val result = System.getProperty(GENERIC_OWNER_CALL_ROUTE_TRACE_EXPORT_PROPERTY)?.let { exportPath ->
            captureGenericOwnerCallRouteTrace(executionOutput, info.outputFile, File(exportPath))
        } ?: executionOutput.trim()
        val outputFile = testServices.moduleStructure.originalTestDataFiles.first().withExtension(OUTPUT_EXTENSION)
        if (outputFile.exists()) {
            assertions.assertEqualsToFile(outputFile, result)
        } else {
            assertions.assertEquals(DEFAULT_EXPECTED_RESULT, result)
        }
    }

    private fun captureGenericOwnerCallRouteTrace(
        executionOutput: String,
        instrumentedAssembly: File,
        exportDirectory: File,
    ): String {
        check(exportDirectory.isDirectory) {
            "The generic-owner trace export directory was not prepared: $exportDirectory"
        }
        val routeManifest = exportDirectory.resolve(GENERIC_OWNER_CALL_ROUTE_MANIFEST_FILE)
        check(exportDirectory.listFiles()?.map(File::getName) == listOf(GENERIC_OWNER_CALL_ROUTE_MANIFEST_FILE) &&
                routeManifest.isFile) {
            "The generic-owner trace must join one compiler-exported route manifest before execution"
        }
        val encodedRouteManifest = checkNotNull(
            genericOwnerCallRouteTraceManifests.remove(genericOwnerCallRouteTraceKey(exportDirectory)),
        ) {
            "The generic-owner trace lacks its process-local canonical route manifest"
        }
        val routeLines = encodedRouteManifest.trimEnd('\r', '\n').lines()
        check(routeLines.firstOrNull() ==
                "kotlin-dotnet-generic-owner-call-routes\t${DotNetGenericOwnerCallRouteManifestCodec.SCHEMA_VERSION}") {
            "The generic-owner trace received a stale call-route manifest"
        }
        val routeCount = routeLines.getOrNull(1)?.split('\t')?.let { fields ->
            fields.takeIf { it.size == 2 && it[0] == "N" }?.get(1)?.toIntOrNull()
        }
        check(routeCount != null && routeCount > 0 && routeLines.size == routeCount + 2) {
            "The generic-owner trace received an invalid call-route count"
        }
        val producerSiteIndices = routeLines.drop(2).map { line ->
            val fields = line.split('\t')
            check(fields.size == 7 && fields[0] == "R") {
                "The generic-owner trace received a malformed route record"
            }
            checkNotNull(fields[1].toIntOrNull()?.takeIf { index -> index >= 0 }) {
                "The generic-owner trace received an invalid compiler call-site index"
            }
        }
        check(producerSiteIndices == producerSiteIndices.sorted() &&
                producerSiteIndices.toSet().size == producerSiteIndices.size) {
            "The generic-owner trace received duplicate or unordered call-site indices"
        }

        val eventCounts = linkedMapOf<Int, Long>()
        val applicationOutput = mutableListOf<String>()
        executionOutput.trim().lines().forEach { line ->
            if (line.startsWith(DOTNET_GENERIC_OWNER_CALL_ROUTE_TRACE_PREFIX)) {
                val fields = line.removePrefix(DOTNET_GENERIC_OWNER_CALL_ROUTE_TRACE_PREFIX)
                    .split(DOTNET_GENERIC_OWNER_CALL_ROUTE_TRACE_COUNT_SEPARATOR)
                val callSiteIndex = fields.getOrNull(0)?.toIntOrNull()
                val count = fields.getOrNull(1)?.toLongOrNull()
                check(fields.size == 2 && callSiteIndex != null && callSiteIndex >= 0 && count != null && count > 0L &&
                        eventCounts.put(callSiteIndex, count) == null) {
                    "The instrumented application emitted an invalid generic-owner final counter: '$line'"
                }
            } else {
                applicationOutput += line
            }
        }
        check(eventCounts.isNotEmpty()) { "The instrumented application emitted no generic-owner route events" }

        val routeFingerprint = DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(
            encodedRouteManifest.toByteArray(),
        )
        val encodedCounts = buildString {
            appendLine("kotlin-dotnet-generic-owner-call-route-counts\t1")
            appendLine("R\t$routeFingerprint")
            appendLine("N\t${producerSiteIndices.size}")
            producerSiteIndices.forEach { callSiteIndex ->
                appendLine("C\t$callSiteIndex\t${eventCounts[callSiteIndex] ?: 0L}")
            }
        }
        exportDirectory.resolve(GENERIC_OWNER_CALL_ROUTE_COUNTS_FILE).writeText(encodedCounts)
        val producerEventCount = producerSiteIndices.fold(0L) { total, callSiteIndex ->
            Math.addExact(total, eventCounts[callSiteIndex] ?: 0L)
        }
        val allEventCount = eventCounts.values.fold(0L, Math::addExact)
        val traceManifest = exportDirectory.resolve(GENERIC_OWNER_CALL_ROUTE_TRACE_MANIFEST_FILE).apply {
            writeText(
                """
                schema=2
                targetProfile=${target.name}
                counterProtocol=$GENERIC_OWNER_CALL_ROUTE_TRACE_COUNTER_PROTOCOL
                routeManifestSha256=$routeFingerprint
                countsSha256=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(encodedCounts.toByteArray())}
                instrumentedAssemblySha256=${DotNetGenericOwnerPhysicalFamilyCodec.producerFingerprint(instrumentedAssembly.readBytes())}
                allEventCount=$allEventCount
                producerEventCount=$producerEventCount
                unrelatedEventCount=${allEventCount - producerEventCount}
                """.trimIndent()
            )
        }
        check(exportDirectory.listFiles()?.map(File::getName)?.sorted() == listOf(
            GENERIC_OWNER_CALL_ROUTE_COUNTS_FILE,
            GENERIC_OWNER_CALL_ROUTE_MANIFEST_FILE,
            GENERIC_OWNER_CALL_ROUTE_TRACE_MANIFEST_FILE,
        ).sorted() && traceManifest.isFile) {
            "The generic-owner call-route trace did not produce its exact closed file set"
        }
        return applicationOutput.joinToString("\n").trim()
    }

    override fun processAfterAllModules(someAssertionWasFailed: Boolean) {
        if (!boxMethodFound) {
            assertions.fail { "Can't find box methods" }
        }
    }

    private fun stageRuntimeDependencies(module: TestModule, executable: File) {
        val outputDirectory = executable.parentFile ?: return
        val binaryLibraries = buildList {
            addAll(module.transitiveRegularDependencies(reverseOrder = true) { it.kind == DependencyKind.Binary })
            addAll(module.transitiveFriendDependencies(reverseOrder = true) { it.kind == DependencyKind.Binary })
        }.distinct()
        for (dependencyModule in binaryLibraries) {
            val artifactName = dependencyModule.name.takeUnless { it == "main" }
                ?: dotNetTestServices.moduleStructure.originalTestDataFiles.first().nameWithoutExtension
            val producedAssembly = outputDirectory
                .resolve("${dependencyModule.name}-$artifactName-library")
                .resolve("$artifactName.dll")
            check(producedAssembly.isFile) {
                "Compiled .NET test dependency was not produced: ${producedAssembly.path}"
            }
            val runtimeAssembly = outputDirectory.resolve("$artifactName.dll")
            if (producedAssembly.canonicalFile != runtimeAssembly.canonicalFile) {
                producedAssembly.copyTo(runtimeAssembly, overwrite = true)
            }
        }
    }

    private fun runExecutable(file: File, producesStdlibFromSource: Boolean): String {
        if (!file.isFile) {
            assertions.fail { "Expected .NET assembly was not produced: ${file.path}" }
        }
        val outputDirectory = file.parentFile ?: File(".")
        val runtimeFile = outputDirectory.resolve("Kotlin.Runtime.dll")
        if (!runtimeFile.isFile) {
            assertions.fail { "Expected Kotlin/.NET runtime assembly was not produced: ${runtimeFile.path}" }
        }
        val stdlibFile = outputDirectory.resolve("Kotlin.Stdlib.dll")
        if (!stdlibFile.isFile) {
            assertions.fail { "Expected Kotlin/.NET stdlib assembly was not produced: ${stdlibFile.path}" }
        }
        val stdlibIlFile = outputDirectory.resolve("Kotlin.Stdlib.il")
        val stdlibIlText = stdlibIlFile.takeIf(File::isFile)?.readText().orEmpty().replace("\r\n", "\n")
        if (!producesStdlibFromSource && stdlibIlFile.exists()) {
            assertions.fail { "An ordinary .NET consumer rebuilt Kotlin.Stdlib from source: ${stdlibIlFile.path}" }
        }
        val requiredStdlibIl = listOf(
            ".assembly extern mscorlib {}",
            ".assembly 'Kotlin.Stdlib'\n{\n  .ver 1:0:0:0",
            "System.Runtime.Versioning.TargetFrameworkAttribute",
            ".class private auto ansi sealed beforefieldinit 'Kotlin.Collections.ArrayIterator'",
            ".class private auto ansi sealed beforefieldinit 'Kotlin.Collections.ArrayIterable'",
            ".class private auto ansi sealed beforefieldinit 'Kotlin.Collections.ArrayAsList'",
            ".class public abstract auto ansi beforefieldinit 'Kotlin.Collections.AbstractCollection'",
            ".class public abstract auto ansi beforefieldinit 'Kotlin.Collections.AbstractList'",
            ".class public abstract sealed auto ansi beforefieldinit 'Kotlin.Collections.CollectionsKt'",
            "'Kotlin.Collections.EmptyIterator'",
            "'Kotlin.Collections.EmptyList'",
            ".class interface public abstract auto ansi 'Kotlin.Collections.RandomAccess'",
            ".class interface public abstract auto ansi 'Kotlin.Text.Appendable'",
            ".class public auto ansi sealed beforefieldinit 'Kotlin.Text.StringBuilder'",
            ".class public abstract sealed auto ansi beforefieldinit 'Kotlin.Text.StringsKt'",
            ".class public auto ansi sealed beforefieldinit 'Kotlin.NotImplementedError'",
            ".method public hidebysig static class [Kotlin.Runtime]'Kotlin.Collections.List' " +
                    "'emptyList'<'T'>()",
            ".method public hidebysig static class [Kotlin.Runtime]'Kotlin.Collections.List' " +
                    "'asList'<'T'>(class [mscorlib]System.Array '<this>')",
            ".method public hidebysig static bool 'any'<'T'>(" +
                    "class [Kotlin.Runtime]'Kotlin.Collections.Iterable' '<this>')",
            ".method public hidebysig specialname static int32 'get_lastIndex'<'T'>(" +
                    "class [Kotlin.Runtime]'Kotlin.Collections.List' '<this>')",
            ".method public hidebysig static object 'firstOrNull'<'T'>(" +
                    "class [Kotlin.Runtime]'Kotlin.Collections.Iterable' '<this>')",
            ".method public hidebysig static object 'lastOrNull'<'T'>(" +
                    "class [Kotlin.Runtime]'Kotlin.Collections.List' '<this>')",
            ".method public hidebysig static bool 'none'<'T'>(" +
                    "class [Kotlin.Runtime]'Kotlin.Collections.Iterable' '<this>')",
            ".method public hidebysig static !!0 'single'<'T'>(" +
                    "class [Kotlin.Runtime]'Kotlin.Collections.List' '<this>')",
            ".method public hidebysig static object 'singleOrNull'<'T'>(" +
                    "class [Kotlin.Runtime]'Kotlin.Collections.Iterable' '<this>')",
        )
        if (producesStdlibFromSource) {
            requiredStdlibIl.firstOrNull { it !in stdlibIlText }?.let { missing ->
                assertions.fail { "Expected Kotlin.Stdlib IL to contain '$missing': ${stdlibIlFile.path}" }
            }
            if ("Kotlin.Collections.CollectionsKt1" in stdlibIlText) {
                assertions.fail {
                    "Compiler-owned collection source shards must share Kotlin.Collections.CollectionsKt: " +
                            stdlibIlFile.path
                }
            }
            if (".assembly extern Kotlin.Stdlib" in stdlibIlText) {
                assertions.fail { "Kotlin.Stdlib must not carry an AssemblyRef to itself: ${stdlibIlFile.path}" }
            }
            if ("[netstandard]" in stdlibIlText) {
                assertions.fail { "The box stdlib must use the selected $target API profile: ${stdlibIlFile.path}" }
            }
            val arrayJoinToSignature =
                ".method public hidebysig static !!1 'joinTo'<'T', " +
                        "(class 'Kotlin.Text.Appendable') 'A'>(class [${target.coreLibraryAssemblyName}]" +
                        "System.Array '<this>'"
            val arrayJoinToDefaultSignature =
                ".method public hidebysig static !!1 'joinTo\$default'<'T', "
            val arrayJoinToStart = stdlibIlText.indexOf(arrayJoinToSignature)
            val arrayJoinToEnd = stdlibIlText.indexOf(arrayJoinToDefaultSignature, arrayJoinToStart + 1)
            if (arrayJoinToStart < 0 || arrayJoinToEnd <= arrayJoinToStart) {
                assertions.fail { "Cannot isolate the generic array joinTo body: ${stdlibIlFile.path}" }
            }
            val arrayJoinToBody = stdlibIlText.substring(arrayJoinToStart, arrayJoinToEnd)
            listOf(
                "isinst !!0[]",
                "ldelem !!0",
                "callvirt instance object [${target.coreLibraryAssemblyName}]System.Array::GetValue(int32)",
            ).firstOrNull { required -> required !in arrayJoinToBody }?.let { missing ->
                assertions.fail { "Generic array joinTo lacks '$missing': ${stdlibIlFile.path}" }
            }
            if ("dotNetExactArrayOrNull" in stdlibIlText || "dotNetJoinToExact" in stdlibIlText) {
                assertions.fail { "A generic-array join optimization helper leaked into CLR metadata: ${stdlibIlFile.path}" }
            }
        }
        val ilFile = outputDirectory.resolve("${file.nameWithoutExtension}.il")
        val ilText = ilFile.takeIf(File::isFile)?.readText().orEmpty()

        if (".assembly extern Kotlin.Runtime" !in ilText || ".ver 1:0:0:0" !in ilText) {
            assertions.fail { "Expected .NET assembly to reference Kotlin.Runtime: ${ilFile.path}" }
        }

        val command = when (target) {
            DotNetTarget.NET10_0 -> {
                // Modern boxes are dlls launched through the signed dotnet host.
                val dotnetHost = DotNetIlAssembler.findModernDotNetHost() ?: assertions.fail {
                    "No modern 'dotnet' host found even though the toolchain assumption passed; " +
                            "provision with compiler/ir/backend.dotnet/tools/provision-dotnet-toolchain.ps1"
                }
                listOf(dotnetHost.absolutePath, "exec", file.absolutePath)
            }
            DotNetTarget.NET48 -> {
                // Framework boxes are loaded by the signed Windows PowerShell CLR 4 host. This
                // invokes the exact managed entry point without directly activating an unsigned exe.
                val frameworkHost = DotNetIlAssembler.findFrameworkPowerShellHost() ?: assertions.fail {
                    "No Windows PowerShell CLR 4 host found even though the toolchain assumption passed"
                }
                frameworkExecutionCommand(frameworkHost, file)
            }
            DotNetTarget.NETSTANDARD_2_0 -> assertions.fail {
                "The library-only netstandard2.0 profile cannot execute box tests"
            }
        }

        // Windows Smart App Control makes a per-file cloud-reputation call the first time the CLR
        // loads a freshly assembled unsigned assembly and fails-closed on a negative verdict
        // (FileLoadException, HRESULT 0x800711C7). A signed host avoids direct unsigned-executable
        // activation, but it cannot override a block on mapping the managed assembly itself.
        // Measured: the verdict is a function of the assembly CONTENT, not just its hash, so for an
        // affected test program the block is deterministic and re-running never clears it. We
        // retry to absorb a genuinely in-flight verdict, then abort the test as SKIPPED with a diagnostic
        // that names SAC: like a missing toolchain, a host that refuses to load the assembly is an
        // environment that cannot execute the test — the test still runs everywhere SAC is not
        // enforced. Skipping (visible in reports) is not a reputation bypass; rewriting the test
        // or perturbing artifact hashes to dodge the classifier would be, and is out of bounds.
        // See 'Box tests' in compiler/ir/backend.dotnet/AGENTS.md.
        var lastBlockedMessage: String? = null
        repeat(SAC_MAX_ATTEMPTS) {
            val execution = execManaged(command, file)
            val exitCode = execution.first
            val output = execution.second
            if (exitCode == 0) return output
            if (!isSmartAppControlBlock(output)) {
                assertions.fail {
                    ".NET executable failed with exit code $exitCode${output.takeIf(String::isNotBlank)?.let { ": $it" }.orEmpty()}"
                }
            }
            lastBlockedMessage = output
            Thread.sleep(SAC_RETRY_DELAY_MS)
        }
        val blockedMessage =
            "Windows Smart App Control blocked loading the assembled test on all $SAC_MAX_ATTEMPTS " +
                    "attempts: ${file.path}\n" +
                    "The SmartScreen verdict is content-derived and can be deterministically negative for a " +
                    "specific test program (measured: the same IL reassembled under a fresh hash is blocked " +
                    "again), so re-running may not help. The test executes on hosts without Smart App Control; " +
                    "to run it here, sign the test assemblies with a reputable certificate or turn SAC off " +
                    "(SAC has no per-file/per-directory exclusions).\n" +
                    "Last output: $lastBlockedMessage"
        if (dotNetToolchainIsRequired()) {
            assertions.fail { "$blockedMessage\nKOTLIN_DOTNET_REQUIRE_TOOLCHAIN is enabled, so execution may not be skipped." }
        }
        throw TestAbortedException(blockedMessage)
    }

    private fun execManaged(command: List<String>, artifact: File): Pair<Int, String> {
        val process = ProcessBuilder(command)
            .directory(artifact.parentFile)
            .redirectErrorStream(true)
            .start()
        if (!process.waitFor(3, TimeUnit.MINUTES)) {
            process.destroyForcibly()
            assertions.fail { ".NET executable timed out: ${artifact.path}" }
        }
        return process.exitValue() to process.inputStream.bufferedReader().readText()
    }

    private fun frameworkExecutionCommand(host: File, assembly: File): List<String> {
        val escapedAssemblyPath = assembly.absolutePath.replace("'", "''")
        val command = """
            ${'$'}ErrorActionPreference = 'Stop'
            try {
                ${'$'}assembly = [Reflection.Assembly]::LoadFrom('$escapedAssemblyPath')
                ${'$'}entryPoint = ${'$'}assembly.EntryPoint
                if (${'$'}null -eq ${'$'}entryPoint) { throw 'Assembly has no managed entry point.' }
                if (${'$'}entryPoint.GetParameters().Count -eq 0) {
                    [void] ${'$'}entryPoint.Invoke(${'$'}null, ${'$'}null)
                } else {
                    [void] ${'$'}entryPoint.Invoke(${'$'}null, [object[]] @(,[string[]] @()))
                }
            } catch {
                [Console]::Error.WriteLine(${'$'}_.Exception.ToString())
                exit 1
            }
        """.trimIndent()
        return listOf(host.path, "-NoLogo", "-NoProfile", "-NonInteractive", "-Command", command)
    }

    /**
     * `0x800711C7` is `ERROR_SYSTEM_INTEGRITY_POLICY_VIOLATION` as an HRESULT — the exact code the
     * CLR's `System.IO.FileLoadException` carries when Code Integrity (Smart App Control) refuses
     * to map the assembly. The prose is matched as a fallback for host-level block messages.
     */
    private fun isSmartAppControlBlock(output: String): Boolean =
        output.contains("0x800711C7") || output.contains("Application Control policy has blocked this file")

    private companion object {
        const val DEFAULT_EXPECTED_RESULT = "OK"
        const val OUTPUT_EXTENSION = "box.txt"
        const val SAC_MAX_ATTEMPTS = 3
        const val SAC_RETRY_DELAY_MS = 1_000L
    }
}

private fun dotNetToolchainIsRequired(): Boolean =
    System.getenv("KOTLIN_DOTNET_REQUIRE_TOOLCHAIN")?.let { value ->
        value == "1" || value.equals("true", ignoreCase = true)
    } == true
